import { acquireLock, DEFAULT_LOCK_STALE_MS, resolveLockPath, resolveStatePath } from "../../../scripts/auto-update-state.mjs";

export type InstallFlow = "npx-local" | "marketplace" | "unknown";

export type ConfigSourceSignal = "npx-local" | "marketplace" | "unparsable";

export interface DetectInstallFlowOptions {
	readonly pluginRoot: string;
	readonly configToml?: string;
	readonly marketplaceName?: string;
}

export interface InstallFlowDetection {
	readonly flow: InstallFlow;
	readonly snapshotPresent: boolean;
	readonly configSource: string | undefined;
	readonly configSignal: ConfigSourceSignal | undefined;
	readonly reason: string;
}

export const INSTALL_SNAPSHOT_FILENAME = "lazycodex-install.json";

const DEFAULT_MARKETPLACE_NAME = "sisyphuslabs";
const MAX_CODEX_HOME_WALK_UP_LEVELS = 6;

export async function detectInstallFlowDetailed(options: DetectInstallFlowOptions): Promise<InstallFlowDetection> {
	const marketplaceName = options.marketplaceName ?? DEFAULT_MARKETPLACE_NAME;
	const snapshotPresent = await isFile(join(options.pluginRoot, INSTALL_SNAPSHOT_FILENAME));
	const snapshotSignal: InstallFlow = snapshotPresent ? "npx-local" : "marketplace";
	const snapshotReason = snapshotPresent
		? `${INSTALL_SNAPSHOT_FILENAME} present at plugin root (written only by the npx installer)`
		: `${INSTALL_SNAPSHOT_FILENAME} absent from plugin root`;
	const scan = options.configToml === undefined ? { kind: "absent" as const } : scanMarketplaceSource(options.configToml, marketplaceName);

	if (scan.kind === "absent") {
		return {
			configSignal: undefined,
			configSource: undefined,
			flow: snapshotSignal,
			reason: `${snapshotReason}; no [marketplaces.${marketplaceName}] source to cross-check`,
			snapshotPresent,
		};
	}
	if (scan.kind === "unparsable") {
		return {
			configSignal: "unparsable",
			configSource: undefined,
			flow: "unknown",
			reason: `${snapshotReason}; [marketplaces.${marketplaceName}] source value is unparsable`,
			snapshotPresent,
		};
	}
	const configSignal = classifyMarketplaceSource(scan.source);
	if (configSignal === "unparsable") {
		return {
			configSignal,
			configSource: scan.source,
			flow: "unknown",
			reason: `${snapshotReason}; marketplace source ${JSON.stringify(scan.source)} is neither a local absolute path nor a git URL`,
			snapshotPresent,
		};
	}
	if (configSignal !== snapshotSignal) {
		return {
			configSignal,
			configSource: scan.source,
			flow: "unknown",
			reason: `${snapshotReason}, but marketplace source ${JSON.stringify(scan.source)} indicates ${configSignal}; signals disagree`,
			snapshotPresent,
		};
	}
	return {
		configSignal,
		configSource: scan.source,
		flow: snapshotSignal,
		reason: `${snapshotReason}; marketplace source ${JSON.stringify(scan.source)} agrees`,
		snapshotPresent,
	};
}

export async function detectInstallFlow(options: DetectInstallFlowOptions): Promise<InstallFlow> {
	return (await detectInstallFlowDetailed(options)).flow;
}

export interface DetectInstallFlowFromEnvironmentOptions {
	readonly pluginRoot: string;
	readonly env: Record<string, string | undefined>;
	readonly marketplaceName?: string;
}

export async function detectInstallFlowFromEnvironment(
	options: DetectInstallFlowFromEnvironmentOptions,
): Promise<InstallFlowDetection> {
	const home = await resolveCodexHome({ env: options.env, pluginRoot: options.pluginRoot });
	const configToml = await readOptionalFile(join(home.path, "config.toml"));
	return detectInstallFlowDetailed({
		pluginRoot: options.pluginRoot,
		...(configToml === undefined ? {} : { configToml }),
		...(options.marketplaceName === undefined ? {} : { marketplaceName: options.marketplaceName }),
	});
}

export async function detectInstallFlowForTest(pluginRoot: string): Promise<InstallFlow> {
	const home = await resolveCodexHome({ env: {}, pluginRoot });
	const configToml = home.source === "walk-up" ? await readOptionalFile(join(home.path, "config.toml")) : undefined;
	return detectInstallFlow({ pluginRoot, ...(configToml === undefined ? {} : { configToml }) });
}

export type CodexHomeSource = "env" | "walk-up" | "default";

export interface CodexHomeResolution {
	readonly path: string;
	readonly source: CodexHomeSource;
}

export interface ResolveCodexHomeOptions {
	readonly env: Record<string, string | undefined>;
	readonly pluginRoot?: string;
}

export async function resolveCodexHome(options: ResolveCodexHomeOptions): Promise<CodexHomeResolution> {
	const envHome = options.env["CODEX_HOME"]?.trim();
	if (envHome !== undefined && envHome.length > 0) {
		return { path: resolve(envHome), source: "env" };
	}
	if (options.pluginRoot !== undefined) {
		let current = resolve(options.pluginRoot);
		for (let level = 0; level < MAX_CODEX_HOME_WALK_UP_LEVELS; level += 1) {
			const parent = dirname(current);
			if (parent === current) break;
			current = parent;
			if (await isFile(join(current, "config.toml"))) {
				return { path: current, source: "walk-up" };
			}
		}
	}
	return { path: join(homedir(), ".codex"), source: "default" };
}

export interface BootstrapLocksOptions {
	readonly pluginData: string;
	readonly env: Record<string, string | undefined>;
	readonly now?: number;
	readonly staleMs?: number;
}

export interface BootstrapLockHandle {
	readonly statePath: string;
	readonly bootstrapLockPath: string;
	readonly autoUpdateLockPath: string;
	readonly release: () => Promise<void>;
}

export function resolveBootstrapStatePath(pluginData: string): string {
	return join(pluginData, "bootstrap", "state.json");
}

export function resolveBootstrapLockPath(pluginData: string): string {
	return `${resolveBootstrapStatePath(pluginData)}.lock`;
}

export async function bootstrapLocks(options: BootstrapLocksOptions): Promise<BootstrapLockHandle | null> {
	const now = options.now ?? Date.now();
	const staleMs = options.staleMs ?? DEFAULT_LOCK_STALE_MS;
	const statePath = resolveBootstrapStatePath(options.pluginData);
	const bootstrapLockPath = resolveBootstrapLockPath(options.pluginData);
	const autoUpdateLockPath = resolveLockPath(options.env, resolveStatePath(options.env));

	const bootstrapLock = await acquireLock(bootstrapLockPath, now, staleMs);
	if (bootstrapLock === null) return null;
	if (autoUpdateLockPath === bootstrapLockPath) {
		return { autoUpdateLockPath, bootstrapLockPath, release: () => bootstrapLock.release(), statePath };
	}
	const autoUpdateLock = await acquireLock(autoUpdateLockPath, now, staleMs);
	if (autoUpdateLock === null) {
		await bootstrapLock.release();
		return null;
	}
	return {
		autoUpdateLockPath,
		bootstrapLockPath,
		release: async () => {
			await autoUpdateLock.release();
			await bootstrapLock.release();
		},
		statePath,
	};
}

type MarketplaceSourceScan = { readonly kind: "absent" } | { readonly kind: "unparsable" } | { readonly kind: "source"; readonly source: string };

function scanMarketplaceSource(configToml: string, marketplaceName: string): MarketplaceSourceScan {
	const expectedHeaders = new Set([`marketplaces.${marketplaceName}`, `marketplaces.${JSON.stringify(marketplaceName)}`]);
	let inMarketplaceSection = false;
	for (const line of configToml.split("\n")) {
		const header = parseTomlHeader(line);
		if (header !== null) {
			inMarketplaceSection = expectedHeaders.has(header);
			continue;
		}
		if (!inMarketplaceSection) continue;
		const valueText = parseSourceAssignment(line);
		if (valueText === null) continue;
		const source = parseTomlStringValue(valueText);
		return source === undefined ? { kind: "unparsable" } : { kind: "source", source };
	}
	return { kind: "absent" };
}

function parseTomlHeader(line: string): string | null {
	const trimmed = line.trim();
	if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return null;
	if (trimmed.startsWith("[[")) return null;
	return trimmed.slice(1, -1).trim();
}

function parseSourceAssignment(line: string): string | null {
	const match = /^\s*source\s*=\s*(.+)$/.exec(line);
	return match === null ? null : (match[1] ?? null);
}

function parseTomlStringValue(valueText: string): string | undefined {
	const trimmed = valueText.trim();
	if (trimmed.startsWith('"')) return parseLeadingJsonString(trimmed);
	if (trimmed.startsWith("'")) {
		const closingIndex = trimmed.indexOf("'", 1);
		return closingIndex === -1 ? undefined : trimmed.slice(1, closingIndex);
	}
	return undefined;
}

function parseLeadingJsonString(value: string): string | undefined {
	let escaped = false;
	for (let index = 1; index < value.length; index += 1) {
		if (escaped) {
			escaped = false;
			continue;
		}
		const char = value[index];
		if (char === "\\") {
			escaped = true;
			continue;
		}
		if (char === '"') {
			try {
				const parsed: unknown = JSON.parse(value.slice(0, index + 1));
				return typeof parsed === "string" ? parsed : undefined;
			} catch {
				return undefined;
			}
		}
	}
	return undefined;
}

function classifyMarketplaceSource(source: string): ConfigSourceSignal {
	const trimmed = source.trim();
	if (trimmed.length === 0) return "unparsable";
	if (/^(https?|ssh|git):\/\//i.test(trimmed) || trimmed.startsWith("git@")) return "marketplace";
	if (trimmed.startsWith("/") || trimmed.startsWith("~") || trimmed.startsWith("\\\\") || /^[A-Za-z]:[\\/]/.test(trimmed)) {
		return "npx-local";
	}
	if (trimmed.toLowerCase().endsWith(".git")) return "marketplace";
	return "unparsable";
}

async function isFile(path: string): Promise<boolean> {
	try {
		return (await stat(path)).isFile();
	} catch {
		return false;
	}
}

async function readOptionalFile(path: string): Promise<string | undefined> {
	try {
		return await readFile(path, "utf8");
	} catch {
		return undefined;
	}
}

import { spawn } from "node:child_process";
import { stat } from "node:fs/promises";
import type { Readable } from "node:stream";
import { fileURLToPath } from "node:url";

import { DEFAULT_LOCK_STALE_MS } from "../../../scripts/auto-update-state.mjs";
import { resolveBootstrapLockPath, resolveBootstrapStatePath } from "./environment.ts";
import { readBootstrapState, readPluginVersion } from "./worker.ts";

export const BOOTSTRAP_RESTART_NOTICE =
	"LazyCodex bootstrap running in background — restart the session when it completes";

export type SessionStartAction =
	| "spawned"
	| "skip-completed"
	| "skip-locked"
	| "skip-missing-env"
	| "skip-version-unresolved";

export interface WorkerSpawnInvocation {
	readonly command: string;
	readonly args: readonly string[];
	readonly env: Record<string, string | undefined>;
}

export interface SessionStartHookOptions {
	readonly env: Record<string, string | undefined>;
	readonly stdin?: Readable & { readonly isTTY?: boolean };
	readonly now?: number;
	readonly spawnWorker?: (invocation: WorkerSpawnInvocation) => void;
	readonly workerCliPath?: string;
	readonly writeNotice?: (line: string) => void;
}

export interface SessionStartHookResult {
	readonly exitCode: 0;
	readonly action: SessionStartAction;
}

export async function runSessionStartHook(options: SessionStartHookOptions): Promise<number> {
	return (await executeSessionStartHook(options)).exitCode;
}

export async function executeSessionStartHook(options: SessionStartHookOptions): Promise<SessionStartHookResult> {
	if (options.stdin !== undefined) await drainStdin(options.stdin);
	const now = options.now ?? Date.now();
	const pluginRoot = options.env["PLUGIN_ROOT"]?.trim();
	const pluginData = options.env["PLUGIN_DATA"]?.trim();
	if (pluginRoot === undefined || pluginRoot.length === 0 || pluginData === undefined || pluginData.length === 0) {
		return { action: "skip-missing-env", exitCode: 0 };
	}

	const pluginVersion = await readPluginVersion(pluginRoot);
	if (pluginVersion === undefined) return { action: "skip-version-unresolved", exitCode: 0 };

	const state = await readBootstrapState(resolveBootstrapStatePath(pluginData));
	if (state.completedForVersion === pluginVersion) return { action: "skip-completed", exitCode: 0 };

	if (await isLockFresh(resolveBootstrapLockPath(pluginData), now)) return { action: "skip-locked", exitCode: 0 };

	const spawnWorker = options.spawnWorker ?? spawnDetachedWorker;
	spawnWorker({
		args: [options.workerCliPath ?? defaultWorkerCliPath(), "worker"],
		command: process.execPath,
		env: options.env,
	});
	const writeNotice = options.writeNotice ?? ((line: string) => process.stdout.write(`${line}\n`));
	writeNotice(
		JSON.stringify({
			hookSpecificOutput: {
				hookEventName: "SessionStart",
				additionalContext: BOOTSTRAP_RESTART_NOTICE,
			},
		}),
	);
	return { action: "spawned", exitCode: 0 };
}

function spawnDetachedWorker(invocation: WorkerSpawnInvocation): void {
	const child = spawn(invocation.command, [...invocation.args], {
		detached: true,
		env: invocation.env,
		stdio: "ignore",
	});
	child.unref();
}

function defaultWorkerCliPath(): string {
	// In the esbuild bundle every module shares import.meta.url, so this
	// resolves to dist/cli.js — the file the detached worker must re-enter.
	return fileURLToPath(import.meta.url);
}

async function isLockFresh(lockPath: string, now: number): Promise<boolean> {
	try {
		const lockStat = await stat(lockPath);
		return now - lockStat.mtimeMs < DEFAULT_LOCK_STALE_MS;
	} catch {
		return false;
	}
}

async function drainStdin(stdin: NonNullable<SessionStartHookOptions["stdin"]>): Promise<void> {
	if (stdin.isTTY === true) return;
	for await (const chunk of stdin) {
		void chunk;
	}
}

import { execFile } from "node:child_process";
import { rm } from "node:fs/promises";
import { dirname, join } from "node:path";
import { promisify } from "node:util";

import {
	findSgBinarySync,
	provisionSgBinary,
	runtimeSlug,
	SG_PINNED_VERSION,
	sgBinaryName,
	type SgFetch,
	type SgManifestAsset,
	type SgRuntimeSlug,
} from "../../../../../utils/src/ast-grep/index.ts";
import { appendBootstrapLog, BOOTSTRAP_DOCTOR_HINT } from "./worker.ts";
import type { BootstrapStepOutcome, BootstrapWorkerContext } from "./worker.ts";

export const SG_PROVISION_COMPONENT = "ast_grep";
export const SG_FORCE_PROVISION_ENV_KEY = "OMO_BOOTSTRAP_FORCE_PROVISION";

export interface ResolvePreexistingSgOptions {
	readonly arch: string;
	readonly codexHome: string;
	readonly env: Record<string, string | undefined>;
	readonly platform: NodeJS.Platform;
}

export interface SgProvisionSeams {
	readonly arch?: string;
	readonly fetchImpl?: SgFetch;
	readonly releaseAssets?: Partial<Record<SgRuntimeSlug, SgManifestAsset>>;
	readonly resolvePreexistingSg?: (options: ResolvePreexistingSgOptions) => string | null;
	readonly runVersionProbe?: (binaryPath: string) => Promise<string>;
}

export function sgProvisionDestination(context: BootstrapWorkerContext, arch: string): string {
	return join(sgRuntimeDir(context.codexHome, context.platform, arch), sgBinaryName(context.platform));
}

function sgRuntimeDir(codexHome: string, platform: NodeJS.Platform, arch: string): string {
	return join(codexHome, "runtime", "ast-grep", runtimeSlug(platform, arch));
}

export async function runSgProvision(
	context: BootstrapWorkerContext,
	seams: SgProvisionSeams = {},
): Promise<BootstrapStepOutcome> {
	const arch = seams.arch ?? process.arch;
	const destination = sgProvisionDestination(context, arch);

	if (context.env[SG_FORCE_PROVISION_ENV_KEY] !== "1") {
		const preexisting = (seams.resolvePreexistingSg ?? defaultResolvePreexistingSg)({
			arch,
			codexHome: context.codexHome,
			env: context.env,
			platform: context.platform,
		});
		if (preexisting !== null) {
			await appendBootstrapLog(context.pluginData, context.now, "sg-provision", { sg: `preexisting:${preexisting}` });
			return { degraded: [] };
		}
	}

	try {
		const version = await provisionFromSharedManifest(context, seams, { arch, destination });
		await appendBootstrapLog(context.pluginData, context.now, "sg-provision", {
			sg: `provisioned:${destination}`,
			version,
		});
		return { degraded: [] };
	} catch (error) {
		const reason = error instanceof Error ? error.message : String(error);
		await appendBootstrapLog(context.pluginData, context.now, "sg-provision-failed", { reason });
		return { degraded: [{ component: SG_PROVISION_COMPONENT, hint: BOOTSTRAP_DOCTOR_HINT, reason }] };
	}
}

async function provisionFromSharedManifest(
	context: BootstrapWorkerContext,
	seams: SgProvisionSeams,
	layout: { readonly arch: string; readonly destination: string },
): Promise<string> {
	const provisionedPath = await provisionSgBinary({
		arch: layout.arch,
		platform: context.platform,
		targetDir: dirname(layout.destination),
		...(seams.fetchImpl === undefined ? {} : { fetchImpl: seams.fetchImpl }),
		...(seams.releaseAssets === undefined ? {} : { releaseAssets: seams.releaseAssets }),
	});
	if (provisionedPath !== layout.destination) {
		await rm(provisionedPath, { force: true });
		throw new Error(`provisioned sg at ${provisionedPath} but expected ${layout.destination}; removed the binary.`);
	}
	await verifyProvisionedVersion(layout.destination, SG_PINNED_VERSION, seams);
	return SG_PINNED_VERSION;
}

async function verifyProvisionedVersion(
	destination: string,
	pinnedVersion: string,
	seams: SgProvisionSeams,
): Promise<void> {
	let reported: string;
	try {
		reported = (await (seams.runVersionProbe ?? defaultVersionProbe)(destination)).trim();
	} catch (error) {
		await rm(destination, { force: true });
		throw new Error(
			`provisioned sg at ${destination} failed its --version probe: ${error instanceof Error ? error.message : String(error)}`,
		);
	}
	if (!reported.includes(pinnedVersion)) {
		await rm(destination, { force: true });
		throw new Error(
			`provisioned sg at ${destination} reported "${reported}" but the manifest pins version ${pinnedVersion}; removed the binary.`,
		);
	}
}

function defaultResolvePreexistingSg(options: ResolvePreexistingSgOptions): string | null {
	return findSgBinarySync({
		arch: options.arch,
		env: { ...options.env, CODEX_HOME: options.codexHome },
		platform: options.platform,
		runtimeDir: sgRuntimeDir(options.codexHome, options.platform, options.arch),
	});
}

const execFileAsync = promisify(execFile);

async function defaultVersionProbe(binaryPath: string): Promise<string> {
	const { stdout } = await execFileAsync(binaryPath, ["--version"]);
	return String(stdout);
}

import { copyFile, mkdir, readFile, readdir, rm, stat } from "node:fs/promises";
import { join } from "node:path";

// These relative imports resolve at BUILD time in the monorepo; esbuild
// inlines the installer source modules into dist/cli.js so PLUGIN_ROOT ships
// nothing beyond the bundle.
import {
	capturePreservedAgentReasoning,
	capturePreservedAgentServiceTier,
	linkCachedPluginAgents,
} from "../../../../src/install/link-cached-plugin-agents.ts";
import { linkCachedPluginBins, linkRootRuntimeBin } from "../../../../src/install/codex-cache-bins.ts";
import { hasForeignAgentRegistration } from "../../../../src/install/codex-config-agents.ts";
import { updateCodexConfig } from "../../../../src/install/codex-config-toml.ts";
import { stampGitBashMcpEnv } from "../../../../src/install/codex-git-bash-mcp-env.ts";
import { trustedHookStatesForPlugin } from "../../../../src/install/codex-hook-trust.ts";
import { resolveCodexInstallerBinDir } from "../../../../src/install/codex-installer-bin-dir.ts";
import { prepareGitBashForInstall } from "../../../../src/install/git-bash.ts";
import type { CodexAgentConfig, GitBashResolution } from "../../../../src/install/types.ts";
import { appendBootstrapLog, BOOTSTRAP_DOCTOR_HINT } from "./worker.ts";
import type { BootstrapDegradedEntry, BootstrapStepOutcome } from "./worker.ts";

export const SETUP_MARKETPLACE_NAME = "sisyphuslabs";
export const SETUP_PLUGIN_NAME = "omo";
export const GIT_BASH_INSTALL_HINT = "winget install --id Git.Git -e --source winget";

export interface WorkerSetupOptions {
	readonly codexHome: string;
	readonly env: Record<string, string | undefined>;
	readonly pluginData: string;
	readonly pluginRoot: string;
	readonly platform: NodeJS.Platform;
	/** Timestamp used for bootstrap.log entries; the worker passes its run time. */
	readonly now?: number;
	/** Test seam: overrides Git Bash discovery (win32 only). */
	readonly resolveGitBash?: () => GitBashResolution;
}

interface AgentLinkOutcome {
	readonly agentConfigs: readonly CodexAgentConfig[];
	readonly degraded: readonly BootstrapDegradedEntry[];
}

// Worker setup sequence (every sub-step is idempotent and degraded-not-fatal,
// unlike the npx installer which throws): Git Bash preflight -> bundled agent
// TOML linking -> config blocks + hook trust re-stamp -> git_bash MCP env ->
// version-aware bin links. Bin linking re-runs whenever the worker re-runs,
// and the worker re-runs whenever completedForVersion changes (Task 7 marker
// semantics), so links always point at the CURRENT versioned PLUGIN_ROOT even
// though Codex deletes old version dirs on upgrade (core-plugins store.rs).
export async function runWorkerSetup(options: WorkerSetupOptions): Promise<BootstrapStepOutcome> {
	const degraded: BootstrapDegradedEntry[] = [];
	const gitBashEnabled = await resolveGitBashStep(options, degraded);
	const agents = await linkBundledAgentsStep(options);
	degraded.push(...agents.degraded);
	await updateConfigStep(options, { agentConfigs: agents.agentConfigs, gitBashEnabled }, degraded);
	await stampGitBashEnvStep(options, degraded);
	await linkComponentBinsStep(options, degraded);
	return { degraded };
}

async function resolveGitBashStep(options: WorkerSetupOptions, degraded: BootstrapDegradedEntry[]): Promise<boolean> {
	if (options.platform !== "win32") return false;
	try {
		const resolution = await prepareGitBashForInstall({
			env: options.env,
			platform: options.platform,
			...(options.resolveGitBash === undefined ? {} : { resolveGitBash: options.resolveGitBash }),
		});
		if (resolution.found) return true;
		degraded.push({
			component: "git-bash",
			hint: GIT_BASH_INSTALL_HINT,
			reason: "Git Bash was not found on this Windows machine; the omo git_bash MCP server stays disabled",
		});
	} catch (error) {
		degraded.push({
			component: "git-bash",
			hint: GIT_BASH_INSTALL_HINT,
			reason: `Git Bash preflight failed: ${errorMessage(error)}`,
		});
	}
	return false;
}

async function linkBundledAgentsStep(options: WorkerSetupOptions): Promise<AgentLinkOutcome> {
	const agentsTarget = join(options.codexHome, "agents");
	try {
		// linkCachedPluginAgents writes its .installed-agents.json manifest next
		// to the agent sources, so the bundled TOMLs are staged under PLUGIN_DATA
		// first: bootstrap must never persist anything under PLUGIN_ROOT (the
		// Codex-managed marketplace cache).
		const stageRoot = join(options.pluginData, "bootstrap", "agents-stage");
		await stageBundledAgents(options.pluginRoot, stageRoot);
		const preservedReasoning = await capturePreservedAgentReasoning({ codexHome: options.codexHome });
		const preservedServiceTier = await capturePreservedAgentServiceTier({ codexHome: options.codexHome });
		const linked = await linkCachedPluginAgents({
			codexHome: options.codexHome,
			pluginRoot: stageRoot,
			preservedReasoning,
			preservedServiceTier,
		});
		const agentConfigs = linked
			.map((link) => ({ configFile: `./agents/${link.name}`, name: agentNameFromToml(link.name) }))
			.sort((left, right) => left.name.localeCompare(right.name));
		return { agentConfigs, degraded: [] };
	} catch (error) {
		return {
			agentConfigs: [],
			degraded: [
				{
					component: "agents",
					hint: BOOTSTRAP_DOCTOR_HINT,
					reason: `failed to link bundled agents into ${agentsTarget}: ${errorMessage(error)}`,
				},
			],
		};
	}
}

async function stageBundledAgents(pluginRoot: string, stageRoot: string): Promise<void> {
	await rm(stageRoot, { force: true, recursive: true });
	await mkdir(stageRoot, { recursive: true });
	const componentsRoot = join(pluginRoot, "components");
	for (const componentName of await directoryNames(componentsRoot)) {
		const agentsDir = join(componentsRoot, componentName, "agents");
		const agentFiles = (await fileNames(agentsDir)).filter((name) => name.endsWith(".toml"));
		if (agentFiles.length === 0) continue;
		const stagedAgentsDir = join(stageRoot, "components", componentName, "agents");
		await mkdir(stagedAgentsDir, { recursive: true });
		for (const agentFile of agentFiles) {
			await copyFile(join(agentsDir, agentFile), join(stagedAgentsDir, agentFile));
		}
	}
}

async function updateConfigStep(
	options: WorkerSetupOptions,
	inputs: { agentConfigs: readonly CodexAgentConfig[]; gitBashEnabled: boolean },
	degraded: BootstrapDegradedEntry[],
): Promise<void> {
	const configPath = join(options.codexHome, "config.toml");
	try {
		await assertWritableConfigIfPresent(configPath);
		// Orca mirrors the system [agents.*] entries into its runtime CODEX_HOME
		// without copying the agents directory. Re-stamping our own registration
		// for such a role would collide with the mirrored entry once Codex
		// discovers <codexHome>/agents/<name>.toml (two different file paths for
		// one role name -> upstream warning), so foreign pre-existing blocks are
		// left untouched; directory discovery still loads the linked toml.
		const existingConfig = await readConfigIfPresent(configPath);
		const agentConfigs = inputs.agentConfigs.filter(
			(agentConfig) => !hasForeignAgentRegistration(existingConfig, agentConfig),
		);
		// Re-stamping trusted hook hashes after an upgrade is what makes the
		// next session's hooks trusted again once the user re-approved the
		// bootstrap hook itself.
		const trustedHookStates = await trustedHookStatesForPlugin({
			marketplaceName: SETUP_MARKETPLACE_NAME,
			pluginName: SETUP_PLUGIN_NAME,
			pluginRoot: options.pluginRoot,
		});
		await updateCodexConfig({
			agentConfigs,
			// Hard invariant: the bootstrap worker NEVER writes permission keys
			// (approval/sandbox/network policies stay installer-flag-only).
			autonomousPermissions: false,
			configPath,
			gitBashEnabled: inputs.gitBashEnabled,
			marketplaceName: SETUP_MARKETPLACE_NAME,
			marketplaceSource: { sourceType: "local", source: options.pluginRoot },
			platform: options.platform,
			pluginNames: [SETUP_PLUGIN_NAME],
			preserveMarketplaceSource: true,
			// The marketplace plugin tree has no <root>/plugin/model-catalog.json,
			// so updateCodexConfig falls back to the catalog bundled into this
			// dist; bootstrap-setup.test.mjs guards against drift between the two.
			repoRoot: options.pluginRoot,
			trustedHookStates,
		});
	} catch (error) {
		degraded.push({
			component: "config",
			hint: BOOTSTRAP_DOCTOR_HINT,
			reason: `failed to update ${configPath}: ${errorMessage(error)}`,
		});
	}
}

async function assertWritableConfigIfPresent(configPath: string): Promise<void> {
	try {
		if (((await stat(configPath)).mode & 0o222) === 0) throw new Error(`${configPath} has no write permission bits set`);
	} catch (error) {
		if (errorCode(error) === "ENOENT") return;
		throw error;
	}
}

function errorCode(error: unknown): string | undefined {
	return error instanceof Error && "code" in error && typeof error.code === "string" ? error.code : undefined;
}

async function readConfigIfPresent(configPath: string): Promise<string> {
	try {
		return await readFile(configPath, "utf8");
	} catch (error) {
		if (errorCode(error) === "ENOENT") return "";
		throw error;
	}
}

async function linkComponentBinsStep(options: WorkerSetupOptions, degraded: BootstrapDegradedEntry[]): Promise<void> {
	const binDir = resolveCodexInstallerBinDir({ codexHome: options.codexHome, env: options.env });
	try {
		await linkCachedPluginBins({ binDir, pluginRoot: options.pluginRoot, platform: options.platform });
	} catch (error) {
		degraded.push({
			component: "bin-links",
			hint: BOOTSTRAP_DOCTOR_HINT,
			reason: `failed to link component bins into ${binDir}: ${errorMessage(error)}`,
		});
	}
	await linkRuntimeWrapperStep(options, binDir, degraded);
}

// Older marketplace payloads may not have <pluginRoot>/dist/cli. Keep that
// degraded path explicit instead of leaving a broken `omo-agent-toolkit` link.
async function linkRuntimeWrapperStep(
	options: WorkerSetupOptions,
	binDir: string,
	degraded: BootstrapDegradedEntry[],
): Promise<void> {
	const cliPath = join(options.pluginRoot, "dist", "cli", "index.js");
	try {
		const linked = await linkRootRuntimeBin({
			binDir,
			codexHome: options.codexHome,
			platform: options.platform,
			repoRoot: options.pluginRoot,
		});
		if (linked !== null) return;
		degraded.push({
			component: "omo-agent-toolkit",
			hint: "use npx lazycodex-ai for the omo-agent-toolkit CLI",
			reason: "marketplace payload has no dist/cli",
		});
		await appendBootstrapLog(options.pluginData, options.now ?? Date.now(), "omo-agent-toolkit-degraded", {
			warning: `Warning: skipped the omo-agent-toolkit runtime wrapper because ${cliPath} is missing; omo-agent-toolkit ulw-loop commands will be unavailable until a package shipping dist/cli is installed`,
		});
	} catch (error) {
		degraded.push({
			component: "omo-agent-toolkit",
			hint: BOOTSTRAP_DOCTOR_HINT,
			reason: `failed to link the omo-agent-toolkit runtime wrapper into ${binDir}: ${errorMessage(error)}`,
		});
	}
}

async function stampGitBashEnvStep(options: WorkerSetupOptions, degraded: BootstrapDegradedEntry[]): Promise<void> {
	try {
		await stampGitBashMcpEnv({ env: options.env, platform: options.platform, pluginRoot: options.pluginRoot });
	} catch (error) {
		degraded.push({
			component: "git-bash-env",
			hint: BOOTSTRAP_DOCTOR_HINT,
			reason: `failed to stamp ${join(options.pluginRoot, ".mcp.json")}: ${errorMessage(error)}`,
		});
	}
}

async function directoryNames(root: string): Promise<string[]> {
	return entryNames(root, (entry) => entry.isDirectory());
}

async function fileNames(root: string): Promise<string[]> {
	return entryNames(root, (entry) => entry.isFile());
}

async function entryNames(root: string, keep: (entry: { isDirectory(): boolean; isFile(): boolean }) => boolean): Promise<string[]> {
	try {
		const entries = await readdir(root, { withFileTypes: true });
		return entries
			.filter((entry) => keep(entry))
			.map((entry) => entry.name)
			.sort();
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return [];
		throw error;
	}
}

function agentNameFromToml(fileName: string): string {
	return fileName.endsWith(".toml") ? fileName.slice(0, -".toml".length) : fileName;
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

import { appendFile, mkdir, readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { readState, writeState } from "../../../scripts/auto-update-state.mjs";
import { bootstrapLocks, resolveBootstrapStatePath, resolveCodexHome } from "./environment.ts";
import { runSgProvision } from "./provision.ts";
import type { SgProvisionSeams } from "./provision.ts";
import { runWorkerSetup } from "./setup.ts";

export const BOOTSTRAP_DOCTOR_HINT = "npx lazycodex-ai doctor";

export type BootstrapRunStatus = "success" | "degraded";

export interface BootstrapDegradedEntry {
	readonly component: string;
	readonly reason: string;
	readonly hint?: string;
}

export interface BootstrapState {
	readonly completedForVersion?: string;
	readonly lastAttemptAt?: number;
	readonly lastStatus?: BootstrapRunStatus;
	readonly degraded?: readonly BootstrapDegradedEntry[];
}

export interface BootstrapWorkerFlags {
	readonly codexHome?: string;
	readonly manifestDir?: string;
	readonly once: boolean;
	readonly only?: string;
}

export interface BootstrapWorkerContext {
	readonly codexHome: string;
	readonly env: Record<string, string | undefined>;
	readonly flags: BootstrapWorkerFlags;
	readonly now: number;
	readonly platform: NodeJS.Platform;
	readonly pluginData: string;
	readonly pluginRoot: string;
	readonly pluginVersion: string | undefined;
}

export interface BootstrapStepOutcome {
	readonly degraded: readonly BootstrapDegradedEntry[];
}

export interface BootstrapWorkerStep {
	readonly name: string;
	readonly run: (context: BootstrapWorkerContext) => Promise<BootstrapStepOutcome>;
}

export type BootstrapWorkerSkipReason = "locked" | "already-completed";

export type BootstrapWorkerResult =
	| { readonly ran: false; readonly reason: BootstrapWorkerSkipReason }
	| {
			readonly ran: true;
			readonly status: BootstrapRunStatus;
			readonly degraded: readonly BootstrapDegradedEntry[];
			readonly statePath: string;
	  };

export interface RunBootstrapWorkerOptions {
	readonly argv?: readonly string[];
	readonly env?: Record<string, string | undefined>;
	readonly now?: number;
	readonly platform?: NodeJS.Platform;
	readonly steps?: readonly BootstrapWorkerStep[];
}

export function parseWorkerFlags(argv: readonly string[]): BootstrapWorkerFlags {
	let codexHome: string | undefined;
	let manifestDir: string | undefined;
	let once = false;
	let only: string | undefined;
	for (let index = 0; index < argv.length; index += 1) {
		const flag = argv[index];
		if (flag === "--once") {
			once = true;
			continue;
		}
		if (flag === "--codex-home") {
			codexHome = requireFlagValue(argv, index, flag);
			index += 1;
			continue;
		}
		if (flag === "--only") {
			only = requireFlagValue(argv, index, flag);
			index += 1;
			continue;
		}
		if (flag === "--manifest-dir") {
			manifestDir = requireFlagValue(argv, index, flag);
			index += 1;
			continue;
		}
		throw new Error(`unknown worker flag: ${flag}`);
	}
	return {
		once,
		...(codexHome === undefined ? {} : { codexHome }),
		...(manifestDir === undefined ? {} : { manifestDir }),
		...(only === undefined ? {} : { only }),
	};
}

export function resolvePluginDataRoot(env: Record<string, string | undefined>): string {
	const fromEnv = env["PLUGIN_DATA"]?.trim();
	if (fromEnv !== undefined && fromEnv.length > 0) return fromEnv;
	return join(homedir(), ".local", "share", "lazycodex");
}

export async function readPluginVersion(pluginRoot: string): Promise<string | undefined> {
	try {
		const parsed: unknown = JSON.parse(await readFile(join(pluginRoot, ".codex-plugin", "plugin.json"), "utf8"));
		if (typeof parsed !== "object" || parsed === null) return undefined;
		const version = (parsed as Record<string, unknown>)["version"];
		if (typeof version !== "string") return undefined;
		const trimmed = version.trim();
		return trimmed.length > 0 ? trimmed : undefined;
	} catch {
		return undefined;
	}
}

export async function readBootstrapState(statePath: string): Promise<BootstrapState> {
	return parseBootstrapState(await readState(statePath));
}

export function parseBootstrapState(raw: Record<string, unknown>): BootstrapState {
	const completedForVersion = typeof raw["completedForVersion"] === "string" ? raw["completedForVersion"] : undefined;
	const lastAttemptAt = typeof raw["lastAttemptAt"] === "number" ? raw["lastAttemptAt"] : undefined;
	const lastStatus = raw["lastStatus"] === "success" || raw["lastStatus"] === "degraded" ? raw["lastStatus"] : undefined;
	const degraded = parseDegradedEntries(raw["degraded"]);
	return {
		...(completedForVersion === undefined ? {} : { completedForVersion }),
		...(lastAttemptAt === undefined ? {} : { lastAttemptAt }),
		...(lastStatus === undefined ? {} : { lastStatus }),
		...(degraded === undefined ? {} : { degraded }),
	};
}

export interface DefaultWorkerStepsSeams {
	readonly sg?: SgProvisionSeams;
}

export function defaultWorkerSteps(seams: DefaultWorkerStepsSeams = {}): readonly BootstrapWorkerStep[] {
	return [
		{
			name: "setup",
			run: (context) => runWorkerSetup(context),
		},
		{
			name: "sg",
			run: (context) => runSgProvision(context, seams.sg),
		},
	];
}

export async function runBootstrapWorker(options: RunBootstrapWorkerOptions = {}): Promise<BootstrapWorkerResult> {
	const env = options.env ?? process.env;
	const now = options.now ?? Date.now();
	const platform = options.platform ?? process.platform;
	const flags = parseWorkerFlags(options.argv ?? []);
	const steps = options.steps ?? defaultWorkerSteps();
	if (flags.only !== undefined && !steps.some((step) => step.name === flags.only)) {
		throw new Error(`unknown --only flag value: ${flags.only}`);
	}
	const pluginRoot = resolvePluginRoot(env);
	const pluginData = resolvePluginDataRoot(env);
	const statePath = resolveBootstrapStatePath(pluginData);
	// Pin BOTH lock paths (bootstrap + auto-update) under the resolved plugin
	// data root even when PLUGIN_DATA is missing from the environment.
	const lockEnv = { ...env, PLUGIN_DATA: pluginData };

	const locks = await bootstrapLocks({ env: lockEnv, now, pluginData });
	if (locks === null) return { ran: false, reason: "locked" };
	try {
		const pluginVersion = await readPluginVersion(pluginRoot);
		const marker = await readBootstrapState(statePath);
		// TOCTOU re-check under lock: another worker may have completed between
		// the hook's unlocked read and this acquisition.
		if (!flags.once && pluginVersion !== undefined && marker.completedForVersion === pluginVersion) {
			await appendBootstrapLog(pluginData, now, "worker-skipped", { reason: "already-completed", version: pluginVersion });
			return { ran: false, reason: "already-completed" };
		}

		const codexHome = flags.codexHome ?? (await resolveCodexHome({ env, pluginRoot })).path;
		const context: BootstrapWorkerContext = { codexHome, env, flags, now, platform, pluginData, pluginRoot, pluginVersion };
		await appendBootstrapLog(pluginData, now, "worker-started", { version: pluginVersion ?? "unknown" });

		const degraded: BootstrapDegradedEntry[] = [];
		if (pluginVersion === undefined) {
			degraded.push({
				component: "bootstrap",
				hint: BOOTSTRAP_DOCTOR_HINT,
				reason: `plugin version unresolved from ${join(pluginRoot, ".codex-plugin", "plugin.json")}`,
			});
		}
		for (const step of steps) {
			if (flags.only !== undefined && step.name !== flags.only) continue;
			degraded.push(...(await runStep(step, context)));
		}

		const status: BootstrapRunStatus = degraded.length === 0 ? "success" : "degraded";
		const state: BootstrapState = {
			...(pluginVersion === undefined ? {} : { completedForVersion: pluginVersion }),
			degraded,
			lastAttemptAt: now,
			lastStatus: status,
		};
		await writeState(statePath, state);
		await appendBootstrapLog(pluginData, now, "worker-finished", { degradedCount: degraded.length, status });
		return { degraded, ran: true, statePath, status };
	} finally {
		await locks.release();
	}
}

async function runStep(step: BootstrapWorkerStep, context: BootstrapWorkerContext): Promise<readonly BootstrapDegradedEntry[]> {
	try {
		return (await step.run(context)).degraded;
	} catch (error) {
		return [
			{
				component: step.name,
				hint: BOOTSTRAP_DOCTOR_HINT,
				reason: error instanceof Error ? error.message : String(error),
			},
		];
	}
}

function resolvePluginRoot(env: Record<string, string | undefined>): string {
	const fromEnv = env["PLUGIN_ROOT"]?.trim();
	if (fromEnv !== undefined && fromEnv.length > 0) return fromEnv;
	// dist/cli.js lives at <pluginRoot>/components/bootstrap/dist/cli.js.
	return resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
}

export async function appendBootstrapLog(
	pluginData: string,
	now: number,
	event: string,
	details: Record<string, unknown>,
): Promise<void> {
	try {
		const logPath = join(pluginData, "bootstrap", "bootstrap.log");
		await mkdir(dirname(logPath), { recursive: true });
		await appendFile(logPath, `${JSON.stringify({ timestamp: new Date(now).toISOString(), event, ...details })}\n`);
	} catch {
		// Logging must never fail the worker.
	}
}

function parseDegradedEntries(raw: unknown): readonly BootstrapDegradedEntry[] | undefined {
	if (!Array.isArray(raw)) return undefined;
	const entries: BootstrapDegradedEntry[] = [];
	for (const candidate of raw) {
		if (typeof candidate !== "object" || candidate === null) continue;
		const record = candidate as Record<string, unknown>;
		if (typeof record["component"] !== "string" || typeof record["reason"] !== "string") continue;
		entries.push({
			component: record["component"],
			reason: record["reason"],
			...(typeof record["hint"] === "string" ? { hint: record["hint"] } : {}),
		});
	}
	return entries;
}

function requireFlagValue(argv: readonly string[], index: number, flag: string): string {
	const value = argv[index + 1];
	if (value === undefined || value.startsWith("--")) {
		throw new Error(`${flag} requires a value`);
	}
	return value;
}

import { afterEach, describe, expect, it } from "bun:test";
import { createHash } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
