			const handle = await bootstrapLocks({ env, pluginData });

			expect(handle).toBeNull();
			expect(existsSync(join(pluginData, "bootstrap", "state.json.lock"))).toBe(false);
			expect(existsSync(autoUpdateLockPath)).toBe(true);
		});
