const NON_FATAL_GC_ERROR_CODES = new Set(["EACCES", "EBUSY", "ENOENT", "ENOTEMPTY", "ENOTDIR", "EPERM"]);

export function pruneCodegraphProjectStoresBestEffort(
	homeDir: string,
	options: PruneCodegraphProjectStoresBestEffortOptions = {},
