		permission_mode: "default",
		stop_hook_active: true,
		last_assistant_message: "done!",
		...overrides,
	};
}

function createUnknownEventInput(cwd: string): Record<string, string | boolean> {
	return {
		hook_event_name: "Stop",
		agent_type: "lazycodex-worker-medium",
		agent_id: "agent_1",
