	writeFileSync(join(projectRoot, "CLAUDE.md"), "Claude rule\n");
	writeFileSync(join(projectRoot, "src", ".omo", "rules", "local.md"), "Local rule\n");
	writeFileSync(join(projectRoot, ".omo", "rules", "root.md"), "Root rule\n");
