#!/usr/bin/env node
import { stdin as processStdin, stdout as processStdout } from "node:process";

import { type CodexSessionStartInput, runSessionStartHook } from "./codex-hook.js";

const command = process.argv[2];
const subcommand = process.argv[3];

if (command === "hook" && subcommand === "session-start") {
	await runHookCli();
} else {
	process.stderr.write("Usage: omo-telemetry hook session-start\n");
	process.exitCode = 1;
}

async function runHookCli(): Promise<void> {
	const raw = await readStdin();
	if (raw.trim().length === 0) return;
	const parsed = parseHookInput(raw);
	if (!isCodexSessionStartInput(parsed)) return;
	const output = await runSessionStartHook(parsed);
	if (output.length > 0) {
		processStdout.write(output);
	}
}

function parseHookInput(raw: string): unknown | undefined {
	try {
		const parsed: unknown = JSON.parse(raw);
		return parsed;
	} catch {
		return undefined;
	}
}

function isCodexSessionStartInput(value: unknown): value is CodexSessionStartInput {
	return (
		isRecord(value) &&
		value["hook_event_name"] === "SessionStart" &&
		typeof value["session_id"] === "string" &&
		isStringOrNull(value["transcript_path"]) &&
		typeof value["cwd"] === "string" &&
		typeof value["model"] === "string" &&
		typeof value["permission_mode"] === "string" &&
		typeof value["source"] === "string"
	);
}

function isStringOrNull(value: unknown): value is string | null {
	return typeof value === "string" || value === null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readStdin(): Promise<string> {
	return new Promise((resolve, reject) => {
		let data = "";
		processStdin.setEncoding("utf8");
		processStdin.on("data", (chunk: string) => {
			data += chunk;
		});
		processStdin.once("error", reject);
		processStdin.once("end", () => {
			resolve(data);
		});
	});
}

import {
	type TelemetryDiagnosticErrorKind,
	type TelemetryDiagnosticEvent,
} from "@oh-my-opencode/telemetry-core";
import {
	createPluginPostHog,
	getPostHogDistinctId,
	type PostHogActivityReason,
	type PostHogClient,
} from "./posthog.js";
import { writeComponentTelemetryDiagnostic } from "./product-identity.js";

export type CodexSessionStartInput = {
	session_id: string;
	transcript_path: string | null;
	cwd: string;
	hook_event_name: "SessionStart";
	model: string;
	permission_mode: string;
	source: "startup" | "resume" | "clear";
};

export type CodexTelemetryHookOptions = {
	createClient?: () => PostHogClient | Promise<PostHogClient>;
	getDistinctId?: () => string;
};

const SESSION_START_REASON: PostHogActivityReason = "session_start";

function writeHookDiagnostic(
	event: TelemetryDiagnosticEvent,
	error: unknown,
	errorKind: TelemetryDiagnosticErrorKind,
): void {
	writeComponentTelemetryDiagnostic({
		event,
		source: "plugin",
		error,
		errorKind,
	});
}

export async function runSessionStartHook(
	_input: CodexSessionStartInput,
	options: CodexTelemetryHookOptions = {},
): Promise<string> {
	const createClient = options.createClient ?? createPluginPostHog;
	const getDistinctId = options.getDistinctId ?? getPostHogDistinctId;

	let client: PostHogClient;
	try {
		client = await createClient();
	} catch (error) {
		writeHookDiagnostic("telemetry_posthog_init_failed", error, error instanceof Error ? "error" : "non_error");
		return "";
	}

	try {
		client.trackActive(getDistinctId(), SESSION_START_REASON);
	} catch (error) {
		writeHookDiagnostic("telemetry_capture_failed", error, error instanceof Error ? "error" : "non_error");
		await safeShutdown(client);
		return "";
	}
	await safeShutdown(client);
	return "";
}

async function safeShutdown(client: PostHogClient): Promise<void> {
	try {
		await client.shutdown();
	} catch (error) {
		writeHookDiagnostic("telemetry_shutdown_failed", error, error instanceof Error ? "error" : "non_error");
		return;
	}
}

import {
	createTelemetryClient,
	getDailyActiveCaptureState,
	getDefaultTelemetryOsProvider,
	getTelemetryDistinctId,
	type PostHogActivityCaptureState,
	type TelemetryOsProvider,
	type TelemetryTransportFactory,
} from "@oh-my-opencode/telemetry-core";

import {
	MACHINE_ID_PREFIX,
	createComponentTelemetryProductConfig,
	getComponentTelemetryStateDir,
	getComponentVersion,
	writeComponentTelemetryDiagnostic,
} from "./product-identity.js";

export { DEFAULT_POSTHOG_API_KEY, DEFAULT_POSTHOG_HOST } from "./product-identity.js";
export { getComponentVersion };

export type PostHogActivityReason = "session_start";

export type PostHogClient = {
	readonly trackActive: (distinctId: string, reason: PostHogActivityReason) => void;
	readonly shutdown: () => Promise<void>;
};

type ActivityStateProvider = () => PostHogActivityCaptureState;

type CreatePluginPostHogOptions = {
	readonly activityStateProvider?: ActivityStateProvider;
	readonly env?: NodeJS.ProcessEnv;
	readonly now?: Date;
	readonly osProvider?: TelemetryOsProvider;
	readonly stateDir?: string;
	readonly transportFactory?: TelemetryTransportFactory;
};

const NO_OP_POSTHOG: PostHogClient = {
	trackActive: () => undefined,
	shutdown: async () => undefined,
};

function resolveOsProvider(options: CreatePluginPostHogOptions): TelemetryOsProvider {
	return options.osProvider ?? getDefaultTelemetryOsProvider();
}

function resolveActivityStateProvider(options: CreatePluginPostHogOptions): ActivityStateProvider {
	if (options.activityStateProvider !== undefined) {
		return options.activityStateProvider;
	}

	if (options.stateDir === undefined) {
		return () =>
			getDailyActiveCaptureState(createDailyActiveCaptureStateInput(
				getComponentTelemetryStateDir(),
				options.now,
			));
	}

	const stateDir = options.stateDir;
	return () =>
		getDailyActiveCaptureState(createDailyActiveCaptureStateInput(
			stateDir,
			options.now,
		));
}

function createDailyActiveCaptureStateInput(
	stateDir: string,
	now: Date | undefined,
) {
	if (now === undefined) {
		return {
			diagnostics: writeComponentTelemetryDiagnostic,
			stateDir,
		};
	}

	return {
		diagnostics: writeComponentTelemetryDiagnostic,
		now,
		stateDir,
	};
}

function createPluginPostHogClient(options: CreatePluginPostHogOptions = {}): PostHogClient {
	const clientInput = {
		diagnostics: writeComponentTelemetryDiagnostic,
		env: options.env ?? process.env,
		osProvider: resolveOsProvider(options),
		product: createComponentTelemetryProductConfig({
			runtime: "node",
			runtime_version: process.version,
		}),
		source: "plugin",
	};
	const client = createTelemetryClient(
		options.transportFactory === undefined
			? clientInput
			: {
					...clientInput,
					transportFactory: options.transportFactory,
				},
	);

	if (!client.enabled) {
		return NO_OP_POSTHOG;
	}

	const activityStateProvider = resolveActivityStateProvider(options);

	return {
		trackActive: (distinctId, reason) => {
			const activityState = activityStateProvider();
			if (!activityState.captureDaily) {
				return;
			}

			client.trackActive({
				dayUTC: activityState.dayUTC,
				distinctId,
				reason,
			});
		},
		shutdown: async () => {
			await client.shutdown();
		},
	};
}

export async function createPluginPostHog(): Promise<PostHogClient> {
	return createPluginPostHogClient();
}

