import { type CheckpointUlwLoopArgs, type CheckpointUlwLoopResult, checkpointUlwLoop } from "./checkpoint.js";
import { hasFlag, parseCodexGoalJson, readValue } from "./cli-arg-parser.js";
import { blockedDecisionHandoff, printJson } from "./cli-output.js";
import { buildCodexGoalInstruction, type UlwLoopGoalInstruction } from "./codex-goal-instruction.js";
import type { UlwLoopScope } from "./paths.js";
import { startNextUlwLoop, summarizeUlwLoopPlan } from "./plan-crud.js";
import type { UlwLoopItem, UlwLoopPlan } from "./types.js";
import { UlwLoopError } from "./types.js";

type ContinuationNext =
	| { readonly resumed: boolean; readonly goal: UlwLoopItem; readonly instruction: UlwLoopGoalInstruction }
	| { readonly done: true; readonly blocked: boolean; readonly handoff: string };

export type CheckpointAndContinueResult = CheckpointUlwLoopResult & { readonly next?: ContinuationNext };

export async function checkpointAndContinue(
	repoRoot: string,
	args: CheckpointUlwLoopArgs & { readonly advance: boolean },
	scope?: UlwLoopScope,
): Promise<CheckpointAndContinueResult> {
	const result = await checkpointUlwLoop(repoRoot, args, scope);
	if (args.status !== "complete" || result.aggregateCompletion !== undefined || !args.advance) return result;
	const next = await startNextUlwLoop(repoRoot, {}, scope);
	if ("done" in next) return { ...result, plan: next.plan, next: doneNext(next.plan) };
	const instruction = buildCodexGoalInstruction({ plan: next.plan, goal: next.goal });
	return { ...result, plan: next.plan, next: { resumed: next.resumed, goal: next.goal, instruction } };
}

export async function checkpoint(
	repoRoot: string,
	argv: readonly string[],
	json: boolean,
	scope?: UlwLoopScope,
): Promise<number> {
	const goalId = required(argv, "--goal-id");
	const statusValue = checkpointStatus(required(argv, "--status"));
	const evidence = required(argv, "--evidence");
	const codexGoalJson = await parseCodexGoalJson(
		statusValue === "complete" ? required(argv, "--codex-goal-json") : readValue(argv, "--codex-goal-json"),
	);
	if (statusValue === "complete" && codexGoalJson === undefined) {
		throw new UlwLoopError("Missing --codex-goal-json.", "ULW_LOOP_CODEX_GOAL_JSON_REQUIRED");
	}
	const qualityGateJson = readValue(argv, "--quality-gate-json");
	const args: CheckpointUlwLoopArgs & { readonly advance: boolean } = {
		goalId,
		status: statusValue,
		evidence,
		advance: !hasFlag(argv, "--no-advance"),
		...(codexGoalJson === undefined ? {} : { codexGoalJson }),
		...(qualityGateJson === undefined ? {} : { qualityGateJson }),
	};
	const result = await checkpointAndContinue(repoRoot, args, scope);
	if (json) printJson({ ok: true, ...result, summary: summarizeUlwLoopPlan(result.plan) });
	else printCheckpointText(result);
	return 0;
}

function printCheckpointText(result: CheckpointAndContinueResult): void {
	process.stdout.write(`ulw-loop checkpoint: ${result.goal.id} -> ${result.goal.status}\n`);
	if (result.next === undefined) return;
	if ("instruction" in result.next) process.stdout.write(`${result.next.instruction.text}\n`);
	else process.stdout.write(`${result.next.handoff || "ulw-loop: all goals complete"}\n`);
}

function doneNext(plan: UlwLoopPlan): ContinuationNext {
	const handoff = blockedDecisionHandoff(plan);
	return { done: true, blocked: handoff.length > 0, handoff };
}

function required(argv: readonly string[], flag: string): string {
	const value = readValue(argv, flag)?.trim();
	if (value) return value;
	throw new UlwLoopError(`Missing ${flag}.`, "ULW_LOOP_ARGUMENT_MISSING", { details: { flag } });
}

function checkpointStatus(value: string): CheckpointUlwLoopArgs["status"] {
	if (value === "complete" || value === "failed" || value === "blocked") return value;
	throw new UlwLoopError(
		"Missing or invalid --status; expected complete, failed, or blocked.",
		"ULW_LOOP_STATUS_INVALID",
		{ details: { status: value } },
	);
}

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";

import { codexGoalMode, isFinalRunCompletionCandidate } from "./goal-status.js";
import { type UlwLoopScope, ulwLoopBriefPath } from "./paths.js";
import type { UlwLoopItem, UlwLoopPlan } from "./types.js";
import { ULW_LOOP_DIR, ULW_LOOP_GOALS, ULW_LOOP_LEDGER } from "./types.js";

function normalizeObjective(value: string): string {
	return value.replace(/\s+/g, " ").trim();
}

function textMentionsUlwLoopPlanArtifact(value: string | undefined): boolean {
	const normalized = (value ?? "").toLowerCase();
	return (
		normalized.includes(ULW_LOOP_DIR.toLowerCase()) ||
		normalized.includes(ULW_LOOP_GOALS.toLowerCase()) ||
		normalized.includes(ULW_LOOP_LEDGER.toLowerCase())
	);
}

function textMentionsGoalId(value: string | undefined, goalId: string): boolean {
	return (value ?? "").toLowerCase().includes(goalId.toLowerCase());
}

function textHasCompletionValidationEvidence(value: string | undefined): boolean {
	const normalized = (value ?? "").toLowerCase();
	const done =
		/\b(?:planned work|implementation|deliverables?|scope|task|work)\b/.test(normalized) &&
		/\b(?:done|complete|completed|finished|shipped)\b/.test(normalized);
	const verified =
		/\b(?:validation|verification|tests?|build|lint|review|quality gate|code-review)\b/.test(normalized) &&
		/\b(?:passed|complete|completed|clean|green|approve|approved|clear)\b/.test(normalized);
	return done && verified;
}

async function snapshotObjectiveMapsToUlwLoopPlan(
	repoRoot: string,
	snapshotObjective: string,
	scope?: UlwLoopScope,
): Promise<boolean> {
	const actual = normalizeObjective(snapshotObjective).toLowerCase();
	if (textMentionsUlwLoopPlanArtifact(actual)) return true;
	if (actual.length < 24 || !existsSync(ulwLoopBriefPath(repoRoot, scope))) return false;
	try {
		const brief = normalizeObjective(await readFile(ulwLoopBriefPath(repoRoot, scope), "utf8")).toLowerCase();
		return brief.length >= 24 && (brief.includes(actual) || actual.includes(brief));
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

export async function canReconcileCompletedTaskScopedAggregateSnapshot(
	repoRoot: string,
	plan: UlwLoopPlan,
	goal: UlwLoopItem,
	snapshotObjective: string,
	evidence: string,
	scope?: UlwLoopScope,
): Promise<boolean> {
	if (codexGoalMode(plan) !== "aggregate") return false;
	if (goal.status !== "in_progress" || plan.activeGoalId !== goal.id) return false;
	if (isFinalRunCompletionCandidate(plan, goal)) {
		return snapshotObjectiveMapsToUlwLoopPlan(repoRoot, snapshotObjective, scope);
	}
	if (!textMentionsUlwLoopPlanArtifact(evidence) || !textMentionsGoalId(evidence, goal.id)) return false;
	if (!textHasCompletionValidationEvidence(evidence)) return false;
	return snapshotObjectiveMapsToUlwLoopPlan(repoRoot, snapshotObjective, scope);
}

export async function canReconcileActiveFinalTaskScopedAggregateSnapshot(
	repoRoot: string,
	plan: UlwLoopPlan,
	goal: UlwLoopItem,
	snapshotObjective: string,
	evidence: string,
	scope?: UlwLoopScope,
): Promise<boolean> {
	if (codexGoalMode(plan) !== "aggregate") return false;
	if (goal.status !== "in_progress" || plan.activeGoalId !== goal.id) return false;
	if (!isFinalRunCompletionCandidate(plan, goal)) return false;
	if (!textHasCompletionValidationEvidence(evidence)) return false;
	return snapshotObjectiveMapsToUlwLoopPlan(repoRoot, snapshotObjective, scope);
}

function buildCompletedLegacyGoalRemediation(goal: UlwLoopItem): string {
	return [
		"If get_goal returns a different completed legacy/thread objective, do not repeat --status complete in this thread.",
		`Record a non-terminal blocker with: omo-agent-toolkit ulw-loop checkpoint --goal-id ${goal.id} --status blocked --evidence "<completed legacy Codex goal blocks create_goal in this thread>" --codex-goal-json "<different completed get_goal JSON or path>".`,
		"Then continue only from a Codex goal context with no active/completed conflicting goal, in the same repo/worktree, and create the intended goal there.",
	].join(" ");
}

export function buildTaskScopedAggregateReconciliationHint(goal: UlwLoopItem, final: boolean): string {
	if (final) {
		return ` Final task-scoped aggregate reconciliation requires the checkpoint goal to be the active in-progress final OMO goal and the completed get_goal objective to map to the ulw-loop brief or artifact. ${buildCompletedLegacyGoalRemediation(goal)}`;
	}
	return ` Completed task-scoped aggregate reconciliation requires the checkpoint goal to be the active in-progress OMO goal, evidence that names that active OMO goal id, names .omo/ulw-loop/goals.json or ledger.jsonl, includes completed implementation plus validation/review evidence, and a get_goal objective that maps to the ulw-loop brief/artifact. ${buildCompletedLegacyGoalRemediation(goal)}`;
}

