import { readCodexGoalSnapshotInput, reconcileCodexGoalSnapshot } from "./codex-goal-snapshot.js";
import { codexGoalMode, compatibleCodexObjectives, expectedCodexObjective, isFinalRunCompletionCandidate } from "./goal-status.js";
import type { UlwLoopScope } from "./paths.js";
import { seedDefaultSuccessCriteria } from "./plan-crud.js";
import { appendLedger, readUlwLoopPlan, withUlwLoopMutationLock, writePlan } from "./plan-io.js";
import type { UlwLoopItem, UlwLoopLedgerEntry, UlwLoopPlan } from "./types.js";
import { iso, UlwLoopError } from "./types.js";

export interface RecordFinalReviewBlockersArgs { readonly goalId: string; readonly title: string; readonly objective: string; readonly evidence: string; readonly codexGoalJson: string }
export interface RecordFinalReviewBlockersResult { readonly plan: UlwLoopPlan; readonly blockedGoal: UlwLoopItem; readonly newGoal: UlwLoopItem; readonly ledgerEntries: UlwLoopLedgerEntry[] }

const BLOCKER_FIELDS = "blockedReason blockerSignature blockerOccurrenceCount requiredExternalDecision nonRetriable failedAt failureReason completedAt blocker blockerEvidence blockerOccurrences blockedAt".split(" ");

function ulwLoopError(message: string, code: string): never {
	throw new UlwLoopError(message, code);
}

function nextGoalId(plan: UlwLoopPlan): string {
	const max = plan.goals.reduce((current, goal) => {
		const digits = /^G(\d+)/u.exec(goal.id)?.[1];
		return digits === undefined ? current : Math.max(current, Number(digits));
	}, 0);
	return `G${String(max + 1).padStart(3, "0")}`;
}

function appendBlockerGoal(plan: UlwLoopPlan, args: RecordFinalReviewBlockersArgs, now: string): UlwLoopItem {
	const index = plan.goals.length;
	const goal: UlwLoopItem = {
		id: nextGoalId(plan),
		title: args.title,
		objective: args.objective,
		status: "pending",
		successCriteria: seedDefaultSuccessCriteria(index, args.objective),
		attempt: 0,
		createdAt: now,
		updatedAt: now,
	};
	plan.goals.push(goal);
	return goal;
}

export async function recordFinalReviewBlockers(
	repoRoot: string,
	args: RecordFinalReviewBlockersArgs,
	scope?: UlwLoopScope,
): Promise<RecordFinalReviewBlockersResult> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const goal = plan.goals.find((candidate) => candidate.id === args.goalId);
		if (goal === undefined) ulwLoopError(`Unknown ulw-loop id: ${args.goalId}`, "ulw_loop_goal_not_found");
		if (goal.status !== "in_progress") ulwLoopError(`${goal.id} is ${goal.status}.`, "ulw_loop_goal_not_in_progress");
		if (!isFinalRunCompletionCandidate(plan, goal)) ulwLoopError(`${goal.id} is not final.`, "ulw_loop_not_final_story");

		const snapshot = await readCodexGoalSnapshotInput(args.codexGoalJson, repoRoot);
		const aggregate = codexGoalMode(plan) === "aggregate";
		const reconciliation = reconcileCodexGoalSnapshot(snapshot, { expectedObjective: expectedCodexObjective(plan, goal), ...(aggregate ? { acceptedObjectives: compatibleCodexObjectives(plan) } : {}), allowedStatuses: ["active"], requireSnapshot: true, requireComplete: false });
		if (!reconciliation.ok) ulwLoopError(reconciliation.errors.join(" "), "ulw_loop_codex_snapshot_mismatch");

		const now = iso();
		for (const field of BLOCKER_FIELDS) Reflect.deleteProperty(goal, field);
		goal.status = "review_blocked";
		goal.reviewBlockedAt = now;
		goal.evidence = args.evidence;
		goal.updatedAt = now;
		if (plan.activeGoalId === goal.id) delete plan.activeGoalId;
		const newGoal = appendBlockerGoal(plan, args, now);
		plan.updatedAt = now;

		const codexGoal = reconciliation.snapshot.raw;
		const blockedEntry: UlwLoopLedgerEntry = { at: now, kind: "goal_review_blocked", goalId: goal.id, status: goal.status, evidence: args.evidence, codexGoal };
		const addedEntry: UlwLoopLedgerEntry = { at: now, kind: "goal_added", goalId: newGoal.id, status: newGoal.status, evidence: args.evidence, message: newGoal.title };
		const summaryEntry: UlwLoopLedgerEntry = { at: now, kind: "goal_review_blocked", goalId: goal.id, status: goal.status, evidence: args.evidence, codexGoal, message: `Review blockers recorded; appended ${newGoal.id}.` };
		Reflect.set(summaryEntry, "kind", "blocker_recorded");
		const ledgerEntries = [blockedEntry, addedEntry, summaryEntry];
		await writePlan(repoRoot, plan, scope);
		for (const entry of ledgerEntries) await appendLedger(repoRoot, entry, scope);
		return { plan, blockedGoal: goal, newGoal, ledgerEntries };
	});
}

export interface UlwLoopErrorOptions {
	readonly cause?: unknown;
	readonly details?: Record<string, unknown>;
}

export class UlwLoopError extends Error {
	readonly code: string;
	readonly details?: Record<string, unknown>;

	constructor(message: string, code: string, opts?: UlwLoopErrorOptions) {
		super(message, opts?.cause === undefined ? undefined : { cause: opts.cause });
		this.name = "UlwLoopError";
		this.code = code;
		if (opts?.details !== undefined) {
			this.details = opts.details;
		}
	}
}

export function iso(): string {
	return new Date().toISOString();
}

import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { PreToolUsePayload } from "./codex-hook.js";
import { parsePreToolUsePayload } from "./codex-hook.js";
import { isFinalRunCompletionCandidate } from "./goal-status.js";
import { ulwLoopAttemptEvidenceDir, ulwLoopDir } from "./paths.js";
import type { UlwLoopPlan } from "./types.js";

// spawn_agent = v1; collaborationspawn_agent = the delimiter-free flattened v2
// hook token from codex-rs hook_names.rs; collaboration.spawn_agent = the
// dotted token observed live in the task-1 probe (hook-tool-tokens.txt).
const SPAWN_TOOL_TOKENS = new Set(["spawn_agent", "collaborationspawn_agent", "collaboration.spawn_agent"]);
const DEFAULT_FANOUT_LIMIT = 60;
const GATE_MESSAGE_PATTERN = /lazycodex-gate-reviewer|final gate review/i;

export function applySpawnGuards(payload: PreToolUsePayload): string {
	if (payload.hook_event_name !== "PreToolUse" || !SPAWN_TOOL_TOKENS.has(payload.tool_name)) return "";
	const stateDir = ulwLoopDir(payload.cwd, { sessionId: payload.session_id });
	const plan = readPlan(join(stateDir, "goals.json"));
	if (plan === null) return "";
	const fanOutDenial = consumeFanOutBudget(stateDir);
	if (fanOutDenial !== null) return deny(fanOutDenial);
	const missingArtifact = missingGateArtifact(payload, plan);
	if (missingArtifact !== null)
		return deny(`spawn code-review + QA first; gate audits their artifacts: missing ${missingArtifact}`);
	return "";
}

export async function runSpawnGuardCli(stdin: NodeJS.ReadableStream, stdout: NodeJS.WritableStream): Promise<void> {
	try {
		const chunks: Buffer[] = [];
		for await (const chunk of stdin) chunks.push(Buffer.from(chunk));
		const payload = parsePreToolUsePayload(Buffer.concat(chunks).toString("utf8"));
		if (payload === null) return;
		const output = applySpawnGuards(payload);
		if (output.length > 0) stdout.write(output);
	} catch (error) {
		if (error instanceof Error) return;
	}
}

// Per-session spawn counter; depth/lineage tracking is descoped — this is a
// total-volume backstop against fan-out explosions, not a recursion tracker.
function consumeFanOutBudget(stateDir: string): string | null {
	const counterPath = join(stateDir, "spawn-count.json");
	const count = readCount(counterPath) + 1;
	writeFileSync(counterPath, JSON.stringify({ count }));
	const limit = fanOutLimit();
	if (count <= limit) return null;
	return `ulw-loop spawn fan-out cap reached (${count}/${limit}). Consolidate work into the agents already running, or raise OMO_SPAWN_FANOUT_LIMIT if this volume is intentional.`;
}

function missingGateArtifact(payload: PreToolUsePayload, plan: UlwLoopPlan): string | null {
	if (!isGateReviewerSpawn(payload.tool_input)) return null;
	const goal = plan.goals.find((candidate) => isFinalRunCompletionCandidate(plan, candidate));
	if (goal === undefined || goal.status === "complete") return null;
	if (!goal.successCriteria.every((criterion) => criterion.status === "pass")) return null;
	const scope = { sessionId: payload.session_id } as const;
	if (plan.evidenceLayoutVersion === 2) {
		const attemptDir = ulwLoopAttemptEvidenceDir(goal.id, goal.attempt, scope);
		for (const name of [`${goal.id}-code-review.md`, `${goal.id}-manual-qa.md`]) {
			const relative = `${attemptDir}/${name}`;
			if (!isNonEmptyFile(join(payload.cwd, relative))) return relative;
		}
		return null;
	}
	const flatReport = `.omo/evidence/${goal.id}-code-review.md`;
	if (!isNonEmptyFile(join(payload.cwd, flatReport))) return flatReport;
	// v1 manual-QA approximation: any other non-empty evidence file counts.
	if (!hasOtherEvidenceFile(join(payload.cwd, ".omo", "evidence"), `${goal.id}-code-review.md`))
		return `.omo/evidence/<any manual-QA artifact besides ${goal.id}-code-review.md>`;
	return null;
}

function isGateReviewerSpawn(toolInput: unknown): boolean {
	if (typeof toolInput !== "object" || toolInput === null) return false;
	const record = toolInput as Record<string, unknown>;
	const agentType = record["agent_type"];
	if (typeof agentType === "string") return agentType === "lazycodex-gate-reviewer";
	const message = record["message"];
	return typeof message === "string" && GATE_MESSAGE_PATTERN.test(message);
}

function deny(reason: string): string {
	return `${JSON.stringify({
		hookSpecificOutput: {
			hookEventName: "PreToolUse",
			permissionDecision: "deny",
			permissionDecisionReason: reason,
			additionalContext: reason,
		},
	})}\n`;
}

function fanOutLimit(): number {
	const raw = process.env["OMO_SPAWN_FANOUT_LIMIT"];
	if (raw === undefined) return DEFAULT_FANOUT_LIMIT;
	const parsed = Number.parseInt(raw, 10);
	return Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_FANOUT_LIMIT;
}

function isNonEmptyFile(path: string): boolean {
	try {
		return existsSync(path) && statSync(path).size > 0;
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function hasOtherEvidenceFile(evidenceDir: string, excludedName: string): boolean {
	try {
		return readdirSync(evidenceDir).some((name) => name !== excludedName && isNonEmptyFile(join(evidenceDir, name)));
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function readCount(counterPath: string): number {
	try {
		const parsed = JSON.parse(readFileSync(counterPath, "utf8")) as Record<string, unknown>;
		return typeof parsed["count"] === "number" && parsed["count"] >= 0 ? parsed["count"] : 0;
	} catch (error) {
		if (error instanceof Error) return 0;
		throw error;
	}
}

function readPlan(goalsPath: string): UlwLoopPlan | null {
	try {
		return JSON.parse(readFileSync(goalsPath, "utf8")) as UlwLoopPlan;
	} catch (error) {
		if (error instanceof Error) return null;
		throw error;
	}
}

// biome-ignore-all format: compact batch steering module stays below the pure LOC budget.
import type { UlwLoopScope } from "./paths.js";
import { appendLedger, appendLedgerEntries, findAcceptedSteeringLedgerEntry, readUlwLoopPlan, withUlwLoopMutationLock, writePlan } from "./plan-io.js";
import { applySteeringMutation, validateUlwLoopSteeringProposal } from "./steering.js";
import { buildSteeringPlanSnapshot, changedGoalIdsBetween } from "./steering-snapshot.js";
import type { UlwLoopLedgerEntry, UlwLoopPlan, UlwLoopSteeringAudit, UlwLoopSteeringProposal } from "./types.js";
import { iso } from "./types.js";
import { batchUpdateLedgerEntry } from "./validation-batch.js";

export interface SteerUlwLoopBatchItemResult {
	readonly accepted: boolean;
	readonly deduped: boolean;
	readonly audit: UlwLoopSteeringAudit;
	readonly rejectedReasons: readonly string[];
}

export interface SteerUlwLoopBatchResult {
	readonly plan: UlwLoopPlan;
	readonly accepted: boolean;
	readonly results: readonly SteerUlwLoopBatchItemResult[];
	readonly rejectedReasons: readonly string[];
}

type PreparedFresh = {
	readonly proposal: UlwLoopSteeringProposal;
	readonly audit: UlwLoopSteeringAudit;
	readonly before: UlwLoopPlan;
	readonly next: UlwLoopPlan;
};

type PreparedItem =
	| { readonly kind: "deduped"; readonly result: SteerUlwLoopBatchItemResult }
	| { readonly kind: "fresh"; readonly prepared: PreparedFresh };

export async function steerUlwLoopBatch(
	repoRoot: string,
	proposals: readonly UlwLoopSteeringProposal[],
	scope?: UlwLoopScope,
): Promise<SteerUlwLoopBatchResult> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const prepared = await prepareBatch(repoRoot, plan, proposals, scope);
		const failed = prepared.results.find((item) => !item.accepted);
		if (failed !== undefined) {
			const entry = rejectedLedgerEntry(prepared.results);
			await appendLedger(repoRoot, entry, scope);
			return rejected(plan, prepared.results, failed.rejectedReasons);
		}
		let next = plan;
		for (const item of prepared.items) if (item.kind === "fresh") next = item.prepared.next;
		const fresh = prepared.items.filter((item): item is Extract<PreparedItem, { readonly kind: "fresh" }> => item.kind === "fresh");
		if (fresh.length > 0) {
			await writePlan(repoRoot, next, scope);
			const entries = fresh.map((item) => ledgerEntry(item.prepared.proposal, item.prepared.audit, item.prepared.proposal.now?.toISOString() ?? iso()));
			const batchEntry = batchUpdateLedgerEntry(plan, next, iso());
			await appendLedgerEntries(repoRoot, batchEntry === null ? entries : [...entries, batchEntry], scope);
		}
		return { plan: next, accepted: true, results: prepared.results, rejectedReasons: [] };
	});
}

async function prepareBatch(
	repoRoot: string,
	plan: UlwLoopPlan,
	proposals: readonly UlwLoopSteeringProposal[],
	scope: UlwLoopScope | undefined,
): Promise<{ readonly items: readonly PreparedItem[]; readonly results: readonly SteerUlwLoopBatchItemResult[] }> {
	const items: PreparedItem[] = [];
	const results: SteerUlwLoopBatchItemResult[] = [];
	let current = plan;
	for (const proposal of proposals) {
		const key = proposal.idempotencyKey ?? proposal.promptSignature;
		const prior = key === undefined ? undefined : await findAcceptedSteeringLedgerEntry(repoRoot, key, scope);
		if (prior?.steering !== undefined) {
			const result = { accepted: true, deduped: true, audit: { ...prior.steering, deduped: true }, rejectedReasons: [] };
			items.push({ kind: "deduped", result });
			results.push(result);
			continue;
		}
		const audit = validateUlwLoopSteeringProposal(current, proposal);
		if (!audit.invariant.accepted) {
			const result = { accepted: false, deduped: false, audit, rejectedReasons: audit.invariant.rejectedReasons };
			items.push({ kind: "deduped", result });
			results.push(result);
			continue;
		}
		const next = applySteeringMutation(current, proposal, audit);
		const changed = changedGoalIdsBetween(current, next);
		const finalAudit = { ...audit, before: buildSteeringPlanSnapshot(current, changed), after: buildSteeringPlanSnapshot(next, changed) };
		const result = { accepted: true, deduped: false, audit: finalAudit, rejectedReasons: [] };
		items.push({ kind: "fresh", prepared: { proposal, audit: finalAudit, before: current, next } });
		results.push(result);
		current = next;
	}
	return { items, results };
}

function rejected(
	plan: UlwLoopPlan,
	results: readonly SteerUlwLoopBatchItemResult[],
	rejectedReasons: readonly string[],
): SteerUlwLoopBatchResult {
	return { plan, accepted: false, results, rejectedReasons };
}

function rejectedLedgerEntry(results: readonly SteerUlwLoopBatchItemResult[]): UlwLoopLedgerEntry {
	const rejectedItems = results.map((result, index) => ({ result, index })).filter((item) => !item.result.accepted);
	return { at: iso(), kind: "steering_rejected", message: rejectedItems.map((item) => `index ${item.index}: ${item.result.rejectedReasons.join(", ")}`).join("; ") };
}

function ledgerEntry(proposal: UlwLoopSteeringProposal, audit: UlwLoopSteeringAudit, at: string): UlwLoopLedgerEntry {
	const entry: UlwLoopLedgerEntry = {
		at,
		kind: proposal.kind === "revise_criterion" ? "criteria_revised" : "steering_accepted",
		evidence: proposal.evidence,
		message: proposal.rationale,
		steering: audit,
		mutationKind: proposal.kind,
	};
	const goalId = audit.targetGoalIds[0];
	if (goalId !== undefined) entry.goalId = goalId;
	if (proposal.criterionId !== undefined) entry.criterionId = proposal.criterionId;
	if (proposal.idempotencyKey !== undefined) entry.idempotencyKey = proposal.idempotencyKey;
	return entry;
}

// biome-ignore-all format: compact extracted steering mutations stay below the pure LOC budget.
import { seedDefaultSuccessCriteria } from "./plan-crud.js";
import type { UlwLoopItem, UlwLoopPlan, UlwLoopSteeringChildGoal, UlwLoopSteeringProposal, UlwLoopSuccessCriterionUserModel } from "./types.js";
import { ULW_LOOP_SUCCESS_CRITERION_USER_MODELS } from "./types.js";
import { updateBatchesAfterSupersede } from "./validation-batch.js";

const read = (value: object, key: string): unknown => Object.entries(value).find(([name]) => name === key)?.[1];
const isText = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;
const text = (value: object, key: string): string | undefined => { const candidate = read(value, key); return isText(candidate) ? candidate.trim() : undefined; };
const isModel = (value: unknown): value is UlwLoopSuccessCriterionUserModel => typeof value === "string" && ULW_LOOP_SUCCESS_CRITERION_USER_MODELS.some((model) => model === value);
const after = (proposal: object): object | undefined => { const candidate = read(proposal, "after"); return typeof candidate === "object" && candidate !== null && !Array.isArray(candidate) ? candidate : undefined; };
const revised = (proposal: object, direct: string, nested: string): string | undefined => text(proposal, direct) ?? text(after(proposal) ?? proposal, nested);
const targets = (proposal: UlwLoopSteeringProposal): string[] => proposal.targetGoalIds ?? [proposal.targetGoalId ?? text(proposal, "goalId") ?? ""].filter(Boolean);
const child = (value: unknown): UlwLoopSteeringChildGoal | null => {
	if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
	const title = text(value, "title"); const objective = text(value, "objective");
	return title === undefined || objective === undefined ? null : { title, objective };
};
const children = (proposal: UlwLoopSteeringProposal): UlwLoopSteeringChildGoal[] => {
	const direct = proposal.childGoals;
	if (direct !== undefined && direct.length > 0) return direct;
	const nested = after(proposal);
	const fromAfter = nested === undefined ? undefined : read(nested, "children");
	return Array.isArray(fromAfter) ? fromAfter.map(child).filter((item): item is UlwLoopSteeringChildGoal => item !== null) : [];
};
const goal = (plan: UlwLoopPlan, id: string | undefined): UlwLoopItem | undefined => id === undefined ? undefined : plan.goals.find((item) => item.id === id);

function nextId(plan: UlwLoopPlan, offset: number): string {
	const max = plan.goals.reduce((current, item) => { const digits = /^G(\d+)(?:-|$)/u.exec(item.id)?.[1]; return digits === undefined ? current : Math.max(current, Number(digits)); }, 0);
	return `G${String(max + offset).padStart(3, "0")}`;
}

export function makeGoal(plan: UlwLoopPlan, childGoal: UlwLoopSteeringChildGoal, evidence: string, now: string, offset: number): UlwLoopItem {
	const id = nextId(plan, offset); const digits = /^G(\d+)/u.exec(id)?.[1]; const goalIndex = digits === undefined ? plan.goals.length + offset - 1 : Number(digits) - 1;
	return { id, title: childGoal.title, objective: childGoal.objective, status: "pending", successCriteria: seedDefaultSuccessCriteria(goalIndex, childGoal.objective), attempt: 0, createdAt: now, updatedAt: now, evidence };
}

export function reviseWording(plan: UlwLoopPlan, proposal: UlwLoopSteeringProposal, now: string): void {
	const target = goal(plan, targets(proposal)[0]); if (target === undefined) return;
	target.title = revised(proposal, "revisedTitle", "title") ?? target.title; target.objective = revised(proposal, "revisedObjective", "objective") ?? target.objective;
	target.steeringEvidence = proposal.evidence; target.steeringRationale = proposal.rationale; target.updatedAt = now;
}

export function splitOrBlock(plan: UlwLoopPlan, proposal: UlwLoopSteeringProposal, now: string): void {
	const target = goal(plan, targets(proposal)[0]); if (target === undefined) return;
	const replacements = children(proposal).map((item, index) => makeGoal(plan, item, proposal.evidence, now, index + 1));
	target.steeringEvidence = proposal.evidence; target.steeringRationale = proposal.rationale; target.updatedAt = now;
	if (replacements.length === 0) { target.status = "blocked"; target.steeringStatus = "blocked"; target.blockedReason = proposal.blockedReason ?? proposal.rationale; }
	else { target.steeringStatus = "superseded"; target.supersededBy = replacements.map((item) => item.id); for (const item of replacements) item.supersedes = [target.id]; plan.goals.splice(plan.goals.indexOf(target) + 1, 0, ...replacements); updateBatchesAfterSupersede(plan, target.id, replacements.map((item) => item.id)); }
	if (plan.activeGoalId === target.id) delete plan.activeGoalId;
}

export function reviseCriterion(plan: UlwLoopPlan, proposal: UlwLoopSteeringProposal, now: string): void {
	const target = goal(plan, targets(proposal)[0]); const index = target?.successCriteria.findIndex((item) => item.id === proposal.criterionId) ?? -1; const current = target?.successCriteria[index];
	if (target === undefined || current === undefined) return;
	const model = read(proposal, "userModel");
	target.successCriteria[index] = { ...current, scenario: text(proposal, "scenario") ?? current.scenario, expectedEvidence: text(proposal, "expectedEvidence") ?? current.expectedEvidence, userModel: isModel(model) ? model : current.userModel };
	target.updatedAt = now;
}

import type { UlwLoopItem, UlwLoopPlan } from "./domain-types.js";
import type { UlwLoopSteeringPlanSnapshot } from "./steering-types.js";

/**
 * Compact before/after snapshots for steering ledger entries.
 *
 * Ledger entries used to embed the FULL plan (every goal, criterion, and
 * evidence string) twice per audit and twice more at the entry top level.
 * That made each accepted steer O(plan size) on disk, so the ledger grew
 * quadratically over a run, and every dedup scan re-hydrated all of it into
 * memory. A snapshot instead records plan-level counters plus only the goals
 * the mutation actually touched, keeping each entry O(changed goals).
 */
export function buildSteeringPlanSnapshot(
	plan: UlwLoopPlan,
	changedGoalIds: ReadonlySet<string>,
): UlwLoopSteeringPlanSnapshot {
	const snapshot: UlwLoopSteeringPlanSnapshot = {
		updatedAt: plan.updatedAt,
		goalCount: plan.goals.length,
		goalIds: plan.goals.map((goal) => goal.id),
		goals: plan.goals.filter((goal) => changedGoalIds.has(goal.id)),
	};
	return plan.activeGoalId === undefined ? snapshot : { ...snapshot, activeGoalId: plan.activeGoalId };
}

/** Ids of goals that differ between two plans, including added or removed goals. */
export function changedGoalIdsBetween(before: UlwLoopPlan, after: UlwLoopPlan): Set<string> {
	const beforeById = new Map<string, UlwLoopItem>(before.goals.map((goal) => [goal.id, goal]));
	const changed = new Set<string>();
	for (const goal of after.goals) {
		const prior = beforeById.get(goal.id);
		if (prior === undefined || JSON.stringify(prior) !== JSON.stringify(goal)) changed.add(goal.id);
		beforeById.delete(goal.id);
	}
	for (const id of beforeById.keys()) changed.add(id);
	return changed;
}

import type { UlwLoopSteeringMutationKind, UlwLoopSteeringSource } from "./constants.js";
import type { UlwLoopItem, UlwLoopPlan } from "./domain-types.js";

export interface UlwLoopSteeringInvariantResult {
	accepted: boolean;
	structuralInvariantAccepted: boolean;
	evidenceBackedNecessity: boolean;
	noEasierCompletion: boolean;
	rejectedReasons: string[];
	reasons?: string[];
}

export interface UlwLoopSteeringChildGoal {
	title: string;
	objective: string;
}

export interface UlwLoopSteeringAfterPayload {
	title?: string;
	objective?: string;
	pendingGoalIds?: string[];
	children?: UlwLoopSteeringChildGoal[];
}

export interface UlwLoopSteeringProposal {
	kind: UlwLoopSteeringMutationKind;
	source: UlwLoopSteeringSource;
	targetGoalId?: string;
	targetGoalIds?: string[];
	criterionId?: string;
	evidence: string;
	rationale: string;
	title?: string;
	objective?: string;
	childGoals?: UlwLoopSteeringChildGoal[];
	revisedTitle?: string;
	revisedObjective?: string;
	pendingOrder?: string[];
	blockedReason?: string;
	after?: UlwLoopSteeringAfterPayload;
	directiveText?: string;
	promptSignature?: string;
	idempotencyKey?: string;
	now?: Date;
}

export interface UlwLoopSteeringPlanSnapshot {
	readonly updatedAt: string;
	readonly activeGoalId?: string;
	readonly goalCount: number;
	readonly goalIds: readonly string[];
	readonly goals: readonly UlwLoopItem[];
}

export interface UlwLoopSteeringAudit {
	kind: UlwLoopSteeringMutationKind;
	source: UlwLoopSteeringSource;
	targetGoalIds: string[];
	criterionId?: string;
	before?: UlwLoopSteeringPlanSnapshot;
	after?: UlwLoopSteeringPlanSnapshot;
	evidence: string;
	rationale: string;
	invariant: UlwLoopSteeringInvariantResult;
	directiveText?: string;
	promptSignature?: string;
	idempotencyKey?: string;
	deduped?: boolean;
}

export interface SteerUlwLoopResult {
	plan: UlwLoopPlan;
	accepted: boolean;
	audit: UlwLoopSteeringAudit;
	rejectedReasons: string[];
	deduped: boolean;
}

// biome-ignore-all format: compact steering module must stay below the 240 pure-LOC budget
import { isUlwLoopDone } from "./goal-status.js";
import type { UlwLoopScope } from "./paths.js";
import { appendLedger, findAcceptedSteeringLedgerEntry, readUlwLoopPlan, withUlwLoopMutationLock, writePlan } from "./plan-io.js";
import { makeGoal, reviseCriterion, reviseWording, splitOrBlock } from "./steering-mutations.js";
import { buildSteeringPlanSnapshot, changedGoalIdsBetween } from "./steering-snapshot.js";
import type {
	SteerUlwLoopResult,
	UlwLoopItem,
	UlwLoopLedgerEntry,
	UlwLoopPlan,
	UlwLoopSteeringAudit,
	UlwLoopSteeringChildGoal,
	UlwLoopSteeringMutationKind,
	UlwLoopSteeringProposal,
	UlwLoopSteeringSource,
	UlwLoopSuccessCriterionUserModel,
} from "./types.js";
import { iso, ULW_LOOP_STEERING_MUTATION_KINDS, ULW_LOOP_SUCCESS_CRITERION_USER_MODELS } from "./types.js";
import { batchUpdateLedgerEntry } from "./validation-batch.js";

const SOURCES = ["user_prompt_submit", "finding", "cli"] as const satisfies readonly UlwLoopSteeringSource[];
const PROTECTED = new Set(["aggregateCompletion", "codexObjective", "codexObjectiveAliases", "originalConstraints", "qualityGate", "status", "completedAt", "completionStatus"]);
const isObject = (value: unknown): value is object => typeof value === "object" && value !== null; const isPlain = (value: unknown): value is object => isObject(value) && !Array.isArray(value);
const read = (value: object, key: string): unknown => Object.entries(value).find(([name]) => name === key)?.[1];
const isText = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;
const text = (value: object, key: string): string | undefined => {
	const candidate = read(value, key);
	return isText(candidate) ? candidate.trim() : undefined;
};
const isKind = (value: unknown): value is UlwLoopSteeringMutationKind => typeof value === "string" && ULW_LOOP_STEERING_MUTATION_KINDS.some((kind) => kind === value);
const isSource = (value: unknown): value is UlwLoopSteeringSource => typeof value === "string" && SOURCES.some((source) => source === value);
const isModel = (value: unknown): value is UlwLoopSuccessCriterionUserModel => typeof value === "string" && ULW_LOOP_SUCCESS_CRITERION_USER_MODELS.some((model) => model === value);
const texts = (value: object, key: string): string[] => {
	const candidate = read(value, key);
	return Array.isArray(candidate) && candidate.every((item) => typeof item === "string") ? candidate : [];
};

function targets(proposal: object): string[] {
	const many = texts(proposal, "targetGoalIds");
	const one = text(proposal, "targetGoalId") ?? text(proposal, "goalId");
	return many.length > 0 ? many : one === undefined ? [] : [one];
}

const after = (proposal: object): object | undefined => {
	const candidate = read(proposal, "after");
	return isPlain(candidate) ? candidate : undefined;
};
const revised = (proposal: object, direct: string, nested: string): string | undefined => text(proposal, direct) ?? text(after(proposal) ?? proposal, nested);

function child(value: unknown): UlwLoopSteeringChildGoal | null {
	if (!isPlain(value)) return null;
	const title = text(value, "title");
	const objective = text(value, "objective");
	if (title === undefined || objective === undefined) return null;
	return { title, objective };
}

function childValues(proposal: object): unknown[] {
	const direct = read(proposal, "childGoals");
	if (Array.isArray(direct) && direct.length > 0) return direct;
	const nested = after(proposal);
	const fromAfter = nested === undefined ? undefined : read(nested, "children");
	return Array.isArray(fromAfter) ? fromAfter : [];
}

const pendingOrder = (proposal: object): string[] => {
	const direct = texts(proposal, "pendingOrder");
	return direct.length > 0 ? direct : texts(after(proposal) ?? proposal, "pendingGoalIds");
};

function hasProtected(value: unknown): boolean {
	if (!isObject(value)) return false;
	for (const [key, childValue] of Object.entries(value)) if (PROTECTED.has(key) || key.toLowerCase().includes("complete") || hasProtected(childValue)) return true;
	return false;
}

function allText(value: unknown): string {
	if (typeof value === "string") return value;
	return isObject(value) ? Object.values(value).map(allText).filter(Boolean).join("\n") : "";
}

function weakens(value: unknown): boolean {
	const valueText = allText(value).toLowerCase();
	return /\b(skip|bypass|weaken|remove|omit|auto[-\s]?complete|mark complete|complete faster)\b/.test(valueText) && /\b(test|tests|verification|review|quality gate|complete|completion)\b/.test(valueText);
}

function auditFor(proposal: unknown, reasons: string[]): UlwLoopSteeringAudit {
	const object = isPlain(proposal) ? proposal : undefined;
	const kindRaw = object === undefined ? undefined : read(object, "kind");
	const sourceRaw = object === undefined ? undefined : read(object, "source");
	const evidence = object === undefined ? "" : (text(object, "evidence") ?? "");
	const rationale = object === undefined ? "" : (text(object, "rationale") ?? "");
	const audit: UlwLoopSteeringAudit = { kind: isKind(kindRaw) ? kindRaw : "annotate_ledger", source: isSource(sourceRaw) ? sourceRaw : "cli", targetGoalIds: object === undefined ? [] : targets(object), evidence, rationale, invariant: { accepted: reasons.length === 0, structuralInvariantAccepted: reasons.length === 0, evidenceBackedNecessity: evidence.length > 0 && rationale.length > 0, noEasierCompletion: !weakens(proposal), rejectedReasons: reasons, reasons } };
	if (object === undefined) return audit;
	const criterionId = text(object, "criterionId");
	const directiveText = text(object, "directiveText");
	const promptSignature = text(object, "promptSignature");
	const idempotencyKey = text(object, "idempotencyKey");
	if (criterionId !== undefined) audit.criterionId = criterionId;
	if (directiveText !== undefined) audit.directiveText = directiveText;
	if (promptSignature !== undefined) audit.promptSignature = promptSignature;
	if (idempotencyKey !== undefined) audit.idempotencyKey = idempotencyKey;
	return audit;
}

export function validateUlwLoopSteeringProposal(plan: UlwLoopPlan, proposal: unknown): UlwLoopSteeringAudit {
	const reasons: string[] = [];
	if (!isPlain(proposal)) reasons.push("proposal must be an object");
	const object = isPlain(proposal) ? proposal : {};
	const kind = read(object, "kind");
	if (!isKind(kind)) reasons.push(`invalid kind: ${String(kind)}`);
	if (!isSource(read(object, "source"))) reasons.push(`invalid source: ${String(read(object, "source"))}`);
	if (text(object, "evidence") === undefined) reasons.push("missing evidence");
	if (text(object, "rationale") === undefined) reasons.push("missing rationale");
	if (hasProtected(proposal)) reasons.push("protected payload");
	if (weakens(proposal)) reasons.push("weakened completion");
	if (isUlwLoopDone(plan)) reasons.push("plan already complete");
	if (isKind(kind)) validateKind(plan, object, kind, reasons);
	return auditFor(proposal, reasons);
}

function goal(plan: UlwLoopPlan, id: string | undefined): UlwLoopItem | undefined {
	return id === undefined ? undefined : plan.goals.find((item) => item.id === id);
}

function validateKind(plan: UlwLoopPlan, proposal: object, kind: UlwLoopSteeringMutationKind, reasons: string[]): void {
	const target = goal(plan, targets(proposal)[0]);
	if (kind === "add_subgoal" && (text(proposal, "title") === undefined || text(proposal, "objective") === undefined)) reasons.push("add_subgoal requires title/objective");
	if ((kind === "split_subgoal" || kind === "revise_pending_wording" || kind === "mark_blocked_superseded") && target === undefined) reasons.push(`${kind} requires target`);
	if ((kind === "split_subgoal" || kind === "revise_pending_wording") && target !== undefined && target.status !== "pending") reasons.push(`${kind} requires pending target`);
	const rawChildren = childValues(proposal);
	if (kind === "split_subgoal" && rawChildren.length === 0) reasons.push("split_subgoal requires children");
	if ((kind === "split_subgoal" || kind === "mark_blocked_superseded") && rawChildren.some((item) => child(item) === null)) reasons.push(`${kind} children require title/objective`);
	if (kind === "reorder_pending") validateOrder(plan, proposal, reasons);
	if (kind === "revise_pending_wording" && revised(proposal, "revisedTitle", "title") === undefined && revised(proposal, "revisedObjective", "objective") === undefined) reasons.push("revise_pending_wording requires update");
	if (kind === "revise_criterion") validateCriterion(plan, proposal, reasons);
}

function validateOrder(plan: UlwLoopPlan, proposal: object, reasons: string[]): void {
	const requested = pendingOrder(proposal);
	const pending = plan.goals.filter((item) => item.status === "pending" && item.steeringStatus === undefined).map((item) => item.id);
	if (requested.length === 0) reasons.push("reorder_pending requires ids");
	if (new Set(requested).size !== requested.length) reasons.push("duplicate pending id");
	if (requested.some((id) => !pending.includes(id))) reasons.push("unknown pending id");
}

function validateCriterion(plan: UlwLoopPlan, proposal: object, reasons: string[]): void {
	const target = goal(plan, targets(proposal)[0]);
	const criterionId = text(proposal, "criterionId");
	if (target === undefined) reasons.push("revise_criterion requires goalId");
	else if (criterionId === undefined || target.successCriteria.every((item) => item.id !== criterionId)) reasons.push("revise_criterion requires criterionId");
	const model = read(proposal, "userModel");
	if (read(proposal, "scenario") === undefined && read(proposal, "expectedEvidence") === undefined && model === undefined) reasons.push("revise_criterion requires update");
	if (model !== undefined && !isModel(model)) reasons.push("invalid userModel");
}

export function applySteeringMutation(plan: UlwLoopPlan, proposal: UlwLoopSteeringProposal, audit: UlwLoopSteeringAudit): UlwLoopPlan {
	const next = structuredClone(plan);
	if (!audit.invariant.accepted) return next;
	const now = proposal.now?.toISOString() ?? iso();
	if (proposal.kind === "add_subgoal") next.goals.push(makeGoal(next, { title: proposal.title ?? "", objective: proposal.objective ?? "" }, proposal.evidence, now, 1));
	if (proposal.kind === "reorder_pending") {
		const order = pendingOrder(proposal);
		next.goals = [...order.map((id) => goal(next, id)).filter((item): item is UlwLoopItem => item !== undefined), ...next.goals.filter((item) => !order.includes(item.id))];
	}
	if (proposal.kind === "revise_pending_wording") reviseWording(next, proposal, now);
	if (proposal.kind === "split_subgoal" || proposal.kind === "mark_blocked_superseded") splitOrBlock(next, proposal, now);
	if (proposal.kind === "revise_criterion") reviseCriterion(next, proposal, now);
	if (proposal.kind !== "annotate_ledger") next.updatedAt = now;
	return next;
}

function isProposal(value: unknown): value is UlwLoopSteeringProposal {
	return isPlain(value) && isKind(read(value, "kind")) && isSource(read(value, "source")) && isText(read(value, "evidence")) && isText(read(value, "rationale"));
}

export function parseUlwLoopSteeringDirective(text: string): UlwLoopSteeringProposal | null {
	const match = /(?:^|\s)(?:OMO_ULW_LOOP_STEER|omo\.ulw-loop\.steer|omo ulw-loop steer|omo-agent-toolkit ulw-loop steer):\s*([\s\S]+)$/u.exec(text);
	if (match?.[1] === undefined) return null;
	try {
		const parsed: unknown = JSON.parse(match[1].trim());
		return isProposal(parsed) ? parsed : null;
	} catch (error) {
		if (error instanceof SyntaxError) return null;
		throw error;
	}
}

export async function steerUlwLoop(repoRoot: string, proposal: UlwLoopSteeringProposal, scope?: UlwLoopScope): Promise<SteerUlwLoopResult> {
	return withUlwLoopMutationLock(repoRoot, scope, async () => {
		const plan = await readUlwLoopPlan(repoRoot, scope);
		const key = proposal.idempotencyKey ?? proposal.promptSignature;
		const prior = key === undefined ? undefined : await findAcceptedSteeringLedgerEntry(repoRoot, key, scope);
		if (prior?.steering !== undefined) {
			// Legacy entries embedded full-plan before/after snapshots; never
			// re-surface those multi-MB payloads on the dedup path.
			const { before: _before, after: _after, ...compactPrior } = prior.steering;
			return { plan, accepted: true, audit: { ...compactPrior, deduped: true }, rejectedReasons: [], deduped: true };
		}
		const audit = validateUlwLoopSteeringProposal(plan, proposal);
		const accepted = audit.invariant.accepted;
		const next = accepted ? applySteeringMutation(plan, proposal, audit) : plan;
		const finalAudit: UlwLoopSteeringAudit = { ...audit };
		if (accepted) {
			const changed = changedGoalIdsBetween(plan, next);
			finalAudit.before = buildSteeringPlanSnapshot(plan, changed);
			finalAudit.after = buildSteeringPlanSnapshot(next, changed);
		}
		const at = proposal.now?.toISOString() ?? iso();
		const batchEntry = accepted ? batchUpdateLedgerEntry(plan, next, at) : null;
		if (accepted) await writePlan(repoRoot, next, scope);
		await appendLedger(repoRoot, ledgerEntry(proposal, finalAudit, at), scope);
		if (batchEntry !== null) await appendLedger(repoRoot, batchEntry, scope);
		return { plan: next, accepted, audit: finalAudit, rejectedReasons: audit.invariant.rejectedReasons, deduped: false };
	});
}

function ledgerEntry(proposal: UlwLoopSteeringProposal, audit: UlwLoopSteeringAudit, at: string): UlwLoopLedgerEntry {
	const entry: UlwLoopLedgerEntry = { at, kind: audit.invariant.accepted ? (proposal.kind === "revise_criterion" ? "criteria_revised" : "steering_accepted") : "steering_rejected", evidence: proposal.evidence, message: proposal.rationale, steering: audit, mutationKind: proposal.kind };
	const goalId = audit.targetGoalIds[0];
	if (goalId !== undefined) entry.goalId = goalId;
	if (proposal.criterionId !== undefined) entry.criterionId = proposal.criterionId;
	if (proposal.idempotencyKey !== undefined) entry.idempotencyKey = proposal.idempotencyKey;
	return entry;
}

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { isAbsolute, join, resolve, sep } from "node:path";

import { normalizeUlwLoopSessionId, ulwLoopDir } from "./paths.js";
import type { UlwLoopItem, UlwLoopPlan } from "./types.js";

// Turn-death recovery only: Codex emits Stop when a turn ends, so a run that
// dies mid-turn (crash, kill, context blowup before any Stop) never reaches
// this handler. Mid-turn stalls are out of scope by design.

const RESUME_CAP = 2;

// Mirrors start-work-continuation's context-pressure bail-out: injecting a
// resume directive into an already-overflowing context makes things worse.
const CONTEXT_PRESSURE_MARKERS = [
	"context compacted",
	"context_length_exceeded",
	"skill descriptions were shortened",
	"context_too_large",
	"codex ran out of room in the model's context window",
	"your input exceeds the context window",
	"long threads and multiple compactions",
] as const;

interface StopPayload {
	readonly session_id: string;
	readonly cwd: string;
	readonly transcript_path: string;
	readonly stop_hook_active: boolean;
}

export function runStopResumeHook(input: unknown): string {
	const payload = parseStopPayload(input);
	if (payload === null || payload.stop_hook_active) return "";
	if (transcriptShowsContextPressure(payload.transcript_path)) return "";
	if (boulderContinuationWillFire(payload.cwd, payload.session_id)) return "";
	const stateDir = ulwLoopDir(payload.cwd, { sessionId: payload.session_id });
	const plan = readPlan(join(stateDir, "goals.json"));
	if (plan === null || plan.aggregateCompletion?.status === "complete") return "";
	const goal = resumableGoal(plan);
	if (goal === undefined) return "";
	if (!consumeResumeBudget(stateDir, goal.id)) return "";
	const output: { decision: "block"; reason: string } = {
		decision: "block",
		reason: renderResumeDirective(plan, goal, payload.session_id),
	};
	return JSON.stringify(output);
}

export async function runStopResumeHookCli(stdin: NodeJS.ReadableStream, stdout: NodeJS.WritableStream): Promise<void> {
	try {
		const chunks: Buffer[] = [];
		for await (const chunk of stdin) chunks.push(Buffer.from(chunk));
		const output = runStopResumeHook(JSON.parse(Buffer.concat(chunks).toString("utf8")));
		if (output.length > 0) stdout.write(output);
	} catch (error) {
		if (error instanceof Error) return;
	}
}

function resumableGoal(plan: UlwLoopPlan): UlwLoopItem | undefined {
	const active = plan.goals.find((goal) => goal.id === plan.activeGoalId);
	if (active !== undefined && isResumableStatus(active.status)) return active;
	return plan.goals.find((goal) => isResumableStatus(goal.status));
}

function isResumableStatus(status: UlwLoopItem["status"]): boolean {
	return status === "pending" || status === "in_progress";
}

// Two-strike cap keyed on ledger movement: an unchanged ledger.jsonl line
// count across resumes means the loop is not progressing. The stuck marker is
// a separate file — a ledger append would change the count and self-reset.
function consumeResumeBudget(stateDir: string, goalId: string): boolean {
	const ledgerLineCount = countLedgerLines(join(stateDir, "ledger.jsonl"));
	const counterPath = resolve(stateDir, `auto-resume-${goalId}.json`);
	const stuckPath = resolve(stateDir, `auto-resume-${goalId}.stuck`);
	// goals.json is untrusted input: a crafted goal id (e.g. `../../x`) must
	// never drive a write outside the session state dir. Deny the resume.
	if (!isInsideDir(stateDir, counterPath) || !isInsideDir(stateDir, stuckPath)) return false;
	const previous = readCounter(counterPath);
	const count = previous !== null && previous.ledgerLineCount === ledgerLineCount ? previous.count : 0;
	if (count >= RESUME_CAP) {
		writeFileSync(stuckPath, `no ledger progress after ${count} resumes\n`);
		return false;
	}
	writeFileSync(counterPath, JSON.stringify({ count: count + 1, ledgerLineCount }));
	return true;
}

function isInsideDir(dir: string, candidate: string): boolean {
	return candidate.startsWith(resolve(dir) + sep);
}

function renderResumeDirective(plan: UlwLoopPlan, goal: UlwLoopItem, sessionId: string): string {
	const normalized = normalizeUlwLoopSessionId(sessionId);
	const option =
		normalized !== null && plan.goalsPath.includes(`/${normalized}/`) ? ` --session-id ${normalized}` : "";
	return [
		`The ulw-loop run in this session still has unfinished goals (next: ${goal.id} — ${goal.title}).`,
		"The turn ended before the loop completed. Resume it now:",
		`1. Run \`omo-agent-toolkit ulw-loop status${option} --json\` to reload the plan, the active goal, and currentAttemptDir.`,
		"2. Continue the active goal's remaining success criteria, recording evidence with record-evidence.",
		`3. Checkpoint through \`omo-agent-toolkit ulw-loop checkpoint${option}\` when the goal's criteria are proven; a complete checkpoint prints the next goal instruction.`,
		"If the loop is genuinely blocked on the user, checkpoint the goal as blocked with the reason instead.",
	].join("\n");
}

function readPlan(goalsPath: string): UlwLoopPlan | null {
	try {
		return JSON.parse(readFileSync(goalsPath, "utf8")) as UlwLoopPlan;
	} catch (error) {
		if (error instanceof Error) return null;
		throw error;
	}
}

function countLedgerLines(ledgerPath: string): number {
	try {
		return readFileSync(ledgerPath, "utf8").split("\n").filter(Boolean).length;
	} catch (error) {
		if (error instanceof Error) return 0;
		throw error;
	}
}

function readCounter(counterPath: string): { count: number; ledgerLineCount: number } | null {
	try {
		if (!existsSync(counterPath)) return null;
		const parsed = JSON.parse(readFileSync(counterPath, "utf8")) as Record<string, unknown>;
		if (typeof parsed["count"] !== "number" || typeof parsed["ledgerLineCount"] !== "number") return null;
		return { count: parsed["count"], ledgerLineCount: parsed["ledgerLineCount"] };
	} catch (error) {
		if (error instanceof Error) return null;
		throw error;
	}
}

// Local ~10-LOC approximation of start-work-continuation's boulder check (no
// cross-component import allowed): any continuable work for this session means
// that hook owns the Stop event, so this one stays silent.
function boulderContinuationWillFire(cwd: string, sessionId: string): boolean {
	try {
		const raw = JSON.parse(readFileSync(join(cwd, ".omo", "boulder.json"), "utf8")) as Record<string, unknown>;
		const works = raw["works"];
		// The flat legacy shape has no works map: the top level is the single work.
		const entries = typeof works === "object" && works !== null ? Object.values(works) : [raw];
		return entries.some((work) => {
			if (typeof work !== "object" || work === null) return false;
			const entry = work as Record<string, unknown>;
			const sessionIds = Array.isArray(entry["session_ids"]) ? entry["session_ids"] : [];
			const continuable = entry["status"] === "active" || entry["status"] === "paused";
			return continuable && sessionIds.includes(`codex:${sessionId}`) && boulderPlanHasChecklist(cwd, entry);
		});
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

function transcriptShowsContextPressure(transcriptPath: string): boolean {
	try {
		const transcript = readFileSync(transcriptPath, "utf8").toLowerCase();
		return CONTEXT_PRESSURE_MARKERS.some((marker) => transcript.includes(marker));
	} catch (error) {
		if (error instanceof Error) return false;
		throw error;
	}
}

// start-work-continuation owns an active Boulder plan until its final gate marks
// the work complete, including the zero-remaining checklist state.
function boulderPlanHasChecklist(cwd: string, entry: Record<string, unknown>): boolean {
	const activePlan = entry["active_plan"];
	if (typeof activePlan !== "string" || activePlan.trim().length === 0) return false;
	const planPath = isAbsolute(activePlan) ? activePlan : join(cwd, activePlan);
	const worktree = entry["worktree_path"];
	const candidates =
		typeof worktree === "string" && worktree.trim().length > 0 && !isAbsolute(activePlan)
			? [join(isAbsolute(worktree) ? worktree : join(cwd, worktree), activePlan), planPath]
			: [planPath];
	for (const candidate of candidates) {
		try {
			return readFileSync(candidate, "utf8")
				.split(/\r?\n/)
				.some((line) => line.startsWith("- [ ] ") || line.startsWith("- [x] ") || line.startsWith("- [X] "));
		} catch (error) {
			if (!(error instanceof Error)) throw error;
		}
	}
	return false;
}

function parseStopPayload(value: unknown): StopPayload | null {
	if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
	const record = value as Record<string, unknown>;
	const optionalMessage = record["last_assistant_message"];
	const valid =
		record["hook_event_name"] === "Stop" &&
		typeof record["session_id"] === "string" &&
		typeof record["turn_id"] === "string" &&
		typeof record["transcript_path"] === "string" &&
		typeof record["cwd"] === "string" &&
		typeof record["model"] === "string" &&
		typeof record["permission_mode"] === "string" &&
		typeof record["stop_hook_active"] === "boolean" &&
		(optionalMessage === undefined || typeof optionalMessage === "string");
	if (!valid) return null;
	return {
		session_id: record["session_id"] as string,
		cwd: record["cwd"] as string,
		transcript_path: record["transcript_path"] as string,
		stop_hook_active: record["stop_hook_active"] as boolean,
	};
}

export * from "./command-types.js";
export * from "./constants.js";
export * from "./domain-types.js";
