		expect(applySpawnGuards(payload("spawn_agent", { message: "scan" }))).toBe("");
		expect(applySpawnGuards(payload("spawn_agent", { message: "scan" }))).toBe("");
		const fourth = applySpawnGuards(payload("spawn_agent", { message: "scan" }));

		const output = deny(fourth);
