		goalsPath: ".omo/ulw-loop/goals.json",
		ledgerPath: ".omo/ulw-loop/ledger.jsonl",
		goals,
		...overrides,
	};
}

describe("changedGoalIdsBetween", () => {
	it.each([
		{
			name: "added goal",
			before: [goal("G001"), goal("G002")],
			after: [goal("G001"), goal("G002"), goal("G003")],
			expected: ["G003"],
		},
		{
			name: "removed goal",
			before: [goal("G001"), goal("G002")],
			after: [goal("G001")],
			expected: ["G002"],
		},
		{
			name: "mutated goal",
			before: [goal("G001"), goal("G002")],
			after: [goal("G001"), goal("G002", { title: "Rewritten" })],
			expected: ["G002"],
		},
		{
			name: "reordered-only goals",
			before: [goal("G001"), goal("G002"), goal("G003")],
			after: [goal("G003"), goal("G001"), goal("G002")],
			expected: [],
		},
		{
			name: "identical plans",
			before: [goal("G001"), goal("G002")],
			after: [goal("G001"), goal("G002")],
			expected: [],
		},
		{
			name: "add + remove + mutate at once",
			before: [goal("G001"), goal("G002"), goal("G003")],
			after: [goal("G001", { status: "blocked" }), goal("G003"), goal("G004")],
			expected: ["G001", "G002", "G004"],
		},
	])("detects $name", ({ before, after, expected }) => {
		// when
		const changed = changedGoalIdsBetween(plan(before), plan(after));

		// then
		expect([...changed].sort()).toEqual(expected);
	});
});

describe("buildSteeringPlanSnapshot", () => {
	it("includes only changed goals while keeping full goalIds order and goalCount", () => {
		// given
		const goals = [goal("G001"), goal("G002"), goal("G003"), goal("G004")];
		const source = plan(goals);

		// when
		const snapshot = buildSteeringPlanSnapshot(source, new Set(["G003"]));

		// then
		expect(snapshot.goals.map((item) => item.id)).toEqual(["G003"]);
		expect(snapshot.goals[0]).toEqual(goals[2]);
		expect(snapshot.goalIds).toEqual(["G001", "G002", "G003", "G004"]);
		expect(snapshot.goalCount).toBe(4);
		expect(snapshot.updatedAt).toBe(NOW);
	});

	it("omits the activeGoalId key entirely when the plan has none", () => {
		// when
		const snapshot = buildSteeringPlanSnapshot(plan([goal("G001")]), new Set(["G001"]));

		// then
		expect("activeGoalId" in snapshot).toBe(false);
	});

	it("carries activeGoalId when the plan has one", () => {
		// when
		const snapshot = buildSteeringPlanSnapshot(plan([goal("G001")], { activeGoalId: "G001" }), new Set());

		// then
		expect(snapshot.activeGoalId).toBe("G001");
	});

	it("keeps plan order for changed goals regardless of set insertion order", () => {
		// given
		const source = plan([goal("G001"), goal("G002"), goal("G003")]);

		// when
		const snapshot = buildSteeringPlanSnapshot(source, new Set(["G003", "G001"]));

		// then
		expect(snapshot.goals.map((item) => item.id)).toEqual(["G001", "G003"]);
	});
});

import { appendFile, mkdtemp, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { ulwLoopGoalsPath, ulwLoopLedgerPath } from "../src/paths.js";
import { readSteeringLedgerEntries, readUlwLoopPlan, writePlan } from "../src/plan-io.js";
import {
	applySteeringMutation,
	parseUlwLoopSteeringDirective,
	steerUlwLoop,
	validateUlwLoopSteeringProposal,
} from "../src/steering.js";
import type {
	UlwLoopItem,
	UlwLoopLedgerEntry,
	UlwLoopPlan,
	UlwLoopSteeringProposal,
	UlwLoopSuccessCriterion,
	UlwLoopSuccessCriterionUserModel,
} from "../src/types.js";

const NOW = "2026-05-23T00:00:00.000Z";

type CriterionSteeringFields = {
	readonly goalId?: string;
	readonly scenario?: string;
	readonly expectedEvidence?: string;
	readonly userModel?: UlwLoopSuccessCriterionUserModel;
};
type SteeringInput = UlwLoopSteeringProposal & CriterionSteeringFields;

function criterion(overrides: Partial<UlwLoopSuccessCriterion> = {}): UlwLoopSuccessCriterion {
	return {
		id: "C001",
		scenario: "old scenario",
		userModel: "happy",
		expectedEvidence: "vague evidence",
		capturedEvidence: null,
		status: "pending",
		...overrides,
	};
}

function goal(overrides: Partial<UlwLoopItem> = {}): UlwLoopItem {
	return {
		id: "G001",
		title: "Build auth service",
		objective: "Implement JWT auth endpoint",
		status: "pending",
		successCriteria: [criterion(), criterion({ id: "C002", status: "pass" })],
		attempt: 0,
		createdAt: NOW,
		updatedAt: NOW,
		...overrides,
	};
}

function plan(overrides: Partial<UlwLoopPlan> = {}): UlwLoopPlan {
	return {
		version: 1,
		createdAt: NOW,
		updatedAt: NOW,
		briefPath: ".omo/ulw-loop/brief.md",
		goalsPath: ".omo/ulw-loop/goals.json",
		ledgerPath: ".omo/ulw-loop/ledger.jsonl",
		goals: [
			goal(),
			goal({ id: "G002", title: "Rate limit", objective: "Throttle login" }),
			goal({ id: "G003", status: "complete" }),
		],
		...overrides,
	};
}

function steering(overrides: Partial<SteeringInput> = {}): SteeringInput {
	return {
		kind: "add_subgoal",
		source: "cli",
		evidence: "observable blocker evidence",
		rationale: "the plan must change to stay safe",
		title: "Investigate auth blocker",
		objective: "Validate the blocker, capture evidence, and report findings.",
		...overrides,
	};
}

async function repoWithPlan(seed: UlwLoopPlan = plan()): Promise<string> {
	const repoRoot = await mkdtemp(join(tmpdir(), "ug-steer-"));
	await writePlan(repoRoot, seed);
	return repoRoot;
}

describe("validateUlwLoopSteeringProposal", () => {
	it("accepts valid add_subgoal", async () => {
		const proposal: unknown = JSON.parse(
			await readFile(join(process.cwd(), "test/fixtures/steering-proposal.json"), "utf8"),
		);
		expect(validateUlwLoopSteeringProposal(plan(), proposal).invariant.accepted).toBe(true);
	});

	it.each([
		["missing evidence", { evidence: "" }],
		["missing rationale", { rationale: "" }],
		["unknown kind", { kind: "teleport_goal" }],
		["protected payload mutations", { after: { codexObjective: "replace", qualityGate: { status: "passed" } } }],
		["weakened completion text", { objective: "skip tests and mark complete faster" }],
	])("rejects %s", (_name, overrides) => {
		const audit = validateUlwLoopSteeringProposal(plan(), { ...steering(), ...overrides });
		expect(audit.invariant.accepted).toBe(false);
		expect(audit.invariant.rejectedReasons.length).toBeGreaterThan(0);
	});

	it("rejects when plan already complete", () => {
		const done = plan({ goals: [goal({ status: "complete" }), goal({ id: "G002", status: "complete" })] });
		expect(validateUlwLoopSteeringProposal(done, steering()).invariant.accepted).toBe(false);
	});

	it("rejects split_subgoal without children", () => {
		const audit = validateUlwLoopSteeringProposal(plan(), steering({ kind: "split_subgoal", targetGoalId: "G001" }));
		expect(audit.invariant.accepted).toBe(false);
	});

	it("rejects reorder_pending with unknown goal id", () => {
		const audit = validateUlwLoopSteeringProposal(
			plan(),
			steering({ kind: "reorder_pending", pendingOrder: ["missing"] }),
		);
		expect(audit.invariant.accepted).toBe(false);
	});

	it.each([
		["new scenario", { scenario: "new precise scenario" }],
		["new expectedEvidence", { expectedEvidence: "specific command output" }],
	])("accepts valid revise_criterion with %s", (_name, update) => {
		const audit = validateUlwLoopSteeringProposal(
			plan(),
			steering({ kind: "revise_criterion", goalId: "G001", criterionId: "C001", ...update }),
		);
		expect(audit.invariant.accepted).toBe(true);
	});

	it.each([
		["unknown goalId", { goalId: "missing", criterionId: "C001", scenario: "new" }],
		["unknown criterionId", { goalId: "G001", criterionId: "missing", scenario: "new" }],
		["no updates", { goalId: "G001", criterionId: "C001" }],
	])("rejects revise_criterion with %s", (_name, overrides) => {
		const audit = validateUlwLoopSteeringProposal(plan(), steering({ kind: "revise_criterion", ...overrides }));
		expect(audit.invariant.accepted).toBe(false);
	});
});

describe("steerUlwLoop", () => {
	describe("steering-created goals", () => {
		function sluggedPlan(): UlwLoopPlan {
			return plan({
				goals: [
					goal({ id: "G001-goal-a", title: "Goal A", objective: "Do A" }),
					goal({ id: "G002-goal-b", title: "Goal B", objective: "Do B" }),
				],
			});
		}

		for (const [name, proposal, goalIndex] of [
			["add_subgoal: uses next numeric id + default success criteria", steering({ idempotencyKey: "slug-add" }), -1],
			[
				"split_subgoal: replacement goals use default success criteria",
				steering({
					kind: "split_subgoal",
					targetGoalId: "G001-goal-a",
					childGoals: [{ title: "Child A", objective: "Do child A" }],
				}),
				1,
			],
			[
				"mark_blocked_superseded: replacement goals use default success criteria",
				steering({
					kind: "mark_blocked_superseded",
					targetGoalId: "G001-goal-a",
					childGoals: [{ title: "Replacement", objective: "Replace blocked path" }],
				}),
				1,
			],
		] as const) {
			it(name, async () => {
				const repoRoot = await repoWithPlan(sluggedPlan());
				const result = await steerUlwLoop(repoRoot, proposal);
				const createdGoal = goalIndex === -1 ? result.plan.goals.at(-1) : result.plan.goals[goalIndex];
				expect(createdGoal).toMatchObject({
					id: "G003",
					successCriteria: [{ id: "C001" }, { id: "C002" }, { id: "C003" }],
				});
			});
		}
	});

	it("add_subgoal: appends goal + ledger entry", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(repoRoot, steering({ idempotencyKey: "add" }));
		const persisted = await readUlwLoopPlan(repoRoot);
		expect(result.accepted).toBe(true);
		expect(persisted.goals.at(-1)).toMatchObject({ id: "G004", title: "Investigate auth blocker" });
		expect((await readSteeringLedgerEntries(repoRoot)).at(-1)).toMatchObject({
			kind: "steering_accepted",
			mutationKind: "add_subgoal",
		});
	});

	it("split_subgoal: creates children + supersedes parent", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(
			repoRoot,
			steering({
				kind: "split_subgoal",
				targetGoalId: "G001",
				childGoals: [{ title: "Child", objective: "Do child" }],
			}),
		);
		expect(result.plan.goals.map((item) => item.id).slice(0, 2)).toEqual(["G001", "G004"]);
		expect(result.plan.goals[0]).toMatchObject({ steeringStatus: "superseded", supersededBy: ["G004"] });
	});

	it("reorder_pending: changes goal order", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(
			repoRoot,
			steering({ kind: "reorder_pending", pendingOrder: ["G002", "G001"] }),
		);
		expect(result.plan.goals.map((item) => item.id).slice(0, 2)).toEqual(["G002", "G001"]);
	});

	it("revise_pending_wording: updates title/objective", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(
			repoRoot,
			steering({
				kind: "revise_pending_wording",
				targetGoalId: "G001",
				revisedTitle: "Build safer auth",
				revisedObjective: "Implement guarded JWT auth",
			}),
		);
		expect(result.plan.goals[0]).toMatchObject({
			title: "Build safer auth",
			objective: "Implement guarded JWT auth",
		});
	});

	it("annotate_ledger: ledger-only, no plan mutation", async () => {
		const seed = plan();
		const repoRoot = await repoWithPlan(seed);
		const result = await steerUlwLoop(repoRoot, steering({ kind: "annotate_ledger" }));
		expect(result.plan.goals).toEqual(seed.goals);
		expect(await readFile(ulwLoopGoalsPath(repoRoot), "utf8")).toBe(`${JSON.stringify(seed, null, 2)}\n`);
	});

	it("mark_blocked_superseded with children: supersede + replace", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(
			repoRoot,
			steering({
				kind: "mark_blocked_superseded",
				targetGoalId: "G001",
				childGoals: [{ title: "Replacement", objective: "Replace blocked path" }],
			}),
		);
		expect(result.plan.goals[0]).toMatchObject({ steeringStatus: "superseded", supersededBy: ["G004"] });
		expect(result.plan.goals[1]).toMatchObject({ id: "G004", supersedes: ["G001"] });
	});

	it("mark_blocked_superseded without children: blocks goal", async () => {
		const repoRoot = await repoWithPlan();
		const result = await steerUlwLoop(
			repoRoot,
			steering({ kind: "mark_blocked_superseded", targetGoalId: "G001", blockedReason: "external blocker" }),
		);
		expect(result.plan.goals[0]).toMatchObject({
			status: "blocked",
			steeringStatus: "blocked",
			blockedReason: "external blocker",
		});
	});

	it.each(["pending", "pass"] as const)("revise_criterion: works on a %s criterion", async (status) => {
		const repoRoot = await repoWithPlan();
		const criterionId = status === "pending" ? "C001" : "C002";
		const result = await steerUlwLoop(
			repoRoot,
			steering({
				kind: "revise_criterion",
				goalId: "G001",
				criterionId,
				scenario: "new scenario",
				expectedEvidence: "precise evidence",
			}),
		);
		const updated = result.plan.goals[0]?.successCriteria.find((item) => item.id === criterionId);
		expect(updated).toMatchObject({ scenario: "new scenario", expectedEvidence: "precise evidence", status });
		expect((await readSteeringLedgerEntries(repoRoot)).at(-1)).toMatchObject({
			kind: "criteria_revised",
			criterionId,
		});
	});

	it("revise_criterion: updates the targeted criterion in plan", () => {
		const audit = validateUlwLoopSteeringProposal(
			plan(),
			steering({ kind: "revise_criterion", goalId: "G001", criterionId: "C001", scenario: "new value" }),
		);
		const next = applySteeringMutation(
			plan(),
			steering({ kind: "revise_criterion", goalId: "G001", criterionId: "C001", scenario: "new value" }),
			audit,
		);
		expect(next.goals[0]?.successCriteria[0]?.scenario).toBe("new value");
	});

	it("idempotency: same idempotencyKey produces deduped true second time", async () => {
		const repoRoot = await repoWithPlan();
		await steerUlwLoop(repoRoot, steering({ idempotencyKey: "same-key" }));
		const second = await steerUlwLoop(repoRoot, steering({ idempotencyKey: "same-key" }));
		expect(second.deduped).toBe(true);
		expect((await readUlwLoopPlan(repoRoot)).goals).toHaveLength(4);
	});

	describe("compact steering ledger entries", () => {
		const DETAIL = "evidence detail ".repeat(200);

		function fatGoal(id: string): UlwLoopItem {
			return goal({
				id,
				title: `Fat goal ${id}`,
				objective: `Objective ${id}: ${DETAIL}`,
				evidence: DETAIL,
				successCriteria: [
					criterion({ id: "C001", scenario: DETAIL, expectedEvidence: DETAIL }),
					criterion({ id: "C002", scenario: DETAIL, expectedEvidence: DETAIL }),
				],
			});
		}

		function fatPlan(): UlwLoopPlan {
			return plan({
				goals: Array.from({ length: 20 }, (_, index) => fatGoal(`G${String(index + 1).padStart(3, "0")}`)),
			});
		}

		it("writes an O(changed goals) ledger entry instead of embedding the full plan", async () => {
			// given
			const seed = fatPlan();
			const planBytes = JSON.stringify(seed).length;
			const repoRoot = await repoWithPlan(seed);

			// when
			await steerUlwLoop(
				repoRoot,
				steering({ kind: "revise_pending_wording", targetGoalId: "G010", revisedTitle: "Sharper goal ten" }),
			);

			// then
			const lines = (await readFile(ulwLoopLedgerPath(repoRoot), "utf8")).split("\n").filter(Boolean);
			expect(lines).toHaveLength(1);
			const line = lines[0] ?? "";
			expect(line.length).toBeLessThan(planBytes / 4);
			const entry: UlwLoopLedgerEntry = JSON.parse(line);
			expect("before" in entry).toBe(false);
			expect("after" in entry).toBe(false);
			expect(entry.steering?.before?.goals.map((item) => item.id)).toEqual(["G010"]);
			expect(entry.steering?.after?.goals.map((item) => item.id)).toEqual(["G010"]);
			expect(entry.steering?.after?.goals[0]?.title).toBe("Sharper goal ten");
			expect(entry.steering?.before?.goalCount).toBe(20);
			expect(entry.steering?.before?.goalIds).toEqual(seed.goals.map((item) => item.id));
		});
	});

	it("dedup against a legacy full-plan entry strips before/after from the returned audit", async () => {
		// given
		const seed = plan();
		const repoRoot = await repoWithPlan(seed);
		const legacyLine = JSON.stringify({
			at: NOW,
			kind: "steering_accepted",
			goalId: "G001",
			idempotencyKey: "legacy-key",
			evidence: "observable blocker evidence",
			message: "the plan must change to stay safe",
			mutationKind: "revise_pending_wording",
			steering: {
				kind: "revise_pending_wording",
				source: "cli",
				targetGoalIds: ["G001"],
				evidence: "observable blocker evidence",
				rationale: "the plan must change to stay safe",
				idempotencyKey: "legacy-key",
				invariant: {
					accepted: true,
					structuralInvariantAccepted: true,
					evidenceBackedNecessity: true,
					noEasierCompletion: true,
					rejectedReasons: [],
				},
				before: seed,
				after: seed,
			},
		});
		await appendFile(ulwLoopLedgerPath(repoRoot), `${legacyLine}\n`, "utf8");

		// when
		const result = await steerUlwLoop(repoRoot, steering({ idempotencyKey: "legacy-key" }));

		// then
		expect(result.deduped).toBe(true);
		expect(result.accepted).toBe(true);
		expect("before" in result.audit).toBe(false);
		expect("after" in result.audit).toBe(false);
		expect(result.audit).toMatchObject({
			kind: "revise_pending_wording",
			idempotencyKey: "legacy-key",
			deduped: true,
		});
		expect((await readUlwLoopPlan(repoRoot)).goals).toEqual(seed.goals);
	});
});

describe("parseUlwLoopSteeringDirective", () => {
	it.each(["OMO_ULW_LOOP_STEER", "omo.ulw-loop.steer", "omo ulw-loop steer", "omo-agent-toolkit ulw-loop steer"])("parses %s pattern", (marker) => {
		expect(parseUlwLoopSteeringDirective(`${marker}: ${JSON.stringify(steering())}`)).toMatchObject({
			kind: "add_subgoal",
		});
	});

	it("returns null when no marker", () => {
		expect(parseUlwLoopSteeringDirective(JSON.stringify(steering()))).toBeNull();
	});

	it("returns null when JSON malformed after marker", () => {
		expect(parseUlwLoopSteeringDirective("OMO_ULW_LOOP_STEER: {bad json")).toBeNull();
	});

	it("returns null for deprecated markers", () => {
		const marker = ["OM", "X_ULW_LOOP_STEER"].join("");
		expect(parseUlwLoopSteeringDirective(`${marker}: ${JSON.stringify(steering())}`)).toBeNull();
	});
});

import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { runStopResumeHook } from "../src/stop-resume-hook.ts";

let workDir: string;

beforeEach(async () => {
	workDir = await mkdtemp(join(tmpdir(), "ulw-stop-resume-"));
});

afterEach(async () => {
	await rm(workDir, { recursive: true, force: true });
});

function stopPayload(overrides: Record<string, unknown> = {}): Record<string, unknown> {
	return {
		hook_event_name: "Stop",
		session_id: "s1",
		turn_id: "t1",
		transcript_path: join(workDir, "transcript.jsonl"),
		cwd: workDir,
		model: "gpt-5.6-sol",
		permission_mode: "default",
		stop_hook_active: false,
		...overrides,
	};
}

function sessionDir(): string {
	return join(workDir, ".omo", "ulw-loop", "s1");
}

function writeGoals(goals: readonly Record<string, unknown>[], planOverrides: Record<string, unknown> = {}): void {
	mkdirSync(sessionDir(), { recursive: true });
	writeFileSync(
		join(sessionDir(), "goals.json"),
		JSON.stringify({
			version: 1,
			createdAt: "2026-07-11T00:00:00.000Z",
			updatedAt: "2026-07-11T00:00:00.000Z",
			briefPath: ".omo/ulw-loop/s1/brief.md",
			goalsPath: ".omo/ulw-loop/s1/goals.json",
			ledgerPath: ".omo/ulw-loop/s1/ledger.jsonl",
			codexGoalMode: "aggregate",
			goals,
			...planOverrides,
		}),
	);
	writeFileSync(join(sessionDir(), "ledger.jsonl"), "");
	writeFileSync(join(workDir, "transcript.jsonl"), "");
}

function writeBoulderPlan(remaining: boolean): string {
	mkdirSync(join(workDir, ".omo", "plans"), { recursive: true });
	writeFileSync(
		join(workDir, ".omo", "plans", "p.md"),
		remaining ? "## TODOs\n- [ ] pending task\n" : "## TODOs\n- [x] done task\n",
	);
	return ".omo/plans/p.md";
}

function pendingGoal(id = "g1", status = "pending"): Record<string, unknown> {
	return {
		id,
		title: `Goal ${id}`,
		objective: `Objective ${id}`,
		status,
		successCriteria: [],
		attempt: 1,
		createdAt: "2026-07-11T00:00:00.000Z",
		updatedAt: "2026-07-11T00:00:00.000Z",
	};
}

describe("runStopResumeHook", () => {
	it("#given a pending goal #when the turn stops #then blocks with a resume directive", () => {
		writeGoals([pendingGoal()]);

		const output = runStopResumeHook(stopPayload());

		const parsed = JSON.parse(output);
		expect(parsed.decision).toBe("block");
		expect(parsed.reason).toContain("omo-agent-toolkit ulw-loop status");
	});

	it("#given stop_hook_active #when the hook runs #then no-ops", () => {
		writeGoals([pendingGoal()]);

		expect(runStopResumeHook(stopPayload({ stop_hook_active: true }))).toBe("");
	});

	it("#given a malformed payload #when the hook runs #then no-ops", () => {
		writeGoals([pendingGoal()]);

		expect(runStopResumeHook({ hook_event_name: "Stop" })).toBe("");
	});

	it("#given an active boulder work with remaining plan tasks #when the hook runs #then defers to start-work-continuation", () => {
		writeGoals([pendingGoal()]);
		const plan = writeBoulderPlan(true);
		writeFileSync(
			join(workDir, ".omo", "boulder.json"),
			JSON.stringify({ works: { w1: { session_ids: ["codex:s1"], status: "active", active_plan: plan } } }),
		);

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given an active boulder work whose plan is exhausted #when the hook runs #then defers to the final gate continuation", () => {
		writeGoals([pendingGoal()]);
		const plan = writeBoulderPlan(false);
		writeFileSync(
			join(workDir, ".omo", "boulder.json"),
			JSON.stringify({ works: { w1: { session_ids: ["codex:s1"], status: "active", active_plan: plan } } }),
		);

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given a flat legacy boulder work with remaining plan tasks #when the hook runs #then still defers", () => {
		writeGoals([pendingGoal()]);
		const plan = writeBoulderPlan(true);
		writeFileSync(
			join(workDir, ".omo", "boulder.json"),
			JSON.stringify({ session_ids: ["codex:s1"], status: "active", active_plan: plan }),
		);

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given a context-pressure marker in the transcript #when the hook runs #then no-ops", () => {
		writeGoals([pendingGoal()]);
		writeFileSync(join(workDir, "transcript.jsonl"), "note: context compacted mid-run\n");

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given no ulw-loop state #when the hook runs #then no-ops", () => {
		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given all goals complete #when the hook runs #then no-ops", () => {
		writeGoals([pendingGoal("g1", "complete"), pendingGoal("g2", "complete")]);

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given blocked and failed goals only #when the hook runs #then no-ops", () => {
		writeGoals([pendingGoal("g1", "blocked"), pendingGoal("g2", "failed")]);

		expect(runStopResumeHook(stopPayload())).toBe("");
	});

	it("#given a static ledger #when the hook fires three times #then caps after two and marks stuck", () => {
		writeGoals([pendingGoal()]);

		const first = runStopResumeHook(stopPayload());
		const second = runStopResumeHook(stopPayload());
		const third = runStopResumeHook(stopPayload());

		expect(JSON.parse(first).decision).toBe("block");
		expect(JSON.parse(second).decision).toBe("block");
		expect(third).toBe("");
		const counter = JSON.parse(readFileSync(join(sessionDir(), "auto-resume-g1.json"), "utf8"));
		expect(counter.count).toBe(2);
		expect(existsSync(join(sessionDir(), "auto-resume-g1.stuck"))).toBe(true);
		expect(readFileSync(join(sessionDir(), "ledger.jsonl"), "utf8")).toBe("");
	});

	it("#given a session id needing normalization #when the hook blocks #then the directive carries the normalized flag", () => {
		writeGoals([pendingGoal()]);

		const output = runStopResumeHook(stopPayload({ session_id: "s1/" }));

		expect(JSON.parse(output).reason).toContain("--session-id s1");
	});

	it("#given a goal id with path traversal #when the hook runs #then nothing is written outside the state dir and the resume is denied", () => {
		writeGoals([pendingGoal("../../../escaped-marker")]);
		const outsideDir = join(workDir, ".omo", "ulw-loop");
		const sentinel = join(outsideDir, "escaped-marker.json");
		writeFileSync(sentinel, "sentinel\n");

		const output = runStopResumeHook(stopPayload());

		expect(output).toBe("");
		expect(readFileSync(sentinel, "utf8")).toBe("sentinel\n");
		expect(existsSync(join(outsideDir, "escaped-marker.stuck"))).toBe(false);
		expect(existsSync(join(outsideDir, "auto-resume-escaped-marker.json"))).toBe(false);
	});

	it("#given a normal goal id #when the hook runs past the cap #then the counter and stuck marker are written inside the state dir", () => {
		writeGoals([pendingGoal("goal-abc")]);

		runStopResumeHook(stopPayload());
		runStopResumeHook(stopPayload());
		const third = runStopResumeHook(stopPayload());

		expect(third).toBe("");
		const counter = JSON.parse(readFileSync(join(sessionDir(), "auto-resume-goal-abc.json"), "utf8"));
		expect(counter.count).toBe(2);
		expect(readFileSync(join(sessionDir(), "auto-resume-goal-abc.stuck"), "utf8")).toBe(
			"no ledger progress after 2 resumes\n",
		);
	});

	it("#given ledger movement between stops #when the hook fires again #then the cap resets", () => {
		writeGoals([pendingGoal()]);

		runStopResumeHook(stopPayload());
		runStopResumeHook(stopPayload());
		appendFileSync(join(sessionDir(), "ledger.jsonl"), '{"kind":"goal_started"}\n');
		const third = runStopResumeHook(stopPayload());

		expect(JSON.parse(third).decision).toBe("block");
		expect(existsSync(join(sessionDir(), "auto-resume-g1.stuck"))).toBe(false);
	});
});

