export async function readModelCatalog(env = process.env) {
	const catalogPath =
		env.LAZYCODEX_MODEL_CATALOG_PATH?.trim() || join(dirname(fileURLToPath(import.meta.url)), "..", "model-catalog.json");
	try {
		return parseCatalog(JSON.parse(await readFile(catalogPath, "utf8"))) ?? FALLBACK_CATALOG;
	} catch (error) {
		if (error instanceof Error) return FALLBACK_CATALOG;
		throw error;
	}
}

function parseCatalog(value) {
	if (!isRecord(value) || !isRecord(value.current) || !Array.isArray(value.managedProfiles)) return null;
	if (typeof value.version !== "string" || !isReasoningProfile(value.current)) return null;
	const managedProfiles = [];
	for (const profile of value.managedProfiles) {
		if (!isRecord(profile) || typeof profile.version !== "string" || !isRecord(profile.match)) return null;
		managedProfiles.push({ version: profile.version, match: profile.match });
	}
	return { version: value.version, current: value.current, managedProfiles, roles: isRecord(value.roles) ? value.roles : {} };
}

function isReasoningProfile(value) {
	return (
		isRecord(value) &&
		typeof value.model === "string" &&
		typeof value.model_context_window === "number" &&
		typeof value.model_reasoning_effort === "string" &&
		typeof value.plan_mode_reasoning_effort === "string"
	);
}

function isRecord(value) {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { lstat } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";

export async function configPaths({ env, cwd }) {
	const codexHome = resolve(env.CODEX_HOME?.trim() || join(homedir(), ".codex"));
	const paths = new Set([join(codexHome, "config.toml")]);
	for (const projectConfig of projectConfigPaths({ cwd, stopAt: homedir() })) {
		if (!(await isRegularFile(projectConfig))) continue;
		if (!(await isRegularDirectory(dirname(projectConfig)))) continue;
		paths.add(projectConfig);
	}
	return [...paths];
}

function projectConfigPaths({ cwd, stopAt }) {
	const paths = [];
	let current = resolve(cwd);
	const stop = resolve(stopAt);
	while (true) {
		paths.push(join(current, ".codex", "config.toml"));
		if (current === stop || current === dirname(current)) break;
		current = dirname(current);
	}
	return paths;
}

async function isRegularFile(path) {
	try {
		return (await lstat(path)).isFile();
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

async function isRegularDirectory(path) {
	try {
		return (await lstat(path)).isDirectory();
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

const CONTEXT7_HEADER = "[mcp_servers.context7]";

export function removeStaleContext7PlaceholderMcpServer(config) {
	return removeSections(config, (section) => section.header === CONTEXT7_HEADER && isContext7PlaceholderSection(section.text));
}

function isContext7PlaceholderSection(sectionText) {
	const args = readStringArraySetting(sectionText, "args");
	if (args === null || !args.includes("@upstash/context7-mcp")) return false;
	const apiKey = valueAfter(args, "--api-key");
	return apiKey !== null && isPlaceholderApiKey(apiKey);
}

function valueAfter(values, key) {
	const index = values.indexOf(key);
	return index >= 0 ? values[index + 1] ?? null : null;
}

function isPlaceholderApiKey(value) {
	return /^your[-_ ]?api[-_ ]?key$/i.test(value);
}

function readStringArraySetting(sectionText, key) {
	for (const line of sectionText.split("\n")) {
		if (!new RegExp(`^\\s*${key}\\s*=`).test(line)) continue;
		const assignmentIndex = line.indexOf("=");
		if (assignmentIndex === -1) return null;
		return parseTomlStringArray(stripUnquotedInlineComment(line.slice(assignmentIndex + 1)).trim());
	}
	return null;
}

function parseTomlStringArray(value) {
	if (!value.startsWith("[") || !value.endsWith("]")) return null;
	const items = [];
	let index = 1;
	while (index < value.length - 1) {
		const char = value[index];
		if (char === "\"" || char === "'") {
			const parsed = parseTomlString(value, index);
			if (parsed === null) return null;
			items.push(parsed.value);
			index = parsed.nextIndex;
			continue;
		}
		index += 1;
	}
	return items;
}

function parseTomlString(input, startIndex) {
	const quote = input[startIndex];
	let value = "";
	let index = startIndex + 1;
	while (index < input.length) {
		const char = input[index];
		if (quote === "\"" && char === "\\") {
			const next = input[index + 1];
			if (next === undefined) return null;
			value += next;
			index += 2;
			continue;
		}
		if (char === quote) return { value, nextIndex: index + 1 };
		value += char;
		index += 1;
	}
	return null;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

function removeSections(config, shouldRemove) {
	return splitSections(config)
		.filter((section) => !shouldRemove(section))
		.map((section) => section.text)
		.join("")
		.replace(/\n{3,}/g, "\n\n");
}

function splitSections(config) {
	const lines = config.match(/[^\n]*\n?|$/g) ?? [];
	const sections = [];
	let current = { header: null, text: "" };
	for (const line of lines) {
		if (line.length === 0) break;
		const header = tableHeader(line);
		if (header !== null) {
			if (current.text.length > 0) sections.push(current);
			current = { header, text: line };
		} else {
			current = { ...current, text: current.text + line };
		}
	}
	if (current.text.length > 0) sections.push(current);
	return sections;
}

function tableHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	if (!trimmed.startsWith("[") || !trimmed.endsWith("]") || trimmed.startsWith("[[")) return null;
	return trimmed;
}

const MULTI_AGENT_MODE_KEY = "multi_agent_mode";

export function removeUnsupportedRootMultiAgentMode(config) {
	const lines = config.split(/\n/);
	const output = [];
	let inRoot = true;
	let changed = false;
	for (const line of lines) {
		const sectionHeader = isSectionHeader(line);
		if (inRoot && isRootSetting(line, MULTI_AGENT_MODE_KEY)) {
			changed = true;
			continue;
		}
		output.push(line);
		if (sectionHeader) inRoot = false;
	}
	return changed ? output.join("\n") : config;
}

function isSectionHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	return trimmed.startsWith("[") && trimmed.endsWith("]");
}

function isRootSetting(line, key) {
	const trimmed = line.trimStart();
	if (trimmed.startsWith("#") || trimmed.startsWith("[")) return false;
	const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=/);
	return match?.[1] === key;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

/**
 * Runtime migration for `[features.multi_agent_v2]`.
 *
 * Historical behavior (openai/codex#26753): force `enabled = false` on every
 * SessionStart because enabling V2 made every turn 400 with encrypted
 * spawn_agent parameters on models that were not configured for encrypted
 * tool use. OpenAI closed that as NOT_PLANNED (V2 under development).
 *
 * GPT-5.6 models that declare `multi_agent_version: "v2"` in the Codex model
 * catalog invert that failure mode: forcing `enabled = false` makes every
 * turn 400 with a reserved `collaboration.spawn_agent` schema mismatch
 * (lazycodex#118 / oh-my-openagent#6002 / openai/codex#31097), and
 * `hide_spawn_agent_metadata = false` (written by OMO installers <= 4.15.x)
 * mismatches the same reserved schema by re-adding agent_type/model
 * properties to spawn_agent. For those models this guard clears the managed
 * disable and the stale metadata override, leaving V2 unset so Codex can
 * follow model metadata.
 *
 * When the selected model is unknown or declares V1, keep the #26753
 * force-disable path.
 *
 * Opt out of the whole migration with LAZYCODEX_CONFIG_MIGRATION_DISABLED=1
 * (or OMO_CODEX_CONFIG_MIGRATION_DISABLED=1).
 */
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, isAbsolute, join } from "node:path";

import {
	findTomlSection as findSection,
	hasTomlSetting,
	removeTomlSectionSetting,
	removeRootTomlSetting,
	replaceOrInsertTomlSectionSetting,
	replaceOrInsertRootTomlSetting,
} from "./toml-section-editor.mjs";

const MANAGED_COMMENT_MARKER = "openai/codex#26753";
const MULTI_AGENT_V2_THREAD_LIMIT_KEY = "features.multi_agent_v2.max_concurrent_threads_per_session";
const MANAGED_DISABLE_COMMENT = [
	"# Managed by LazyCodex: multi_agent_v2 is re-disabled on every Codex session start",
	`# because enabling it fails every turn with HTTP 400 (${MANAGED_COMMENT_MARKER}).`,
	"# Opt out: LAZYCODEX_CONFIG_MIGRATION_DISABLED=1 (or OMO_CODEX_CONFIG_MIGRATION_DISABLED=1).",
	"",
].join("\n");

/**
 * @param {string} config
 * @param {{
 *   multiAgentVersion?: string | null,
 *   sessionModel?: string | null,
 *   requireSessionModel?: boolean,
 *   env?: NodeJS.ProcessEnv,
 *   modelsCachePath?: string,
 *   configPath?: string,
 * }} [options]
 */
export function forceDisableMultiAgentV2(config, options = {}) {
	// Always normalize the legacy `[features]` boolean shorthand first: leaving
	// `multi_agent_v2 = true|false` in place while a later guard appends the
	// `[features.multi_agent_v2]` table would define the same name as both a
	// scalar and a table, which Codex rejects as invalid TOML.
	const normalized = removeFeaturesShorthand(config);
	const sessionModel = normalizeModel(options.sessionModel);
	const multiAgentVersion =
		options.multiAgentVersion !== undefined
			? options.multiAgentVersion
			: resolveMultiAgentVersionFromConfig(normalized, options);
	const effectiveModel = sessionModel || readRootModel(normalized);

	if (prefersMultiAgentV2(multiAgentVersion, effectiveModel)) {
		return clearMultiAgentV2DisableForReservedSchema(normalized);
	}

	// SessionStart can run with an override model (`codex -m gpt-5.6-terra`) while
	// config.toml still lists a different default. If we cannot see the effective
	// session model, do not force-disable — writing enabled=false would break a
	// GPT-5.6 reserved collaboration.spawn_agent session.
	if (options.requireSessionModel === true && !sessionModel) {
		return normalized;
	}

	// No model evidence at all (no session model AND no root `model` in
	// config.toml — Codex Desktop selects the model in the UI): config alone
	// cannot prove the session is not a GPT-5.6 reserved-schema model, and
	// writing `enabled = false` would 400 every turn on those sessions
	// (#6002). Leave the enable state untouched.
	if (multiAgentVersion == null && !sessionModel && !readRootModel(normalized)) {
		return normalized;
	}

	// Unknown catalog entry for an explicit session model: skip force-disable
	// rather than assume the legacy encrypted-V2 failure mode.
	if (sessionModel && multiAgentVersion == null) {
		return normalized;
	}

	return forceDisableLegacyEncryptedV2(normalized);
}

/**
 * True when the effective model should run MultiAgentV2: the catalog says
 * "v2", or the catalog is unavailable but the model is a GPT-5.6 family
 * model (which reserves the collaboration.spawn_agent schema).
 * @param {"v1" | "v2" | null | undefined} multiAgentVersion
 * @param {string | null | undefined} sessionModel
 */
export function prefersMultiAgentV2(multiAgentVersion, sessionModel) {
	return multiAgentVersion === "v2" || (multiAgentVersion == null && isGpt56Family(normalizeModel(sessionModel)));
}

/**
 * Resolve the effective model against Codex `models_cache.json`.
 * Prefers SessionStart `model` over the root `model` in config.toml.
 * @param {string} config
 * @param {{ sessionModel?: string | null, env?: NodeJS.ProcessEnv, modelsCachePath?: string, configPath?: string }} [options]
 * @returns {"v1" | "v2" | null}
 */
export function resolveMultiAgentVersionFromConfig(config, options = {}) {
	const model = normalizeModel(options.sessionModel) || readRootModel(config);
	if (!model) return null;
	const version = resolveMultiAgentVersionForModel(model, {
		...options,
		modelsCachePath: options.modelsCachePath?.trim() || resolveModelCatalogPath(readRootModelCatalogPath(config), options) || undefined,
	});
	return version ?? (isGpt56Family(model) ? "v2" : null);
}

/**
 * @param {string} model
 * @param {{ env?: NodeJS.ProcessEnv, modelsCachePath?: string }} [options]
 * @returns {"v1" | "v2" | null}
 */
export function resolveMultiAgentVersionForModel(model, options = {}) {
	const cachePath =
		options.modelsCachePath?.trim() ||
		join(options.env?.CODEX_HOME?.trim() || join(homedir(), ".codex"), "models_cache.json");

	try {
		const cache = JSON.parse(readFileSync(cachePath, "utf8"));
		const models = Array.isArray(cache?.models) ? cache.models : [];
		const entry = models.find((item) => item?.slug === model || item?.id === model);
		const version = entry?.multi_agent_version;
		if (version === "v1" || version === "v2") return version;
		return null;
	} catch {
		return null;
	}
}

export function readRootModel(config) {
	const double = config.match(/^\s*model\s*=\s*"([^"]+)"/m);
	if (double) return double[1];
	const single = config.match(/^\s*model\s*=\s*'([^']+)'/m);
	return single?.[1] ?? null;
}

// Codex documents `model_catalog_json` as a COMPLETE replacement for the
// fetched models_cache.json (codex-rs/core/src/config/mod.rs load_model_catalog
// -> load_catalog_json -> ModelsResponse). When set, Codex resolves the model
// only from that file, so the guard must too — otherwise Codex and the guard
// disagree on the multi-agent version (lazycodex#120).
export function readRootModelCatalogPath(config) {
	const double = config.match(/^\s*model_catalog_json\s*=\s*"([^"]+)"/m);
	if (double) return double[1];
	const single = config.match(/^\s*model_catalog_json\s*=\s*'([^']+)'/m);
	return single?.[1] ?? null;
}

function resolveModelCatalogPath(configuredPath, options) {
	const trimmed = normalizeModel(configuredPath);
	if (!trimmed) return null;
	if (isAbsolute(trimmed)) return trimmed;
	const baseDir = options.configPath ? dirname(options.configPath) : options.env?.CODEX_HOME?.trim() || join(homedir(), ".codex");
	return join(baseDir, trimmed);
}

function normalizeModel(value) {
	if (typeof value !== "string") return null;
	const trimmed = value.trim();
	return trimmed.length > 0 ? trimmed : null;
}

function isGpt56Family(model) {
	return typeof model === "string" && /^gpt-5\.6\b/i.test(model);
}

function clearMultiAgentV2DisableForReservedSchema(config) {
	// `config` arrives shorthand-normalized from forceDisableMultiAgentV2.
	let result = removeManagedDisableComments(config);
	result = removeRootTomlSetting(result, "features.multi_agent_v2.enabled", "false");
	result = removeRootTomlSetting(result, "features.multi_agent_v2.hide_spawn_agent_metadata", "false");
	result = removeDottedMultiAgentV2Setting(result, "enabled", "false");
	result = removeDottedMultiAgentV2Setting(result, "hide_spawn_agent_metadata", "false");

	const section = findSection(result, "[features.multi_agent_v2]");
	if (!section) return result;

	// Two settings poison the reserved collaboration.spawn_agent schema on V2
	// models (verified against codex-cli 0.144.1 + gpt-5.6-sol):
	// - `enabled = false` forces the legacy V1 tool surface on some Codex
	//   versions (#6002's failure shape);
	// - `hide_spawn_agent_metadata = false` (written by OMO installers
	//   <= 4.15.x to expose agent_type) re-adds agent_type/model/... to
	//   spawn_agent, mismatching the reserved schema -> HTTP 400 every turn.
	// Remove both; `hide_spawn_agent_metadata = true` matches the Codex
	// default and is left alone.
	const cleared = section.text
		.replace(/^\s*enabled\s*=\s*false[ \t]*(?:#[^\n]*)?\n?/gm, "")
		.replace(/^\s*hide_spawn_agent_metadata\s*=\s*false[ \t]*(?:#[^\n]*)?\n?/gm, "");
	if (cleared === section.text) return result;
	return result.slice(0, section.start) + cleared + result.slice(section.end);
}

// `config` arrives shorthand-normalized from forceDisableMultiAgentV2.
function forceDisableLegacyEncryptedV2(config) {
	const section = findSection(config, "[features.multi_agent_v2]");

	if (!section) {
		if (hasTomlSetting(config, MULTI_AGENT_V2_THREAD_LIMIT_KEY)) {
			return setDottedMultiAgentV2Disable(config);
		}
		return ensureManagedComment(appendDisabledSection(config));
	}

	const enabledTruePattern = /^(\s*)enabled\s*=\s*true[ \t]*(#[^\n]*)?$/m;
	if (enabledTruePattern.test(section.text)) {
		const patched = section.text.replace(enabledTruePattern, (_match, indent, comment) =>
			comment ? `${indent}enabled = false ${comment}` : `${indent}enabled = false`,
		);
		return ensureManagedComment(config.slice(0, section.start) + patched + config.slice(section.end));
	}

	if (/^\s*enabled\s*=\s*false[ \t]*(?:#[^\n]*)?$/m.test(section.text)) return config;

	const headerEnd = section.text.indexOf("\n");
	const insertAt = headerEnd === -1 ? section.text.length : headerEnd + 1;
	const patched = `${section.text.slice(0, insertAt)}${headerEnd === -1 ? "\n" : ""}enabled = false\n${section.text.slice(insertAt)}`;
	return ensureManagedComment(config.slice(0, section.start) + patched + config.slice(section.end));
}

function setDottedMultiAgentV2Disable(config) {
	const featuresSection = findSection(config, "[features]");
	if (!featuresSection) {
		return replaceOrInsertRootTomlSetting(config, "features.multi_agent_v2.enabled", "false");
	}
	return replaceOrInsertTomlSectionSetting(config, featuresSection, "multi_agent_v2.enabled", "false");
}

function removeDottedMultiAgentV2Setting(config, key, expectedValue) {
	const featuresSection = findSection(config, "[features]");
	if (!featuresSection) return config;
	return removeTomlSectionSetting(config, featuresSection, `multi_agent_v2.${key}`, expectedValue);
}

function ensureManagedComment(config) {
	if (config.includes(MANAGED_COMMENT_MARKER)) return config;
	const section = findSection(config, "[features.multi_agent_v2]");
	if (!section) return config;
	return config.slice(0, section.start) + MANAGED_DISABLE_COMMENT + config.slice(section.start);
}

function removeManagedDisableComments(config) {
	if (!config.includes(MANAGED_COMMENT_MARKER) && !config.includes("Managed by LazyCodex: multi_agent_v2")) {
		return config;
	}

	const lines = config.split("\n");
	const kept = [];
	for (const line of lines) {
		const trimmed = line.trim();
		if (
			trimmed.startsWith("#") &&
			(trimmed.includes(MANAGED_COMMENT_MARKER) ||
				trimmed.includes("Managed by LazyCodex: multi_agent_v2") ||
				trimmed.includes("because enabling it fails every turn with HTTP 400") ||
				trimmed.includes("LAZYCODEX_CONFIG_MIGRATION_DISABLED=1") ||
				trimmed.includes("OMO_CODEX_CONFIG_MIGRATION_DISABLED=1"))
		) {
			continue;
		}
		kept.push(line);
	}
	return kept.join("\n").replace(/\n{3,}/g, "\n\n");
}

function removeFeaturesShorthand(config) {
	const section = findSection(config, "[features]");
	if (!section) return config;

	const shorthandPattern = /^\s*multi_agent_v2\s*=\s*(?:true|false)[ \t]*(?:#[^\n]*)?[ \t]*\n?/m;
	if (!shorthandPattern.test(section.text)) return config;

	const patched = section.text.replace(shorthandPattern, "");
	return config.slice(0, section.start) + patched + config.slice(section.end);
}

function appendDisabledSection(config) {
	const trimmed = config.trimEnd();
	const prefix = trimmed.length === 0 ? "" : `${trimmed}\n\n`;
	return `${prefix}[features.multi_agent_v2]\nenabled = false\n`;
}

export const MANAGED_KEYS = ["model", "model_context_window", "model_reasoning_effort", "plan_mode_reasoning_effort"];

export function ensureCodexReasoningConfig(config, profile) {
	let next = replaceOrInsertRootSetting(config, "model", JSON.stringify(profile.model));
	next = replaceOrInsertRootSetting(next, "model_context_window", profile.model_context_window.toString());
	next = replaceOrInsertRootSetting(next, "model_reasoning_effort", JSON.stringify(profile.model_reasoning_effort));
	next = replaceOrInsertRootSetting(next, "plan_mode_reasoning_effort", JSON.stringify(profile.plan_mode_reasoning_effort));
	return next;
}

export function readRootSettings(config) {
	const settings = {};
	for (const line of config.split(/\n/)) {
		if (isSectionHeader(line)) break;
		for (const key of MANAGED_KEYS) {
			if (!isRootSetting(line, key)) continue;
			const value = parseTomlScalar(line.slice(line.indexOf("=") + 1));
			if (value !== undefined) settings[key] = value;
		}
	}
	return settings;
}

function parseTomlScalar(value) {
	const trimmed = value.trim();
	if (trimmed.startsWith('"') && trimmed.endsWith('"')) {
		try {
			return JSON.parse(trimmed);
		} catch (error) {
			if (error instanceof SyntaxError) return undefined;
			throw error;
		}
	}
	const numeric = Number(trimmed);
	return Number.isFinite(numeric) ? numeric : undefined;
}

function replaceOrInsertRootSetting(config, key, value) {
	const lines = config.split(/\n/);
	const output = [];
	let replaced = false;
	let inserted = false;
	let inRoot = true;
	for (const line of lines) {
		const sectionHeader = isSectionHeader(line);
		if (inRoot && !inserted && sectionHeader) {
			if (!replaced) output.push(`${key} = ${value}`);
			inserted = true;
		}
		if (inRoot && isRootSetting(line, key)) {
			if (!replaced) {
				output.push(`${key} = ${value}`);
				replaced = true;
			}
			continue;
		}
		output.push(line);
		if (sectionHeader) inRoot = false;
	}
	if (!replaced && !inserted) output.push(`${key} = ${value}`);
	return output.join("\n");
}

function isSectionHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	return trimmed.startsWith("[") && trimmed.endsWith("]");
}

function isRootSetting(line, key) {
	const trimmed = line.trimStart();
	if (trimmed.startsWith("#") || trimmed.startsWith("[")) return false;
	const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=/);
	return match?.[1] === key;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

export function resolveStatePath(env) {
	const explicitStatePath = env.LAZYCODEX_MODEL_CATALOG_STATE_PATH?.trim();
	if (explicitStatePath) return explicitStatePath;
	const dataRoot = env.PLUGIN_DATA?.trim() || join(homedir(), ".local", "share", "lazycodex");
	return join(dataRoot, "model-catalog-state.json");
}

export async function readState(statePath) {
	try {
		const parsed = JSON.parse(await readFile(statePath, "utf8"));
		return isRecord(parsed) ? parsed : {};
	} catch (error) {
		if (error instanceof Error) return {};
		throw error;
	}
}

export async function writeState(statePath, state) {
	await mkdir(dirname(statePath), { recursive: true });
	await writeFile(statePath, `${JSON.stringify(state, null, 2)}\n`);
}

function isRecord(value) {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { prefersMultiAgentV2, readRootModel, resolveMultiAgentVersionFromConfig } from "./multi-agent-v2-guard.mjs";
import {
	findTomlSection as findSection,
	hasTomlSetting,
	replaceOrInsertTomlSectionSetting,
} from "./toml-section-editor.mjs";

const CODEX_AGENTS_HEADER = "[agents]";
const CODEX_MULTI_AGENT_V2_HEADER = "[features.multi_agent_v2]";
const CODEX_MULTI_AGENT_V2_THREAD_LIMIT_KEY = "features.multi_agent_v2.max_concurrent_threads_per_session";
const CODEX_SUBAGENT_THREAD_LIMIT = "1000";
const CODEX_MULTI_AGENT_V2_DEFAULT_THREAD_LIMIT = "16";

/**
 * Ensure subagent concurrency limits without writing settings that conflict
 * with MultiAgentV2. When the selected model prefers V2 (catalog `v2`, or a
 * GPT-5.6 family session model with the catalog unavailable) or V2 is already
 * enabled in config, skip `agents.max_threads` because Codex rejects that key
 * while features.multi_agent_v2 is enabled.
 *
 * When no model is resolvable at all (no session model and no root `model`
 * in config.toml — Codex Desktop selects the model in the UI), never
 * introduce `agents.max_threads`: it hard-fails thread/start on
 * MultiAgentV2 sessions. An existing cap is still raised in place so the
 * legacy low-cap repair keeps working and a hand-removed key stays removed.
 *
 * @param {string} config
 * @param {{ multiAgentVersion?: string | null, sessionModel?: string | null, env?: NodeJS.ProcessEnv, modelsCachePath?: string }} [options]
 */
export function ensureSubagentConcurrencyLimit(config, options = {}) {
	const multiAgentVersion =
		options.multiAgentVersion !== undefined
			? options.multiAgentVersion
			: resolveMultiAgentVersionFromConfig(config, options);
	const v2Preferred = prefersMultiAgentV2(multiAgentVersion, options.sessionModel) || isMultiAgentV2Enabled(config);

	let result = config;
	if (v2Preferred) {
		result = removeAgentsMaxThreads(result);
	} else if (multiAgentVersion == null && !hasModelEvidence(config, options)) {
		result = raiseExistingAgentsMaxThreads(result);
	} else {
		result = ensureAgentsMaxThreads(result);
	}
	return ensureMultiAgentV2ThreadLimit(result);
}

function hasModelEvidence(config, options) {
	const sessionModel = typeof options.sessionModel === "string" ? options.sessionModel.trim() : "";
	return sessionModel.length > 0 || readRootModel(config) !== null;
}

function isMultiAgentV2Enabled(config) {
	const section = findSection(config, CODEX_MULTI_AGENT_V2_HEADER);
	if (!section) return false;
	return /^\s*enabled\s*=\s*true[ \t]*(?:#[^\n]*)?$/m.test(section.text);
}

function raiseExistingAgentsMaxThreads(config) {
	const section = findSection(config, CODEX_AGENTS_HEADER);
	if (!section) return config;
	if (!/^\s*max_threads\s*=/m.test(section.text)) return config;
	return replaceOrInsertTomlSectionSetting(config, section, "max_threads", CODEX_SUBAGENT_THREAD_LIMIT);
}

function ensureAgentsMaxThreads(config) {
	const section = findSection(config, CODEX_AGENTS_HEADER);
	if (!section) return appendBlock(config, `${CODEX_AGENTS_HEADER}\nmax_threads = ${CODEX_SUBAGENT_THREAD_LIMIT}\n`);
	return replaceOrInsertTomlSectionSetting(config, section, "max_threads", CODEX_SUBAGENT_THREAD_LIMIT);
}

function removeAgentsMaxThreads(config) {
	const section = findSection(config, CODEX_AGENTS_HEADER);
	if (!section) return config;
	if (!/^\s*max_threads\s*=/m.test(section.text)) return config;

	const patched = section.text.replace(/^\s*max_threads\s*=\s*[^\n]*\n?/m, "");
	const bodyLines = patched
		.split("\n")
		.slice(1)
		.filter((line) => line.trim() !== "");
	if (bodyLines.length === 0) {
		return config.slice(0, section.start) + config.slice(section.end).replace(/^\n+/, "");
	}
	return config.slice(0, section.start) + patched + config.slice(section.end);
}

function ensureMultiAgentV2ThreadLimit(config) {
	if (hasTomlSetting(config, CODEX_MULTI_AGENT_V2_THREAD_LIMIT_KEY)) return config;
	const section = findSection(config, CODEX_MULTI_AGENT_V2_HEADER);
	if (!section) {
		return appendBlock(
			config,
			`${CODEX_MULTI_AGENT_V2_HEADER}\nmax_concurrent_threads_per_session = ${CODEX_MULTI_AGENT_V2_DEFAULT_THREAD_LIMIT}\n`,
		);
	}
	return replaceOrInsertTomlSectionSetting(
		config,
		section,
		"max_concurrent_threads_per_session",
		CODEX_MULTI_AGENT_V2_DEFAULT_THREAD_LIMIT,
	);
}

function appendBlock(config, block) {
	const trimmed = config.trimEnd();
	const prefix = trimmed.length === 0 ? "" : `${trimmed}\n\n`;
	return `${prefix}${block}`;
}

function escapeRegExp(value) {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function findTomlSection(config, headerLine) {
	const targetHeaderPath = parseTomlTableHeader(headerLine);
	const lines = config.match(/[^\n]*\n?|$/g) ?? [];
	let offset = 0;
	let start = -1;
	let multilineQuote = null;
	for (const line of lines) {
		if (line.length === 0) break;
		const multilineScan = scanTomlMultilineLine(line, multilineQuote);
		multilineQuote = multilineScan.nextQuote;
		if (multilineScan.wasInside) {
			offset += line.length;
			continue;
		}
		if (start === -1) {
			if (tomlTableHeaderMatches(line, targetHeaderPath)) start = offset;
		} else if (isTomlTableHeaderLine(line)) {
			return { start, end: offset, text: config.slice(start, offset) };
		}
		offset += line.length;
	}
	if (start === -1) return null;
	return { start, end: config.length, text: config.slice(start) };
}

export function hasTomlSetting(config, keyPath) {
	const targetPath = parseTomlDottedKey(keyPath);
	if (!targetPath) return false;

	let tablePath = [];
	let multilineQuote = null;
	for (const line of config.split("\n")) {
		const multilineScan = scanTomlMultilineLine(line, multilineQuote);
		multilineQuote = multilineScan.nextQuote;
		if (multilineScan.wasInside) continue;
		const normalizedLine = stripUnquotedInlineComment(line).trim();
		if (normalizedLine.length === 0) continue;

		const headerPath = parseTomlTableHeader(normalizedLine);
		if (headerPath) {
			tablePath = headerPath;
			continue;
		}
		if (isTomlTableHeaderLine(normalizedLine)) {
			tablePath = null;
			continue;
		}
		if (!tablePath) continue;

		const assignmentIndex = findUnquotedAssignment(normalizedLine);
		if (assignmentIndex < 0) continue;
		const settingPath = parseTomlDottedKey(normalizedLine.slice(0, assignmentIndex).trim());
		if (!settingPath) continue;
		const fullPath = [...tablePath, ...settingPath];
		if (fullPath.length !== targetPath.length) continue;
		if (fullPath.every((part, index) => part === targetPath[index])) return true;
	}
	return false;
}

export function replaceOrInsertRootTomlSetting(config, keyPath, value) {
	const targetPath = parseTomlDottedKey(keyPath);
	if (!targetPath) return config;
	const match = findRootTomlSetting(config, targetPath);
	if (match) {
		const commentIndex = findUnquotedComment(match.lineBody, match.assignmentIndex + 1);
		const comment = commentIndex === -1 ? "" : ` ${match.lineBody.slice(commentIndex).trimStart()}`;
		const replacement = `${match.lineBody.slice(0, match.assignmentIndex + 1)} ${value}${comment}${match.newline}`;
		return config.slice(0, match.offset) + replacement + config.slice(match.offset + match.line.length);
	}
	const firstTable = findFirstTomlTableStart(config);
	const root = config.slice(0, firstTable).trimEnd();
	const suffix = config.slice(firstTable);
	const replacement = `${root}${root.length > 0 ? "\n" : ""}${keyPath} = ${value}\n`;
	if (suffix.length === 0) return replacement;
	return `${replacement.trimEnd()}\n\n${suffix.trimStart()}`;
}

export function replaceOrInsertTomlSectionSetting(config, section, keyPath, value) {
	const targetPath = parseTomlDottedKey(keyPath);
	if (!targetPath) return config;
	const lines = section.text.match(/[^\n]*\n?|$/g) ?? [];
	let offset = 0;
	let multilineQuote = null;
	for (const line of lines) {
		if (line.length === 0) break;
		const multilineScan = scanTomlMultilineLine(line, multilineQuote);
		multilineQuote = multilineScan.nextQuote;
		if (multilineScan.wasInside) {
			offset += line.length;
			continue;
		}
		const assignmentIndex = findUnquotedAssignment(line);
		if (assignmentIndex >= 0) {
			const settingPath = parseTomlDottedKey(line.slice(0, assignmentIndex).trim());
