		]);
		assert.equal(contract["pending-action"], "review .omo/plans/<slug>.md");

		for (const [laneName, lane] of Object.entries(contract.review)) {
			assert.deepEqual(lane, {
				status: "pending",
				workspace_root: surface.reviewRoots[laneName],
