	const projectDirectory = join(projectRoot, "not-a-directory");
	const codexPackageRoot = join(repoRoot, "packages", "omo-codex");
	const pluginRoot = join(codexPackageRoot, "plugin");
	const logs = [];

	await writeJson(join(codexPackageRoot, "marketplace.json"), {
		name: "debug-marketplace",
		plugins: [{ name: "alpha", source: "./plugin" }],
	});
	await writePluginAt(pluginRoot, "alpha", "1.2.3");
	await writeFile(projectDirectory, "file, not directory\n");

	const result = await installMarketplaceLocally({
		repoRoot,
		codexHome,
		binDir,
		projectDirectory,
		platform: "linux",
		runCommand: async (command, args, options) => {
			if (command === "npm" && args.join(" ") === "run build") {
				await mkdir(join(options.cwd, "dist"), { recursive: true });
				await writeFile(join(options.cwd, "dist", "cli.js"), "#!/usr/bin/env node\n");
			}
		},
		log: (message) => logs.push(message),
	});

	assert.equal(result.projectCleanup.projectRoot, null);
	assert.equal(result.projectCleanup.changed, false);
	assert.equal(logs.some((message) => message.includes("Skipped project-local Codex cleanup")), true);
	assert.equal(logs.some((message) => message.includes("not a directory")), true);
	assert.equal(await pathExists(join(codexHome, "config.toml")), true);
});

async function pathExists(path) {
	try {
		await lstat(path);
		return true;
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

export async function makeTempDir() {
	return mkdtemp(join(tmpdir(), "omo-codex-install-"));
}

export async function writeJson(path, value) {
	await mkdir(dirname(path), { recursive: true });
	await writeFile(path, `${JSON.stringify(value, null, 2)}\n`);
}

export async function writePlugin(root, name, version) {
	const pluginRoot = join(root, "plugins", name);
	await writePluginAt(pluginRoot, name, version);
}

export async function writePluginAt(pluginRoot, name, version) {
	await mkdir(join(pluginRoot, ".codex-plugin"), { recursive: true });
	await mkdir(join(pluginRoot, "dist"), { recursive: true });
	await mkdir(join(pluginRoot, "hooks"), { recursive: true });
	await mkdir(join(pluginRoot, "skills", name), { recursive: true });
	await mkdir(join(pluginRoot, "components", "ultrawork", "agents"), { recursive: true });
	await writeJson(join(pluginRoot, ".codex-plugin", "plugin.json"), {
		name,
		version,
		description: `${name} test plugin`,
		mcpServers: "./.mcp.json",
		hooks: "./hooks/hooks.json",
		skills: "./skills/",
	});
	await writeJson(join(pluginRoot, ".mcp.json"), {
		mcpServers: {
			[name]: {
				command: "node",
				args: ["./dist/cli.js", "mcp"],
				cwd: ".",
			},
		},
	});
	await writeJson(join(pluginRoot, "hooks", "hooks.json"), { hooks: {} });
	await writeFile(join(pluginRoot, "skills", name, "SKILL.md"), "---\nname: test\n---\n");
	await writeFile(join(pluginRoot, "components", "ultrawork", "agents", "explorer.toml"), 'name = "explorer"\n');
	await writeFile(join(pluginRoot, "components", "ultrawork", "agents", "librarian.toml"), 'name = "librarian"\n');
	await writeFile(join(pluginRoot, "components", "ultrawork", "agents", "plan.toml"), 'name = "plan"\n');
	await writeJson(join(pluginRoot, "package.json"), {
		name: `@example/${name}`,
		version,
		bin: {
			[name]: "./dist/cli.js",
		},
		scripts: {
			build: "node -e \"require('fs').writeFileSync('dist/cli.js', 'console.log(1)')\"",
		},
		dependencies: {},
	});
}

