    expect(rewritten.mcpServers.context7.args).toEqual([
      "--bun",
      "-y",
      "@upstash/context7-mcp",
      "--api-key",
      "ctx7sk_real_user_key",
    ])
    expect(rewritten.mcpServers.context7.env).toEqual({ CONTEXT7_API_KEY: "ctx7sk_real_env_key" })
