async function collectDeclaredBinNames(root: string): Promise<readonly string[]> {
  const names = new Set<string>()
  await walk(root, names)
  return [...names].sort()
}

async function walk(directory: string, names: Set<string>): Promise<void> {
  const entries = await readdir(directory, { withFileTypes: true }).catch(() => null)
  if (entries === null) return

  if (entries.some((entry) => entry.isFile() && entry.name === "package.json")) {
    for (const name of await readBinNames(join(directory, "package.json"))) names.add(name)
  }

  for (const entry of entries) {
    if (!entry.isDirectory()) continue
    if (entry.name === "node_modules" || entry.name === ".git" || entry.name === "dist") continue
    await walk(join(directory, entry.name), names)
  }
}

async function readBinNames(packageJsonPath: string): Promise<readonly string[]> {
  const parsed: unknown = JSON.parse(await readFile(packageJsonPath, "utf8"))
  if (typeof parsed !== "object" || parsed === null) return []
  const record = parsed as { readonly name?: unknown; readonly bin?: unknown }
  if (typeof record.bin === "string") return typeof record.name === "string" ? [basenameOf(record.name)] : []
  if (typeof record.bin !== "object" || record.bin === null) return []
  return Object.keys(record.bin as Record<string, unknown>)
}

function basenameOf(packageName: string): string {
  const segments = packageName.split("/")
  return segments[segments.length - 1] ?? packageName
}

import { lstat, readFile, readdir, readlink, rm } from "node:fs/promises"
import { dirname, isAbsolute, join, resolve } from "node:path"
import { COMMAND_SHIM_MARKER } from "./codex-cache-command-shim"
import { isManagedComponentBinTarget } from "./codex-cache-dangling-bins"
import { isNodeErrorWithCode } from "./codex-cache-fs"
import { isLegacyCodexBinTarget, LEGACY_CODEX_COMPONENT_BIN_NAMES } from "./codex-cache-legacy-bins"
import { RUNTIME_WRAPPER_MARKER } from "./codex-cache-runtime-wrapper"

type LinkPlatform = NodeJS.Platform

const ROOT_RUNTIME_BIN_NAME = "omo"

// Every bin name the installer creates: the root runtime wrapper plus each component's
// package.json `bin` key. A marker alone is not proof of ownership - a user who copies or
// renames a generated wrapper keeps the marker - so removal also requires the name to be one
// the installer itself would have written. `codex-cleanup-bins-coverage.test.ts` fails if a
// component adds a bin that is missing here, so this list cannot silently drift.
export const MANAGED_CODEX_BIN_NAMES: ReadonlySet<string> = new Set([
  ROOT_RUNTIME_BIN_NAME,
  "omo-codegraph",
  "omo-comment-checker",
  "omo-git-bash-hook",
  "omo-lsp",
  "omo-rules",
  "omo-start-work-continuation",
  "omo-telemetry",
  "omo-ultrawork",
  "omo-ulw-loop",
  "lazycodex-executor-verify",
  "ulw",
  "ulw-loop",
  ...LEGACY_CODEX_COMPONENT_BIN_NAMES,
])

// Removes the bin links the Codex installer created in binDir - the root `omo` runtime
// wrapper plus the component shims/symlinks - so uninstall no longer leaves the `omo`
// command behind (issue #6320). A candidate is removed only when BOTH its name is an
// installer bin name AND it carries the installer's own marker (or, on POSIX, resolves to a
// managed component target), so a user's own `omo`, a renamed copy of a generated wrapper,
// and an unrelated symlink all survive. Unlike the install-time dangling sweep this removes
// managed bins whether or not their cache target still exists, because uninstall also
// removes that cache.
export async function removeManagedCodexBins(binDir: string, platform: LinkPlatform): Promise<readonly string[]> {
  const entries = await readdir(binDir, { withFileTypes: true }).catch((error: unknown) => {
    if (isNodeErrorWithCode(error) && error.code === "ENOENT") return null
    throw error
  })
  if (entries === null) return []

  const removed: string[] = []
  for (const entry of entries) {
    const binName = managedBinNameForEntry(entry.name, platform)
    if (binName === null || !MANAGED_CODEX_BIN_NAMES.has(binName)) continue
    const linkPath = join(binDir, entry.name)
    if (await isManagedCodexBin(linkPath, platform, binName)) {
      await rm(linkPath, { force: true })
      removed.push(linkPath)
    }
  }
  return removed
}

// Windows shims and wrappers are always written as `<name>.cmd`; anything else in the bin
// directory (including a `.backup` copy) is not something the installer created. Windows
// resolves names case-insensitively while preserving the casing an entry was created with, so
// the installer's lowercase `omo.cmd` path can write through to an entry that stays on disk as
// `OMO.CMD`; the name is lowercased here so such a wrapper is still recognized as managed.
// POSIX names stay untouched because there `OMO` really is a different file. Ownership is not
// widened by this: removal still requires the installer's marker.
function managedBinNameForEntry(entryName: string, platform: LinkPlatform): string | null {
  if (platform !== "win32") return entryName
  const normalizedEntryName = entryName.toLowerCase()
  return normalizedEntryName.endsWith(".cmd") ? normalizedEntryName.slice(0, -".cmd".length) : null
}

async function isManagedCodexBin(linkPath: string, platform: LinkPlatform, binName: string): Promise<boolean> {
  const entryStat = await lstat(linkPath).catch((error: unknown) => {
    if (isNodeErrorWithCode(error) && error.code === "ENOENT") return null
    throw error
  })
  if (entryStat === null) return false

  if (entryStat.isSymbolicLink()) {
    if (platform === "win32") return false
    const linkTarget = await readlink(linkPath)
    const target = isAbsolute(linkTarget) ? linkTarget : resolve(dirname(linkPath), linkTarget)
    // The current layout is checked strictly; legacy names additionally accept the older
    // arbitrary-marketplace shape, so a legacy install does not leave commands on PATH.
    return isManagedComponentBinTarget(target) || isLegacyCodexBinTarget(binName, target)
  }

  if (!entryStat.isFile()) return false
  const content = await readFile(linkPath, "utf8")
  return content.includes(RUNTIME_WRAPPER_MARKER) || content.includes(COMMAND_SHIM_MARKER)
}

import { lstat, mkdir, readFile, writeFile } from "node:fs/promises"
import { dirname } from "node:path"
import { parseAgentHeaderName, parseHookStateHeaderKey, parsePluginHeaderKey } from "./codex-config-toml-sections"

const MANAGED_MARKETPLACES = ["sisyphuslabs", "lazycodex", "code-yeongyu-codex-plugins"] as const

const LEGACY_MANAGED_CODEX_AGENT_NAMES_TO_PURGE = ["codex-ultrawork-reviewer"] as const

const CURRENT_MANAGED_CODEX_AGENT_NAMES = [
  "explorer",
  "lazycodex-worker-high",
  "lazycodex-worker-low",
  "lazycodex-worker-medium",
  "librarian",
  "metis",
  "momus",
  "plan",
] as const

export const MANAGED_CODEX_AGENT_NAMES = [
  ...LEGACY_MANAGED_CODEX_AGENT_NAMES_TO_PURGE,
  ...CURRENT_MANAGED_CODEX_AGENT_NAMES,
] as const

export function cleanupCodexLightConfigText(config: string): string {
  let nextConfig = config
  for (const marketplace of MANAGED_MARKETPLACES) {
    nextConfig = removeTomlSections(nextConfig, (header) => header === `marketplaces.${marketplace}`)
    nextConfig = removeTomlSections(nextConfig, (header) => isManagedPluginHeader(header, marketplace))
    nextConfig = removeTomlSections(nextConfig, (header) => isManagedHookStateHeader(header, marketplace))
  }
  nextConfig = removeManagedAgentBlocks(nextConfig)
  return nextConfig.replace(/\n{3,}/g, "\n\n")
}

export async function cleanupCodexConfig(configPath: string, now: (() => Date) | undefined): Promise<{
  readonly changed: boolean
  readonly backupPath?: string
}> {
  if (!(await configExists(configPath))) return { changed: false }

  const original = await readFile(configPath, "utf8")
  const next = cleanupCodexLightConfigText(original)
  if (next === original) return { changed: false }

  const backupPath = `${configPath}.backup-${formatBackupTimestamp(now?.() ?? new Date())}`
  await mkdir(dirname(configPath), { recursive: true })
  await writeFile(backupPath, original)
  await writeFile(configPath, `${next.trimEnd()}\n`)
  return { changed: true, backupPath }
}

function removeManagedAgentBlocks(config: string): string {
  const managedAgentNames = new Set<string>(MANAGED_CODEX_AGENT_NAMES)
  return splitTomlSections(config)
    .filter((section) => {
      if (section.header === null) return true
      const agentName = parseAgentHeaderName(section.header)
      if (agentName === null || !managedAgentNames.has(agentName)) return true
      return !section.text.includes(`config_file = ${JSON.stringify(`./agents/${agentName}.toml`)}`)
    })
    .map((section) => section.text)
    .join("")
}

function isManagedPluginHeader(header: string, marketplace: string): boolean {
  const pluginKey = parsePluginHeaderKey(header)
  return pluginKey !== null && pluginKey.endsWith(`@${marketplace}`)
}

function isManagedHookStateHeader(header: string, marketplace: string): boolean {
  const hookKey = parseHookStateHeaderKey(header)
  if (hookKey === null) return false
  const separator = hookKey.indexOf(":")
  if (separator === -1) return false
  return hookKey.slice(0, separator).endsWith(`@${marketplace}`)
}

function removeTomlSections(config: string, shouldRemove: (header: string) => boolean): string {
  return splitTomlSections(config)
    .filter((section) => section.header === null || !shouldRemove(section.header))
    .map((section) => section.text)
    .join("")
}

function splitTomlSections(config: string): Array<{ header: string | null; text: string }> {
  const lines = config.match(/[^\n]*\n?|$/g) ?? []
  const sections: Array<{ header: string | null; text: string }> = []
  let current: { header: string | null; text: string } = { header: null, text: "" }
  for (const line of lines) {
    if (line.length === 0) break
    const header = parseTomlHeader(line)
    if (header !== null) {
      if (current.text.length > 0) sections.push(current)
      current = { header, text: line }
    } else {
      current.text += line
    }
  }
  if (current.text.length > 0) sections.push(current)
  return sections
}

function parseTomlHeader(line: string): string | null {
  const trimmed = line.trim()
  if (!trimmed.startsWith("[") || !trimmed.endsWith("]") || trimmed.startsWith("[[")) return null
  return trimmed.slice(1, -1)
}

function formatBackupTimestamp(date: Date): string {
  return date.toISOString().replace(/[:.]/g, "-")
}

async function configExists(path: string): Promise<boolean> {
  try {
    await lstat(path)
    return true
  } catch (error) {
    if (nodeErrorCode(error) === "ENOENT") return false
    throw error
  }
}

function nodeErrorCode(error: unknown): string | null {
  if (!(error instanceof Error) || !("code" in error)) return null
  return typeof error.code === "string" ? error.code : null
}

