import { parseJsonString } from "./codex-config-toml-sections"
import { resolveManagedAgentReasoning, type PreservedAgentReasoning } from "./managed-agent-reasoning-defaults"

export async function capturePreservedAgentReasoning(input: {
  readonly codexHome: string
}): Promise<ReadonlyMap<string, PreservedAgentReasoning>> {
  const agentsDir = join(input.codexHome, "agents")
  if (!(await exists(agentsDir))) return new Map()

  const preserved = new Map<string, PreservedAgentReasoning>()
  const agentEntries = await readdir(agentsDir, { withFileTypes: true })
  for (const entry of agentEntries) {
    if (!entry.name.endsWith(".toml")) continue
    const content = await readTextIfExists(join(agentsDir, entry.name))
    if (content === null) continue
    const effort = extractReasoningEffort(content)
    if (effort !== null) {
      preserved.set(agentNameFromToml(entry.name), {
        model: extractModel(content),
        effort,
      })
    }
  }
  return preserved
}

export async function capturePreservedAgentServiceTier(input: {
  readonly codexHome: string
}): Promise<ReadonlyMap<string, string | null>> {
  const agentsDir = join(input.codexHome, "agents")
  if (!(await exists(agentsDir))) return new Map()

  const preserved = new Map<string, string | null>()
  const agentEntries = await readdir(agentsDir, { withFileTypes: true })
  for (const entry of agentEntries) {
    if (!entry.name.endsWith(".toml")) continue
    const content = await readTextIfExists(join(agentsDir, entry.name))
    if (content === null) continue
    preserved.set(agentNameFromToml(entry.name), extractServiceTier(content))
  }
  return preserved
}

export async function restorePreservedReasoning(input: {
  readonly agentName: string
  readonly linkPath: string
  readonly target: string
  readonly value: PreservedAgentReasoning | undefined
}): Promise<void> {
  if (input.value === undefined) return
  const content = await readFile(input.target, "utf8")
  const bundledEffort = extractReasoningEffort(content)
  const effort = resolveManagedAgentReasoning({
    agentName: input.agentName,
    bundledModel: extractModel(content),
    bundledEffort,
    preserved: input.value,
  })
  if (bundledEffort === effort) return
  const replacement = replaceTopLevelStringSetting(content, "model_reasoning_effort", effort, { insertIfMissing: false })
  if (!replacement.replaced) return
  await writeFile(input.linkPath, replacement.content)
}

export async function restorePreservedServiceTier(input: {
  readonly linkPath: string
  readonly preserved: boolean
  readonly value: string | null
}): Promise<void> {
  if (!input.preserved) return
  const content = await readFile(input.linkPath, "utf8")
  if (extractServiceTier(content) === input.value) return
  const replacement = replaceTopLevelStringSetting(content, "service_tier", input.value, { insertIfMissing: true })
  if (!replacement.replaced) return
  await writeFile(input.linkPath, replacement.content)
}

async function readTextIfExists(path: string): Promise<string | null> {
  try {
    return await readFile(path, "utf8")
  } catch (error) {
    if (nodeErrorCode(error) === "ENOENT") return null
    throw error
  }
}

function extractModel(content: string): string | null {
  return extractTopLevelStringSetting(content, "model")
}

function extractReasoningEffort(content: string): string | null {
  return extractTopLevelStringSetting(content, "model_reasoning_effort")
}

function extractServiceTier(content: string): string | null {
  return extractTopLevelStringSetting(content, "service_tier")
}

function extractTopLevelStringSetting(content: string, key: string): string | null {
  for (const line of content.split(/\n/)) {
    if (isSectionHeader(line)) return null
    const rawValue = topLevelStringSettingRawValue(line, key)
    if (rawValue === undefined) continue
    const parsed = parseJsonString(rawValue)
    if (parsed !== null) return parsed
  }
  return null
}

function replaceTopLevelStringSetting(
  content: string,
  key: string,
  value: string | null,
  options: { readonly insertIfMissing: boolean },
): { readonly content: string; readonly replaced: boolean } {
  const lines = content.split(/\n/)
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]
    if (line === undefined || isSectionHeader(line)) break
    if (topLevelStringSettingRawValue(line, key) === undefined) continue
    if (value === null) {
      lines.splice(index, 1)
      return { content: lines.join("\n"), replaced: true }
    }
    lines[index] = line.replace(/=\s*"(?:[^"\\]|\\.)*"/, `= ${JSON.stringify(value)}`)
    return { content: lines.join("\n"), replaced: true }
  }

  if (value === null || !options.insertIfMissing) return { content, replaced: false }
  lines.splice(topLevelInsertionIndex(lines), 0, `${key} = ${JSON.stringify(value)}`)
  return { content: lines.join("\n"), replaced: true }
}

function topLevelStringSettingRawValue(line: string, key: string): string | undefined {
  const match = line.match(/^\s*([A-Za-z0-9_]+)\s*=\s*("(?:[^"\\]|\\.)*")/)
  if (match === null) return undefined
  const settingKey = match[1]
  const rawValue = match[2]
  if (settingKey !== key || rawValue === undefined) return undefined
  return rawValue
}

function topLevelInsertionIndex(lines: readonly string[]): number {
  const sectionIndex = lines.findIndex((line) => isSectionHeader(line))
  const topLevelEnd = sectionIndex === -1 ? lines.length : sectionIndex
  let insertionIndex = topLevelEnd
  while (insertionIndex > 0 && lines[insertionIndex - 1] === "") {
    insertionIndex -= 1
  }
  return insertionIndex
}

function isSectionHeader(line: string): boolean {
  const trimmed = line.trim()
  return trimmed.startsWith("[") && trimmed.endsWith("]")
}

function agentNameFromToml(fileName: string): string {
  return fileName.endsWith(".toml") ? fileName.slice(0, -".toml".length) : fileName
}

async function exists(path: string): Promise<boolean> {
  try {
    await lstat(path)
    return true
  } catch (error) {
    if (nodeErrorCode(error) !== "ENOENT") throw error
    return false
  }
}

function nodeErrorCode(error: unknown): string | null {
  if (!(error instanceof Error) || !("code" in error)) return null
  return typeof error.code === "string" ? error.code : null
}

import { lstat, readFile, rm } from "node:fs/promises"
import { join } from "node:path"

const RETIRED_MANAGED_AGENT_FILES = [
  {
    fileName: "codex-ultrawork-reviewer.toml",
    requiredMarkers: [
      'name = "codex-ultrawork-reviewer"',
      'description = "Strict ultrawork verification reviewer.',
      'developer_instructions = """You are the ultrawork verification reviewer.',
    ],
  },
] as const

export async function purgeRetiredManagedAgentFiles(input: { readonly codexHome: string }): Promise<void> {
  const agentsDir = join(input.codexHome, "agents")
  if (!(await exists(agentsDir))) return

  for (const retiredAgent of RETIRED_MANAGED_AGENT_FILES) {
    const agentPath = join(agentsDir, retiredAgent.fileName)
    if (!(await exists(agentPath))) continue
    const agentStat = await lstat(agentPath)
    if (agentStat.isDirectory() && !agentStat.isSymbolicLink()) continue
    const content = await readTextIfExists(agentPath)
    if (content === null || !hasRequiredMarkers(content, retiredAgent.requiredMarkers)) continue
    await rm(agentPath, { force: true })
  }
}

function hasRequiredMarkers(content: string, markers: readonly string[]): boolean {
  return markers.every((marker) => content.includes(marker))
}

async function readTextIfExists(path: string): Promise<string | null> {
  try {
    return await readFile(path, "utf8")
  } catch (error) {
    if (nodeErrorCode(error) === "ENOENT") return null
    throw error
  }
}

async function exists(path: string): Promise<boolean> {
  try {
    await lstat(path)
    return true
  } catch (error) {
    if (nodeErrorCode(error) !== "ENOENT") throw error
    return false
  }
}

function nodeErrorCode(error: unknown): string | null {
  if (!(error instanceof Error) || !("code" in error)) return null
  return typeof error.code === "string" ? error.code : null
}

export interface TomlSection {
  readonly start: number
  readonly end: number
  readonly text: string
}

export type TomlMultilineQuote = '"""' | "'''"

export interface TomlMultilineLineScan {
  readonly wasInside: boolean
  readonly nextQuote: TomlMultilineQuote | null
}

export function findTomlSection(config: string, header: string): TomlSection | null {
  const headerLine = `[${header}]`
  const targetHeaderPath = parseTomlDottedKey(header)
  const lines = config.match(/[^\n]*\n?|$/g) ?? []
  let offset = 0
  let start = -1
  let multilineQuote: TomlMultilineQuote | null = null
  for (const line of lines) {
    if (line.length === 0) break
    const multilineScan = scanTomlMultilineLine(line, multilineQuote)
    multilineQuote = multilineScan.nextQuote
    if (multilineScan.wasInside) {
      offset += line.length
      continue
    }
    const trimmed = line.trim()
    if (start === -1) {
      if (tomlTableHeaderMatches(trimmed, headerLine, targetHeaderPath)) start = offset
    } else if (isTomlTableHeaderLine(line)) {
      return { start, end: offset, text: config.slice(start, offset) }
    }
    offset += line.length
  }
  if (start === -1) return null
  return { start, end: config.length, text: config.slice(start) }
}

export function replaceOrInsertSetting(config: string, section: TomlSection, key: string, value: string): string {
  const targetPath = parseTomlDottedKey(key)
  if (!targetPath) return config

  const lines = section.text.match(/[^\n]*\n?|$/g) ?? []
  let offset = 0
  let multilineQuote: TomlMultilineQuote | null = null
  for (const line of lines) {
    if (line.length === 0) break
    const multilineScan = scanTomlMultilineLine(line, multilineQuote)
    multilineQuote = multilineScan.nextQuote
    if (multilineScan.wasInside) {
      offset += line.length
      continue
    }
    const assignmentIndex = findUnquotedAssignment(line)
    if (assignmentIndex < 0) {
      offset += line.length
      continue
    }
    const settingPath = parseTomlDottedKey(line.slice(0, assignmentIndex).trim())
    if (!settingPath || !tomlPathMatches(settingPath, targetPath)) {
      offset += line.length
      continue
    }
    const replacement = replaceTomlAssignmentValue(line, assignmentIndex, value)
    const assignmentEnd = multilineScan.nextQuote
      ? findTomlMultilineValueEnd(section.text, offset + line.length, multilineScan.nextQuote)
      : offset + line.length
    const sectionReplacement = section.text.slice(0, offset) + replacement + section.text.slice(assignmentEnd)
    return config.slice(0, section.start) + sectionReplacement + config.slice(section.end)
  }

  const replacement = insertSetting(section.text, key, value)
  return config.slice(0, section.start) + replacement + config.slice(section.end)
}

export function removeSetting(config: string, section: TomlSection, key: string): string {
  const linePattern = new RegExp(`^[ \\t]*${escapeRegExp(key)}[ \\t]*=.*(?:\\n|$)`, "m")
  const replacement = section.text.replace(linePattern, "")
  return config.slice(0, section.start) + replacement + config.slice(section.end)
}

export function replaceOrInsertRootSetting(config: string, key: string, value: string): string {
  const sectionStart = findFirstTableStart(config)
  const root = config.slice(0, sectionStart)
  const suffix = config.slice(sectionStart)
  const linePattern = new RegExp(`^[ \\t]*${escapeRegExp(key)}[ \\t]*=.*$`, "m")
  const replacement = linePattern.test(root)
    ? root.replace(linePattern, `${key} = ${value}`)
    : `${root.trimEnd()}${root.trimEnd().length > 0 ? "\n" : ""}${key} = ${value}\n`
  if (suffix.length === 0) return replacement
  return `${replacement.trimEnd()}\n\n${suffix.trimStart()}`
}

export function replaceOrInsertRootDottedSetting(config: string, keyPath: string, value: string): string {
  const targetPath = parseTomlDottedKey(keyPath)
  if (!targetPath) return config

  const lines = config.match(/[^\n]*\n?|$/g) ?? []
  let offset = 0
  let multilineQuote: TomlMultilineQuote | null = null
  for (const line of lines) {
    if (line.length === 0) break
    const multilineScan = scanTomlMultilineLine(line, multilineQuote)
    multilineQuote = multilineScan.nextQuote
    if (multilineScan.wasInside) {
      offset += line.length
      continue
    }
    if (isTomlTableHeaderLine(line)) break

    const assignmentIndex = findUnquotedAssignment(line)
    if (assignmentIndex < 0) {
      offset += line.length
      continue
    }
    const settingPath = parseTomlDottedKey(line.slice(0, assignmentIndex).trim())
    if (!settingPath || !tomlPathMatches(settingPath, targetPath)) {
      offset += line.length
      continue
    }
    const replacement = replaceTomlAssignmentValue(line, assignmentIndex, value)
    const assignmentEnd = multilineScan.nextQuote
      ? findTomlMultilineValueEnd(config, offset + line.length, multilineScan.nextQuote)
      : offset + line.length
    return config.slice(0, offset) + replacement + config.slice(assignmentEnd)
  }

  const sectionStart = findFirstTableStart(config)
  const root = config.slice(0, sectionStart).trimEnd()
  const suffix = config.slice(sectionStart)
  const replacement = `${root}${root.length > 0 ? "\n" : ""}${keyPath} = ${value}\n`
  if (suffix.length === 0) return replacement
  return `${replacement.trimEnd()}\n\n${suffix.trimStart()}`
}

export function appendBlock(config: string, block: string): string {
  const prefix = config.trimEnd()
  return `${prefix}${prefix.length > 0 ? "\n\n" : ""}${block.trimEnd()}\n`
}

function findFirstTableStart(config: string): number {
  const lines = config.match(/[^\n]*\n?|$/g) ?? []
  let offset = 0
  let multilineQuote: TomlMultilineQuote | null = null
  for (const line of lines) {
    if (line.length === 0) break
    const multilineScan = scanTomlMultilineLine(line, multilineQuote)
    multilineQuote = multilineScan.nextQuote
    if (multilineScan.wasInside) {
      offset += line.length
      continue
    }
    if (isTomlTableHeaderLine(line)) return offset
    offset += line.length
  }
  return config.length
}

function insertSetting(sectionText: string, key: string, value: string): string {
  const lines = sectionText.split("\n")
  lines.splice(1, 0, `${key} = ${value}`)
  return lines.join("\n")
}

export function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

function tomlTableHeaderMatches(line: string, headerLine: string, targetHeaderPath: readonly string[] | null): boolean {
  const normalizedLine = stripUnquotedInlineComment(line).trim()
  if (normalizedLine === headerLine) return true
  if (!targetHeaderPath) return false
  const candidateHeaderPath = parseTomlTableHeader(normalizedLine)
  if (!candidateHeaderPath || candidateHeaderPath.length !== targetHeaderPath.length) return false
  return candidateHeaderPath.every((part, index) => part === targetHeaderPath[index])
}

function parseTomlTableHeader(line: string): readonly string[] | null {
  const normalizedLine = stripUnquotedInlineComment(line).trim()
  if (!normalizedLine.startsWith("[") || !normalizedLine.endsWith("]") || normalizedLine.startsWith("[[")) return null
  return parseTomlDottedKey(normalizedLine.slice(1, -1).trim())
}

export function isTomlTableHeaderLine(line: string): boolean {
  const normalizedLine = stripUnquotedInlineComment(line).trim()
  return normalizedLine.startsWith("[") && normalizedLine.endsWith("]")
}

export function scanTomlMultilineLine(
  line: string,
  currentQuote: TomlMultilineQuote | null,
): TomlMultilineLineScan {
  if (currentQuote) {
    return {
      wasInside: true,
      nextQuote: findTomlMultilineDelimiter(line, currentQuote, 0) === -1 ? currentQuote : null,
    }
  }

  let quote: "'" | '"' | null = null
  let index = 0
  while (index < line.length) {
    const char = line[index]
    if (quote === '"') {
      if (char === "\\") {
        index += 2
        continue
      }
      if (char === '"') quote = null
      index += 1
      continue
    }
    if (quote === "'") {
      if (char === "'") quote = null
      index += 1
      continue
    }
    if (char === "#") break
    const delimiter = line.startsWith('"""', index) ? '"""' : line.startsWith("'''", index) ? "'''" : null
    if (delimiter) {
      const closingIndex = findTomlMultilineDelimiter(line, delimiter, index + delimiter.length)
      return { wasInside: false, nextQuote: closingIndex === -1 ? delimiter : null }
    }
    if (char === '"' || char === "'") quote = char
    index += 1
  }
  return { wasInside: false, nextQuote: null }
}

function findTomlMultilineDelimiter(line: string, delimiter: TomlMultilineQuote, startIndex: number): number {
  let index = line.indexOf(delimiter, startIndex)
  while (index !== -1) {
    if (delimiter === "'''" || countPrecedingBackslashes(line, index) % 2 === 0) return index
    index = line.indexOf(delimiter, index + 1)
  }
  return -1
}

function countPrecedingBackslashes(line: string, index: number): number {
  let count = 0
  let cursor = index - 1
  while (cursor >= 0 && line[cursor] === "\\") {
    count += 1
    cursor -= 1
  }
  return count
}

function findUnquotedAssignment(line: string): number {
  return findUnquotedCharacter(line, "=", 0)
}

function findUnquotedComment(line: string, startIndex: number): number {
  return findUnquotedCharacter(line, "#", startIndex)
}

function findUnquotedCharacter(line: string, target: "=" | "#", startIndex: number): number {
  let quote: "'" | '"' | null = null
  let index = startIndex
  while (index < line.length) {
    const char = line[index]
    if (quote === '"') {
      if (char === "\\") {
        index += 2
        continue
      }
      if (char === '"') quote = null
      index += 1
      continue
    }
    if (quote === "'") {
      if (char === "'") quote = null
      index += 1
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      index += 1
      continue
    }
    if (char === target) return index
    if (char === "#") return -1
    index += 1
  }
  return -1
}

function tomlPathMatches(candidate: readonly string[], target: readonly string[]): boolean {
  return candidate.length === target.length && candidate.every((part, index) => part === target[index])
}

function replaceTomlAssignmentValue(line: string, assignmentIndex: number, value: string): string {
  const newline = line.endsWith("\n") ? "\n" : ""
  const lineBody = newline ? line.slice(0, -1) : line
  const commentIndex = findUnquotedComment(lineBody, assignmentIndex + 1)
  const comment = commentIndex === -1 ? "" : ` ${lineBody.slice(commentIndex).trimStart()}`
  return `${lineBody.slice(0, assignmentIndex + 1)} ${value}${comment}${newline}`
}

function findTomlMultilineValueEnd(text: string, startOffset: number, quote: TomlMultilineQuote): number {
  const lines = text.slice(startOffset).match(/[^\n]*\n?|$/g) ?? []
  let offset = startOffset
  let currentQuote: TomlMultilineQuote | null = quote
  for (const line of lines) {
    if (line.length === 0) break
    const scan = scanTomlMultilineLine(line, currentQuote)
    currentQuote = scan.nextQuote
    offset += line.length
    if (currentQuote === null) return offset
  }
  return text.length
}

function stripUnquotedInlineComment(line: string): string {
  let quote: "'" | '"' | null = null
  let index = 0
  while (index < line.length) {
    const char = line[index]
    if (quote === '"') {
      if (char === "\\") {
        index += 2
        continue
      }
      if (char === '"') quote = null
      index += 1
      continue
    }
    if (quote === "'") {
      if (char === "'") quote = null
      index += 1
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      index += 1
      continue
    }
    if (char === "#") return line.slice(0, index)
    index += 1
  }
  return line
}

export function parseTomlDottedKey(input: string): readonly string[] | null {
  const parts: string[] = []
  let index = 0
  while (index < input.length) {
    index = skipWhitespace(input, index)
    const parsedKey = parseTomlKeyPart(input, index)
    if (!parsedKey) return null
    parts.push(parsedKey.value)
    index = skipWhitespace(input, parsedKey.nextIndex)
    if (index === input.length) return parts
    if (input[index] !== ".") return null
    index += 1
  }
  return parts.length > 0 ? parts : null
}

function parseTomlKeyPart(input: string, startIndex: number): { readonly value: string; readonly nextIndex: number } | null {
  const quote = input[startIndex]
  if (quote === "'") return parseLiteralTomlString(input, startIndex)
  if (quote === '"') return parseBasicTomlString(input, startIndex)
  return parseBareTomlKey(input, startIndex)
}

function parseLiteralTomlString(
  input: string,
  startIndex: number,
): { readonly value: string; readonly nextIndex: number } | null {
  let index = startIndex + 1
  let value = ""
  while (index < input.length) {
    const char = input[index]
    if (char === "'") return { value, nextIndex: index + 1 }
    value += char
    index += 1
  }
  return null
}

function parseBasicTomlString(
  input: string,
  startIndex: number,
): { readonly value: string; readonly nextIndex: number } | null {
  let index = startIndex + 1
  let value = ""
  while (index < input.length) {
    const char = input[index]
    if (char === '"') return { value, nextIndex: index + 1 }
    if (char !== "\\") {
      value += char
      index += 1
      continue
    }
    const escaped = parseBasicTomlEscape(input, index)
    if (!escaped) return null
    value += escaped.value
    index = escaped.nextIndex
  }
  return null
}

function parseBasicTomlEscape(
  input: string,
  backslashIndex: number,
): { readonly value: string; readonly nextIndex: number } | null {
  const escape = input[backslashIndex + 1]
  if (escape === undefined) return null
  if (escape === "b") return { value: "\b", nextIndex: backslashIndex + 2 }
  if (escape === "t") return { value: "\t", nextIndex: backslashIndex + 2 }
  if (escape === "n") return { value: "\n", nextIndex: backslashIndex + 2 }
  if (escape === "f") return { value: "\f", nextIndex: backslashIndex + 2 }
  if (escape === "r") return { value: "\r", nextIndex: backslashIndex + 2 }
  if (escape === '"') return { value: '"', nextIndex: backslashIndex + 2 }
  if (escape === "\\") return { value: "\\", nextIndex: backslashIndex + 2 }
  if (escape === "u") return parseUnicodeEscape(input, backslashIndex + 2, 4)
  if (escape === "U") return parseUnicodeEscape(input, backslashIndex + 2, 8)
  return null
}

function parseUnicodeEscape(
  input: string,
  digitsStart: number,
  digitCount: number,
): { readonly value: string; readonly nextIndex: number } | null {
  const digits = input.slice(digitsStart, digitsStart + digitCount)
  if (digits.length !== digitCount || !/^[0-9A-Fa-f]+$/.test(digits)) return null
  const codePoint = Number.parseInt(digits, 16)
  if (codePoint > 0x10ffff) return null
  return { value: String.fromCodePoint(codePoint), nextIndex: digitsStart + digitCount }
}

function parseBareTomlKey(input: string, startIndex: number): { readonly value: string; readonly nextIndex: number } | null {
  let index = startIndex
  while (index < input.length && /[A-Za-z0-9_-]/.test(input[index])) index += 1
  if (index === startIndex) return null
  return { value: input.slice(startIndex, index), nextIndex: index }
}

function skipWhitespace(input: string, startIndex: number): number {
  let index = startIndex
  while (index < input.length && /\s/.test(input[index])) index += 1
  return index
}

import { parseTomlDottedKey, scanTomlMultilineLine, type TomlMultilineQuote } from "./toml-section-editor"

export function hasTomlSetting(config: string, keyPath: string): boolean {
  const targetPath = parseTomlDottedKey(keyPath)
  if (!targetPath) return false

  return hasTomlAssignment(config, (tablePath, settingPath) => {
    const fullPath = [...tablePath, ...settingPath]
    return fullPath.length === targetPath.length && fullPath.every((part, index) => part === targetPath[index])
  })
}

export function hasTomlRootDottedKeyPrefix(config: string, rootKey: string): boolean {
  return hasTomlAssignment(
    config,
    (tablePath, settingPath) => tablePath.length === 0 && settingPath.length > 1 && settingPath[0] === rootKey,
  )
}

function hasTomlAssignment(
  config: string,
  predicate: (tablePath: readonly string[], settingPath: readonly string[]) => boolean,
): boolean {
  let tablePath: readonly string[] | null = []
  let multilineQuote: TomlMultilineQuote | null = null
  for (const line of config.split("\n")) {
    const multilineScan = scanTomlMultilineLine(line, multilineQuote)
    multilineQuote = multilineScan.nextQuote
    if (multilineScan.wasInside) continue
    const normalizedLine = stripUnquotedInlineComment(line).trim()
    if (normalizedLine.length === 0) continue

    const headerPath = parseTomlTableHeader(normalizedLine)
    if (headerPath) {
      tablePath = headerPath
      continue
    }
    if (isTomlTableHeaderLine(normalizedLine)) {
      tablePath = null
      continue
    }
    if (!tablePath) continue

    const assignmentIndex = findUnquotedAssignment(normalizedLine)
    if (assignmentIndex < 0) continue
    const settingPath = parseTomlDottedKey(normalizedLine.slice(0, assignmentIndex).trim())
    if (!settingPath) continue
    if (predicate(tablePath, settingPath)) return true
  }
  return false
}

function parseTomlTableHeader(line: string): readonly string[] | null {
  if (!line.startsWith("[") || !line.endsWith("]") || line.startsWith("[[")) return null
  return parseTomlDottedKey(line.slice(1, -1).trim())
}

function isTomlTableHeaderLine(line: string): boolean {
  return line.startsWith("[") && line.endsWith("]")
}

function stripUnquotedInlineComment(line: string): string {
  let quote: "'" | '"' | null = null
  let index = 0
  while (index < line.length) {
    const char = line[index]
    if (quote === '"') {
      if (char === "\\") {
        index += 2
        continue
      }
      if (char === '"') quote = null
      index += 1
      continue
    }
    if (quote === "'") {
      if (char === "'") quote = null
      index += 1
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      index += 1
      continue
    }
    if (char === "#") return line.slice(0, index)
    index += 1
  }
  return line
}

function findUnquotedAssignment(line: string): number {
  let quote: "'" | '"' | null = null
  let index = 0
  while (index < line.length) {
    const char = line[index]
    if (quote === '"') {
      if (char === "\\") {
        index += 2
        continue
      }
      if (char === '"') quote = null
      index += 1
      continue
    }
    if (quote === "'") {
      if (char === "'") quote = null
      index += 1
      continue
    }
    if (char === '"' || char === "'") {
      quote = char
      index += 1
      continue
    }
    if (char === "=") return index
    index += 1
  }
  return -1
}

